// Lógica Central do CRM de Cobrança Moura Leite
// Moura Leite Loteamentos - ERP Sienge & Azure AD Integration

// Interceptador Global de Fetch para rotear o Sienge Proxy e Rotas API para a Vercel/Firebase
(function() {
  const originalSetItem = localStorage.setItem;
  localStorage.setItem = function(key, value) {
      if (key === "crm_moura_notes") {
          window.agendaItemsCache = null;
      }
      originalSetItem.apply(this, arguments);
  };

  let originalSaveNotesToFirebase = null;
  Object.defineProperty(window, 'saveNotesToFirebase', {
      set: function(val) { originalSaveNotesToFirebase = val; },
      get: function() {
          if (!originalSaveNotesToFirebase) return undefined;
          return function() {
              window.agendaItemsCache = null;
              return originalSaveNotesToFirebase.apply(this, arguments);
          };
      },
      configurable: true
  });
})();
(function() {
  const _origFetch = window.fetch;
  window.fetch = async function() {
    var args = Array.prototype.slice.call(arguments);
    if (typeof args[0] === 'string') {
      if (args[0].includes('/sienge-proxy')) {
        args[0] = args[0].replace(/http:\/\/[^:\/]+(:\d+)?\/sienge-proxy/g, '/api/sienge-proxy');
        args[0] = args[0].replace(window.location.origin + '/sienge-proxy', '/api/sienge-proxy');
      }
    }
    return _origFetch.apply(this, args);
  };
})();
// Override lucide.createIcons para evitar que ícones inválidos travem o app
if (typeof lucide !== 'undefined' && typeof lucide.createIcons === 'function') {
  const originalCreateIcons = lucide.createIcons;
  lucide.createIcons = function(options) {
    try {
      originalCreateIcons(options);
    } catch (e) {
      console.warn("Lucide icon error intercepted:", e);
    }
  };
}

// getDynamicOperators was removed from here because it is defined at the end of the file.

window.updateOperatorTabsUI = function() {
  const dynOps = window.getDynamicOperators();
  
  const filaTabs = document.getElementById("operator-tabs-container");
  if (filaTabs) {
     // Remover botões de operador existentes
     const existingOpBtns = filaTabs.querySelectorAll(".operator-tab-btn");
     existingOpBtns.forEach(btn => btn.remove());
     
     // Criar e inserir novos botões no início
     let opBtnsHtml = `<button class="operator-tab-btn active" data-operator="TODOS">TODOS</button>`;
     dynOps.forEach(op => {
         opBtnsHtml += `<button class="operator-tab-btn" data-operator="${op}">${op}</button>`;
     });
     opBtnsHtml += `<button class="operator-tab-btn" data-operator="NÃO ATRIBUÍDO">NÃO ATRIBUÍDO</button>`;
     
     filaTabs.insertAdjacentHTML('afterbegin', opBtnsHtml);
  }

  const _cu = window.AppState ? window.AppState.currentUser : null;
  const isAdmin = (_cu && (
      (_cu.role && _cu.role.toUpperCase().includes('ADMIN')) || 
      (_cu.profile_name && (_cu.profile_name.toUpperCase().includes('ADMIN') || _cu.profile_name.toUpperCase().includes('GESTOR') || _cu.profile_name.toUpperCase().includes('GERENTE'))) ||
      (_cu.email && (_cu.email.toLowerCase() === 'admin@mouraleite.com.br' || _cu.email.toLowerCase() === 'israel@mouraleite.com.br' || _cu.email.toLowerCase() === 'atendimento@mouraleite.com.br')) ||
      (_cu.name && _cu.name.toUpperCase().includes('ISRAEL'))
  ));

  const agendaTabs = document.getElementById("agenda-operator-tabs-container");
  const agendaSelect = document.getElementById("agenda-operator-select");

  if (agendaTabs) {
     if (isAdmin) {
         console.log("updateOperatorTabsUI - isAdmin is TRUE. Showing agenda dropdown for admin.");
         agendaTabs.style.cssText = "display: none !important;"; // Hide tabs, prefer select for admin
         if(agendaSelect) agendaSelect.style.display = "block"; // Show select dropdown
         
         if (!window.AgendaSelectedOperator) window.AgendaSelectedOperator = "Todos";
     } else {
         console.log("updateOperatorTabsUI - isAdmin is FALSE. Hiding agenda tabs. User:", window.AppState ? window.AppState.currentUser : null);
         agendaTabs.style.cssText = "display: none !important;";
         const _cu = window.AppState && window.AppState.currentUser;
         if (_cu) {
             const opName = _cu.sienge_user
                 ? _cu.sienge_user.toUpperCase().replace(/\./g, ' ').trim()
                 : (_cu.name ? _cu.name.toUpperCase() : '');
             if (opName) window.AgendaSelectedOperator = opName;
         }
     }
  }

  const agendaSelect = document.getElementById("agenda-operator-select");
  if (agendaSelect) {
     agendaSelect.innerHTML = `<option value="Todos">Todos os Operadores</option>`;
     dynOps.forEach(op => {
         agendaSelect.innerHTML += `<option value="${op}">${op}</option>`;
     });
     agendaSelect.innerHTML += `<option value="NÃO ATRIBUÍDO">NÃO ATRIBUÍDO</option>`;
  }
};

document.addEventListener("DOMContentLoaded", () => {
    window.updateOperatorTabsUI();
});

