window.GlobalCustomerCache = {
    data: [],
    status: 'idle', // idle, loading, done
    loadedCount: 0,
    totalCount: 1,
    syncStarted: false
};

const IdbCustomerCache = {
    dbName: 'CrmAppDB',
    storeName: 'CustomerCache',
    openDB() {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(this.dbName, 1);
            request.onupgradeneeded = e => e.target.result.createObjectStore(this.storeName);
            request.onsuccess = e => resolve(e.target.result);
            request.onerror = e => reject(e.target.error);
        });
    },
    async get(key) {
        try {
            const db = await this.openDB();
            if (!db.objectStoreNames.contains(this.storeName)) return null;
            return new Promise((resolve, reject) => {
                const tx = db.transaction(this.storeName, 'readonly');
                const req = tx.objectStore(this.storeName).get(key);
                req.onsuccess = () => resolve(req.result);
                req.onerror = () => reject(req.error);
            });
        } catch(e) { return null; }
    },
    async set(key, val) {
        try {
            const db = await this.openDB();
            return new Promise((resolve, reject) => {
                const tx = db.transaction(this.storeName, 'readwrite');
                const req = tx.objectStore(this.storeName).put(val, key);
                req.onsuccess = () => resolve();
                req.onerror = () => reject(req.error);
            });
        } catch(e) {}
    }
};

window.startCustomerBackgroundSync = async function(force = false, quiet = false) {
    if (window.GlobalCustomerCache.syncStarted && !force) return;
    
    if (force) {
        window.GlobalCustomerCache.syncStarted = false;
        window.GlobalCustomerCache.status = 'idle';
    }
    
    const container = document.getElementById('customer-sync-container');
    if (container && !quiet) container.style.display = 'flex';
    const textEl = document.getElementById('customer-sync-text');
    if (textEl) textEl.style.color = '#6b7280';
    const progEl = document.getElementById('customer-sync-progress');
    
    if (!force) {
        try {
            const cachedData = await IdbCustomerCache.get('crm_customer_cache');
            if (cachedData && cachedData.data && cachedData.data.length > 0) {
                let lastSync = cachedData.syncTimestamp ? new Date(cachedData.syncTimestamp) : new Date(0);
                const now = new Date();
                let targetSyncTime = new Date();
                targetSyncTime.setHours(8, 0, 0, 0);
                if (now < targetSyncTime) targetSyncTime.setDate(targetSyncTime.getDate() - 1);
                
                window.GlobalCustomerCache.data = cachedData.data;
                window.GlobalCustomerCache.totalCount = cachedData.totalCount || cachedData.data.length;
                window.GlobalCustomerCache.loadedCount = cachedData.data.length;
                
                ['nome', 'telefone', 'email'].forEach(type => {
                    const el = document.getElementById(`relacionamento-filter-${type}`);
                    if (el) { el.disabled = false; el.placeholder = "Digite para buscar..."; }
                });
                
                if (lastSync >= targetSyncTime) {
                    window.GlobalCustomerCache.status = 'done';
                    window.GlobalCustomerCache.syncStarted = true;
                    console.log(`Loaded ${cachedData.data.length} customers from local cache. Next sync at 08:00 AM.`);
                    if (container) container.style.display = 'none';
                    return;
                }
            }
        } catch(e) { console.error("Erro ao ler cache do IndexedDB:", e); }
    }

    window.GlobalCustomerCache.syncStarted = true;
    window.GlobalCustomerCache.status = 'loading';
    
    const setDynamicFieldsState = (disabled, placeholder) => {
        ['nome', 'telefone', 'email'].forEach(type => {
            const el = document.getElementById(`relacionamento-filter-${type}`);
            if (el) { el.disabled = disabled; el.placeholder = placeholder; }
        });
    };
    
    if (!window.GlobalCustomerCache.data || window.GlobalCustomerCache.data.length === 0) {
        setDynamicFieldsState(true, "Carregando base do Firebase...");
    }
    
    try {
        if (textEl && progEl) {
            textEl.innerText = `Buscando no Firebase...`;
            progEl.style.width = `10%`;
        }

        // Se for force manual (clicou no botão), primeiro chama o worker para buscar Sienge -> Firebase
        if (force && !quiet) {
            if (textEl && progEl) {
                textEl.innerText = `Sincronizando Sienge -> Firebase...`;
                progEl.style.width = `30%`;
            }
            try {
                await fetch('/api/sync-customers');
            } catch(e) {
                console.warn('Erro ao acionar cron de sync-customers manualmente:', e);
            }
        }
        
        if (!window.firebaseDb || !window.firebaseCollections) {
            throw new Error("Firebase SDK não inicializado.");
        }

        if (textEl && progEl) {
            textEl.innerText = `Baixando base atualizada...`;
            progEl.style.width = `60%`;
        }

        // Baixa a base completa do Firebase (rápido e não depende da lentidão do Sienge)
        const colRef = window.firebaseCollections.collection(window.firebaseDb, 'sienge_customers');
        const snapshot = await window.firebaseCollections.getDocs(colRef);
        
        let tempData = [];
        snapshot.forEach(doc => {
            const c = doc.data();
            tempData.push({
                id: c.id || c.customerId,
                name: c.name || c.customerName || c.clientName || 'Sem Nome',
                cpfCnpj: c.cpfCnpj || c.document || '',
                cpf: c.cpf,
                cnpj: c.cnpj,
                birthDate: c.birthDate,
                email: c.email,
                phone: c.phone,
                phones: c.phones ? c.phones.map(p => ({
                    areaCode: p.areaCode,
                    number: p.number || p.phoneNumber
                })) : undefined
            });
        });

        if (tempData.length > 0) {
            window.GlobalCustomerCache.data = tempData;
            window.GlobalCustomerCache.loadedCount = tempData.length;
            window.GlobalCustomerCache.totalCount = tempData.length;
        }
        
        window.GlobalCustomerCache.status = 'done';
        setDynamicFieldsState(false, "Digite para buscar...");
        
        if (!quiet && textEl && progEl) {
            textEl.innerText = `Base atualizada!`;
            textEl.style.color = 'var(--color-primary)';
            progEl.style.width = `100%`;
            setTimeout(() => { if (container) container.style.display = 'none'; }, 3000);
        }

        try {
            await IdbCustomerCache.set('crm_customer_cache', {
                syncTimestamp: new Date().toISOString(),
                date: new Date().toLocaleDateString(),
                data: tempData,
                totalCount: tempData.length
            });
        } catch(e) {
            console.warn("Não foi possível salvar cache no IndexedDB.", e);
        }
        
    } catch(e) {
        console.error("Erro no sync de clientes do Firebase:", e);
        window.GlobalCustomerCache.status = 'error';
        setDynamicFieldsState(false, "Falha na busca");
        if (textEl) textEl.innerText = `Erro ao sincronizar base.`;
    }
};

window.handleAgendaAutocomplete = function(query) {
    if (!window.GlobalCustomerCache || !window.GlobalCustomerCache.data) return;
    
    if (window._agendaSearchTimeout) clearTimeout(window._agendaSearchTimeout);
    
    window._agendaSearchTimeout = setTimeout(() => {
        let matches = [];
        const normalizeStr = str => str ? String(str).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "") : '';
        const qNorm = normalizeStr(query);
        
        if (!qNorm) {
            const dropdown = document.getElementById('custom-dropdown-agenda');
            if (dropdown) dropdown.style.display = 'none';
            return;
        }
        
        const terms = qNorm.split(' ').filter(t => t.trim() !== '');
        matches = window.GlobalCustomerCache.data.filter(c => {
            const cName = normalizeStr(c.name);
            return terms.every(term => cName.includes(term));
        });
        
        const inputEl = document.getElementById('agenda-search-input');
        if (!inputEl) return;
        
        let dropdown = document.getElementById('custom-dropdown-agenda');
        if (!dropdown) {
            dropdown = document.createElement('div');
            dropdown.id = 'custom-dropdown-agenda';
            dropdown.style.position = 'absolute';
            dropdown.style.background = 'white';
            dropdown.style.border = '1px solid #ccc';
            dropdown.style.borderRadius = '4px';
            dropdown.style.maxHeight = '200px';
            dropdown.style.overflowY = 'auto';
            dropdown.style.zIndex = '1000';
            dropdown.style.boxShadow = '0 4px 6px rgba(0,0,0,0.1)';
            
            inputEl.parentNode.style.position = 'relative';
            inputEl.parentNode.appendChild(dropdown);
            
            inputEl.addEventListener('blur', () => {
                setTimeout(() => { if (dropdown) dropdown.style.display = 'none'; }, 200);
            });
            inputEl.addEventListener('focus', () => {
                if (dropdown && dropdown.children.length > 0) dropdown.style.display = 'block';
            });
        }
        
        dropdown.innerHTML = '';
        matches.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
        const topMatches = matches.slice(0, 100);
        
        if (topMatches.length === 0) {
            dropdown.style.display = 'none';
            return;
        }
        
        dropdown.style.display = 'block';
        dropdown.style.width = '100%';
        dropdown.style.top = '100%';
        dropdown.style.left = '0';
        
        topMatches.forEach(c => {
            const label = `${c.id} - ${c.name}`;
            const item = document.createElement('div');
            item.style.padding = '8px 12px';
            item.style.cursor = 'pointer';
            item.style.borderBottom = '1px solid #f3f4f6';
            item.style.fontSize = '0.85rem';
            item.style.color = '#333';
            item.innerText = label;
            
            item.onmouseover = () => item.style.backgroundColor = '#f0fdf4';
            item.onmouseout = () => item.style.backgroundColor = 'transparent';
            
            item.onclick = () => {
                inputEl.value = c.name;
                dropdown.style.display = 'none';
                if(typeof renderAgendaAlerts === 'function') renderAgendaAlerts();
            };
            
            dropdown.appendChild(item);
        });
    }, 200);
};

window.handleDynamicCustomerSearch = function(query, type) {
    window.SelectedDynamicCustomerId = null;
    window.SelectedDynamicCustomerName = null;
    window.SelectedDynamicCustomerDoc = null;
    
    if (!window.GlobalCustomerCache || !window.GlobalCustomerCache.data) return;
    
    // Máscara para Telefone
    if (type === 'telefone') {
        const inputEl = document.getElementById('relacionamento-filter-telefone');
        if (inputEl && query && !window._maskingPhone) {
            window._maskingPhone = true;
            let v = query.replace(/\D/g, "");
            if (v.length > 0) {
                if (v.length <= 10) {
                    v = v.replace(/^(\d{2})(\d)/g, "($1) $2");
                    v = v.replace(/(\d{4})(\d)/, "$1-$2");
                } else {
                    v = v.replace(/^(\d{2})(\d)/g, "($1) $2");
                    v = v.replace(/(\d{5})(\d)/, "$1-$2");
                }
                v = v.substring(0, 15);
            }
            inputEl.value = v;
            query = v;
            window._maskingPhone = false;
        }
    }

    if (window._dynamicSearchTimeout) clearTimeout(window._dynamicSearchTimeout);
    
    window._dynamicSearchTimeout = setTimeout(() => {
        let matches = [];
        const normalizeStr = str => str ? String(str).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "") : '';
        const qNorm = normalizeStr(query);
        
        if (!qNorm) {
            const dropdown = document.getElementById(`custom-dropdown-${type}`);
            if (dropdown) dropdown.style.display = 'none';
            return;
        }
        
        if (type === 'nome') {
            const terms = qNorm.split(' ').filter(t => t.trim() !== '');
            matches = window.GlobalCustomerCache.data.filter(c => {
                const cName = normalizeStr(c.name);
                return terms.every(term => cName.includes(term));
            });
        } else if (type === 'telefone') {
            const qNum = query.replace(/\D/g, '');
            if (qNum.length >= 4) {
                matches = window.GlobalCustomerCache.data.filter(c => {
                    const phones = c.phones || [];
                    return phones.some(p => {
                        const fullNum = String(p.areaCode || '') + String(p.number || p.phoneNumber || '');
                        return fullNum.replace(/\D/g, '').includes(qNum);
                    });
                });
            }
        } else if (type === 'email') {
            matches = window.GlobalCustomerCache.data.filter(c => normalizeStr(c.email).includes(qNorm));
        }
        
        const inputEl = document.getElementById(`relacionamento-filter-${type}`);
        if (!inputEl) return;
        
        let dropdown = document.getElementById(`custom-dropdown-${type}`);
        if (!dropdown) {
            dropdown = document.createElement('div');
            dropdown.id = `custom-dropdown-${type}`;
            dropdown.style.position = 'absolute';
            dropdown.style.background = 'white';
            dropdown.style.border = '1px solid #ccc';
            dropdown.style.borderRadius = '4px';
            dropdown.style.maxHeight = '200px';
            dropdown.style.overflowY = 'auto';
            dropdown.style.zIndex = '1000';
            dropdown.style.boxShadow = '0 4px 6px rgba(0,0,0,0.1)';
            
            // Container needs relative positioning for absolute dropdown to work
            inputEl.parentNode.style.position = 'relative';
            inputEl.parentNode.appendChild(dropdown);
            
            inputEl.addEventListener('blur', () => {
                setTimeout(() => { if (dropdown) dropdown.style.display = 'none'; }, 200);
            });
            inputEl.addEventListener('focus', () => {
                if (dropdown && dropdown.children.length > 0) dropdown.style.display = 'block';
            });
        }
        
        dropdown.innerHTML = '';
        matches.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
        const topMatches = matches.slice(0, 500); // Exibe até 500 resultados para permitir busca completa
        
        if (topMatches.length === 0) {
            if (window.GlobalCustomerCache.status === 'loading') {
                dropdown.style.display = 'block';
                dropdown.style.width = '100%';
                dropdown.style.top = '100%';
                dropdown.style.left = '0';
                
                const item = document.createElement('div');
                item.style.padding = '8px 12px';
                item.style.fontSize = '0.85rem';
                item.style.color = '#64748b';
                item.style.fontStyle = 'italic';
                const perc = Math.min(100, Math.round(((window.GlobalCustomerCache.loadedCount || 0) / (window.GlobalCustomerCache.totalCount || 1)) * 100));
                item.innerHTML = `<i data-lucide="loader-2" class="spin" style="width:14px; height:14px; vertical-align:middle; margin-right:6px;"></i> Cliente não encontrado nos ${perc}% carregados. Aguarde o fim do download...`;
                dropdown.appendChild(item);
                if (typeof lucide !== 'undefined') lucide.createIcons();
            } else {
                dropdown.style.display = 'none';
            }
            return;
        }
        
        dropdown.style.display = 'block';
        dropdown.style.width = '100%';
        dropdown.style.top = '100%'; // directly below input
        dropdown.style.left = '0';
        
        topMatches.forEach(c => {
            const doc = c.cpf || c.cnpj || c.cpfCnpj || '';
            const maskedDoc = doc.length === 14 ? doc.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, '$1.$2.$3/$4-$5') : String(doc).replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
            const label = `${c.id} - ${c.name} - ${maskedDoc}`;
            
            const item = document.createElement('div');
            item.style.padding = '8px 12px';
            item.style.cursor = 'pointer';
            item.style.borderBottom = '1px solid #f3f4f6';
            item.style.fontSize = '0.85rem';
            item.style.color = '#333';
            item.innerText = label;
            
            item.onmouseover = () => item.style.background = '#f3f4f6';
            item.onmouseout = () => item.style.background = 'white';
            item.onmousedown = () => {
                if (type === 'nome') {
                    inputEl.value = c.name;
                } else if (type === 'email') {
                    inputEl.value = c.email || '';
                }
                // Se for telefone, não substituímos o campo com o nome do cliente. Mantemos o que foi digitado.
                dropdown.style.display = 'none';
                
                // Grava na memoria o ID do cliente em vez do CPF
                window.SelectedDynamicCustomerId = c.id;
                window.SelectedDynamicCustomerName = c.name;
                window.searchRelacionamento();
            };
            dropdown.appendChild(item);
        });
    }, 400);
};
// Lógica das Abas do Cliente
function switchCustomerTab(tabId) {
  if (tabId === 'tab-quitacao' && AppState.isCurrentContractPaid) {
    alert(AppState.currentPayoffMsg);
    return;
  }
  // Ocultar todos os painéis
  document.querySelectorAll('.customer-tab-pane').forEach(pane => {
    pane.style.display = 'none';
    pane.classList.remove('active');
  });
  
  // Remover active de todos os botões
  document.querySelectorAll('.customer-tab-btn').forEach(btn => {
    btn.classList.remove('active');
  });
  
  // Mostrar o painel selecionado
  const selectedPane = document.getElementById(tabId);
  if (selectedPane) {
    selectedPane.style.display = 'block';
    selectedPane.classList.add('active');
  }
  
  if (tabId === 'tab-ocorrencias') {
    if (typeof window.populatePromisedInstallmentsDropdown === 'function') {
      window.populatePromisedInstallmentsDropdown();
    }
    
    // Auto-fill form from cross-contract validation
    if (window.pendingOccurrenceClone) {
        const occ = window.pendingOccurrenceClone;
        const textEl = document.getElementById("note-text");
        const pDateEl = document.getElementById("note-promise-date");
        const selectEl = document.getElementById("note-reminder-select");
        const canalEl = document.getElementById("note-canal");
        
        if (textEl) textEl.value = occ.text || "";
        if (pDateEl && occ.promiseDate) pDateEl.value = occ.promiseDate;
        if (selectEl && occ.reminder) selectEl.value = occ.reminder;
        if (canalEl && occ.canal) canalEl.value = occ.canal;
        
        if (occ.iniciativa) {
            // Usually "Ativo" or "Receptivo"
            const rads = document.querySelectorAll('input[name="note-iniciativa"]');
            rads.forEach(r => {
                if (String(r.value).toUpperCase() === String(occ.iniciativa).toUpperCase()) {
                    r.checked = true;
                }
            });
        }
        
        if (typeof window.validateOccurrenceForm === 'function') {
            window.validateOccurrenceForm();
        }
        
        // Limpar clone para não preencher indevidamente em outras aberturas
        window.pendingOccurrenceClone = null;
    }
  }
  
  const activeBtn = document.querySelector(`.customer-tab-btn[data-target="${tabId}"]`);
  if (activeBtn) {
    activeBtn.classList.add('active');
  }

  if (tabId === 'tab-informe-rendimentos') {
    const yearInput = document.getElementById('informe-year');
    if (yearInput && !yearInput.value) {
      yearInput.value = new Date().getFullYear() - 1;
    }
  }
}

// Lógica das Abas da Ficha Cadastral
window.switchFichaTab = function(tabId) {
  document.querySelectorAll('.ficha-tab-pane').forEach(pane => {
    pane.style.display = 'none';
    pane.classList.remove('active');
  });
  
  document.querySelectorAll('.ficha-tab-btn').forEach(btn => {
    btn.classList.remove('active');
  });
  
  const selectedPane = document.getElementById(tabId);
  if (selectedPane) {
    selectedPane.style.display = 'block';
    selectedPane.classList.add('active');
  }
  
  const activeBtn = document.querySelector(`.ficha-tab-btn[data-target="${tabId}"]`);
  if (activeBtn) {
    activeBtn.classList.add('active');
  }
};

async function preloadCustomers(customerIds) {
  if (getSiengeApiMode() === "simulado") return;
  const uniqueIds = [...new Set(customerIds.filter(id => id != null))];
  const uncachedIds = uniqueIds.filter(id => !AppState.customers[id]);
  if (uncachedIds.length > 0) {
    const batchSize = 2;
    for (let i = 0; i < uncachedIds.length; i += batchSize) {
      const batch = uncachedIds.slice(i, i + batchSize);
      await Promise.all(batch.map(async (id) => {
        try {
          const cust = await SiengeApiService.getCustomer(id);
          if (cust) {
            AppState.customers[id] = cust;
          }
          const custSales = await SiengeApiService.getSales(id);
          if (custSales && custSales.length > 0) {
            if (!AppState.sales) AppState.sales = [];
            AppState.sales = AppState.sales.filter(s => String(s.customerId) !== String(id));
            AppState.sales.push(...custSales);
          }
        } catch (e) {
          console.error("Erro ao buscar cliente do Sienge " + id, e);
        }
      }));
      if (i + batchSize < uncachedIds.length) {
        await new Promise(resolve => setTimeout(resolve, 1000));
      }
    }
  }
}

function getCustomerFromState(id) {
  if (getSiengeApiMode() === "simulado") {
    return window.MOCK_DATA.CUSTOMERS[id] || null;
  }
  return AppState.customers[id] || { name: "Cliente Sienge " + id, phone: "N/D", cpfCnpj: "N/D", email: "N/D", address: "N/D" };
}


