window.showMockLoginModal = function(resolve, reject) {
  // O modal já está visível por causa do checkAuthentication.
  // Apenas configuramos o evento do botão para a lógica do simulador.
  const btn = document.getElementById("btn-submit-login");
  const emailInput = document.getElementById("login-email");
  const errorMsg = document.getElementById("login-error-msg");
  
  // Limpar onclick antigo se houver
  btn.onclick = null;
  
  btn.onclick = () => {
    const email = emailInput.value.trim();
    const name = email.split("@")[0].toUpperCase(); // Usa o começo do e-mail como nome fallback
    
    if (!MouraAuth.validateDomain(email)) {
      errorMsg.textContent = "Erro: O e-mail deve pertencer ao domínio @mouraleite.com.br";
      errorMsg.style.display = "block";
      return;
    }
    
    errorMsg.style.display = "none";
    
    const user = {
      name: name,
      email: email,
      isAuthenticated: true,
      method: "Simulado"
    };
    
    localStorage.setItem("crm_moura_user_session", JSON.stringify(user));
    resolve(user);
  };
};

function validateAndLoadCrmUser(user) {
  let crmUsers = [];
  try {
    crmUsers = JSON.parse(localStorage.getItem('crm_users')) || [];
  } catch(e) {}
  
  let matchedUser = crmUsers.find(u => u.email.toLowerCase() === user.email.toLowerCase());
  
  // Se o usuário não existir na base, vamos auto-registrar
  if (!matchedUser) {
    // israel@mouraleite.com.br é o super-admin padrão
    if (user.email.toLowerCase() === "israel@mouraleite.com.br") {
      matchedUser = {
        id: "usr_" + Date.now(),
        name: user.name,
        email: user.email.toLowerCase(),
        role: "ADMIN",
        status: "ATIVO",
        createdAt: new Date().toISOString()
      };
    } else {
      // Outros usuários entram como ATIVO automaticamente (OPERADOR)
      matchedUser = {
        id: "usr_" + Date.now(),
        name: user.name,
        email: user.email.toLowerCase(),
        role: "OPERADOR",
        status: "ATIVO",
        createdAt: new Date().toISOString()
      };
    }
    crmUsers.push(matchedUser);
    localStorage.setItem('crm_users', JSON.stringify(crmUsers));
  }
  
  if (matchedUser.status === "INATIVO") {
    throw new Error("Seu acesso foi desativado pelo Administrador.");
  }
  
  if (matchedUser.status === "PENDENTE") {
    // Se eles ficaram pendentes no passado, nós vamos auto-aprovar agora!
    matchedUser.status = "ATIVO";
    localStorage.setItem('crm_users', JSON.stringify(crmUsers));
  }
  
  // Mescla o perfil do CRM com o usuário logado
  return { ...user, ...matchedUser };
}

async function processSuccessfulLogin(loggedUser) {
  try {
    if (window.syncGlobalConfigFromFirebase) {
       await window.syncGlobalConfigFromFirebase();
    }
    const validatedUser = validateAndLoadCrmUser(loggedUser);
    AppState.currentUser = validatedUser;
    window.updateOperatorTabsUI();
    
    // Determine admin/gestor status based on role OR profile_name
    const _profileNameUp = (validatedUser.profile_name || '').toUpperCase();
    const _roleUp = (validatedUser.role || '').toUpperCase();
    const _isAdminOrGestor = _roleUp.includes('ADMIN') ||
        _profileNameUp.includes('ADMIN') ||
        _profileNameUp.includes('GESTOR') ||
        _profileNameUp.includes('GERENTE') ||
        (validatedUser.email && (validatedUser.email === 'admin@mouraleite.com.br' || validatedUser.email === 'israel@mouraleite.com.br'));

    if (_isAdminOrGestor) {
        window.AgendaSelectedOperator = "Todos";
    } else {
        // Use sienge_user name if available (matches how occ.author is stored)
        const opName = validatedUser.sienge_user
            ? validatedUser.sienge_user.toUpperCase().replace(/\./g, ' ').trim()
            : (validatedUser.name ? validatedUser.name.toUpperCase() : "TODOS");
        window.AgendaSelectedOperator = opName;
    }
    if (typeof window.updateOperatorTabsUI === 'function') {
        window.updateOperatorTabsUI();
    }

    document.getElementById("login-modal-overlay").classList.remove("active");
    renderUserSession();
    await initializeApplication();
  } catch (err) {
    const errorMsg = document.getElementById("login-error-msg");
    if (errorMsg) {
      errorMsg.textContent = err.message;
      errorMsg.style.display = "block";
    } else {
      alert(err.message);
    }
    MouraAuth.logout();
  }
}

async function checkAuthentication() {
  const user = MouraAuth.getCurrentUser();
  if (!user) {
    const overlay = document.getElementById("login-modal-overlay");
    overlay.classList.add("active");
    
    const authConfig = MouraAuth.getAuthConfig();
    const btn = document.getElementById("btn-submit-login");
    
    if (authConfig.enabled) {
      // Azure AD habilitado: botão aciona MSAL Popup
      const emailInput = document.getElementById("login-email");
      const labelEl = document.querySelector(".login-label");
      if (emailInput) emailInput.style.display = "none";
      if (labelEl) labelEl.style.display = "none";
      
      btn.textContent = "Entrar com Microsoft";
      
      // Mostrar botão de forma isolada
      btn.style.display = "block";
      btn.style.marginTop = "20px";
      
      btn.onclick = () => {
        MouraAuth.login().then(async loggedUser => {
          await processSuccessfulLogin(loggedUser);
        }).catch(err => {
          const errorMsg = document.getElementById("login-error-msg");
          if (errorMsg) {
            errorMsg.textContent = "Falha no login com a Microsoft: " + err.message;
            errorMsg.style.display = "block";
          }
        });
      };
    } else {
      // Simulado: botão aciona a promessa de mock
      MouraAuth.login().then(async loggedUser => {
        await processSuccessfulLogin(loggedUser);
      }).catch(err => {
        // Mock falhou
      });
    }
  } else {
    await processSuccessfulLogin(user);
  }
}

function renderUserSession() {
  const nameEl = document.getElementById("logged-user-name");
  const emailEl = document.getElementById("logged-user-email");
  const avatarEl = document.getElementById("logged-user-avatar");
  const appContainer = document.getElementById("app-container");
  
  if (AppState.currentUser) {
    const safeName = AppState.currentUser.name || "Usuario";
    nameEl.textContent = safeName;
    emailEl.textContent = AppState.currentUser.email;
    avatarEl.textContent = safeName.substring(0, 2).toUpperCase();
    appContainer.style.display = "flex";
    
    // Atualizar badge do Azure
    const azureStatus = document.getElementById("azure-status");
    const authConfig = MouraAuth.getAuthConfig();
    if (authConfig.enabled) {
      azureStatus.innerHTML = `<i data-lucide="shield-check" style="width: 16px;"></i> Azure Real`;
      azureStatus.className = "auth-status-badge";
    } else {
      azureStatus.innerHTML = `<i data-lucide="shield-alert" style="width: 16px;"></i> Simulador Local`;
      azureStatus.className = "auth-status-badge";
      azureStatus.style.borderColor = "var(--color-secondary)";
      azureStatus.style.color = "var(--color-secondary)";
      azureStatus.style.backgroundColor = "var(--color-warning-glow)";
    }
    lucide.createIcons();
  }
}

// ----------------------------------------------------
// 4. INICIALIZAÇÃO DA APLICAÇÃO E DADOS
// ----------------------------------------------------
async function initializeApplication() {
  // Sincronizar configurações globais do Firebase para a memória local (Recarrega se precisar)
  if (window.syncGlobalConfigFromFirebase) {
      await window.syncGlobalConfigFromFirebase();
  }


  // Carregar dados armazenados localmente (SharePoint preambles & occurrences)
  AppState.preambles = JSON.parse(localStorage.getItem("crm_moura_preambles")) || window.MOCK_DATA.INITIAL_PREAMBLE_DATA;
  
  // --- INICIO MIGRACAO FIREBASE NOTES ---
  // Strategy: merge Firebase (source of truth for cloud) with localStorage (local fallback)
  // Firebase wins on a per-customer basis if the customer exists in Firebase.
  try {
     const localNotes = JSON.parse(localStorage.getItem("crm_moura_notes")) || {};
     if (window.firebaseDb && window.firebaseCollections) {
         const notesSnapshot = await window.firebaseCollections.getDocs(window.firebaseCollections.collection(window.firebaseDb, 'customer_notes'));
         const firebaseNotes = {};
         notesSnapshot.forEach(doc => {
             if (doc.data().notes && doc.data().notes.length > 0) {
                 firebaseNotes[doc.id] = doc.data().notes;
             }
         });
         // Merge: start with local notes, then override with Firebase notes (Firebase is authoritative)
         AppState.notes = { ...localNotes, ...firebaseNotes };
         if (Object.keys(AppState.notes).length === 0) {
             AppState.notes = window.MOCK_DATA.INITIAL_MOCK_NOTES || {};
         }
         console.log(`[Firebase] Notas carregadas: ${Object.keys(firebaseNotes).length} do Firebase, ${Object.keys(localNotes).length} locais. Total: ${Object.keys(AppState.notes).length} clientes.`);
         localStorage.setItem("crm_moura_notes", JSON.stringify(AppState.notes));
     } else {
         AppState.notes = localNotes.length > 0 ? localNotes : (window.MOCK_DATA.INITIAL_MOCK_NOTES || {});
     }
  } catch (e) {
     console.error("Erro ao buscar notas do Firebase:", e);
     AppState.notes = JSON.parse(localStorage.getItem("crm_moura_notes")) || window.MOCK_DATA.INITIAL_MOCK_NOTES || {};
  }
  
  window.saveNotesToFirebase = async function(customerId) {
      localStorage.setItem("crm_moura_notes", JSON.stringify(AppState.notes));
      if (window.firebaseDb && window.firebaseCollections) {
          try {
              if (customerId) {
                 const docRef = window.firebaseCollections.doc(window.firebaseDb, 'customer_notes', String(customerId));
                 window.firebaseCollections.setDoc(docRef, { notes: AppState.notes[customerId] || [] }, { merge: true }).catch(e => console.error(e));
              } else {
                 for (const custId of Object.keys(AppState.notes)) {
                    const docRef = window.firebaseCollections.doc(window.firebaseDb, 'customer_notes', String(custId));
                    window.firebaseCollections.setDoc(docRef, { notes: AppState.notes[custId] || [] }, { merge: true }).catch(e => console.error(e));
                 }
              }
          } catch(e) {
              console.error('Erro ao salvar notas no Firebase', e);
          }
      }
  };
  // --- FIM MIGRACAO FIREBASE NOTES ---
  
  // --- INICIO MIGRACAO FIREBASE JUD NOTES & AGENDA NOTES ---
  try {
     if (window.firebaseDb && window.firebaseCollections) {
         // Jud Notes
         const judSnapshot = await window.firebaseCollections.getDocs(window.firebaseCollections.collection(window.firebaseDb, 'jud_notes'));
         AppState.judNotes = {};
         judSnapshot.forEach(doc => { AppState.judNotes[doc.id] = doc.data().notes || []; });
         if (Object.keys(AppState.judNotes).length === 0) {
             AppState.judNotes = JSON.parse(localStorage.getItem("crm_moura_jud_notes")) || {};
         }
         localStorage.setItem("crm_moura_jud_notes", JSON.stringify(AppState.judNotes));
         
         // Agenda Personal Notes
         const agendaSnapshot = await window.firebaseCollections.getDocs(window.firebaseCollections.collection(window.firebaseDb, 'agenda_personal_notes'));
         let personalNotes = {};
         agendaSnapshot.forEach(doc => { personalNotes[doc.id] = doc.data().notes || []; });
         if (Object.keys(personalNotes).length === 0) {
             personalNotes = JSON.parse(localStorage.getItem("crm_agenda_personal_notes")) || {};
         }
         localStorage.setItem("crm_agenda_personal_notes", JSON.stringify(personalNotes));

         // Agenda Recurring Notes
         const recurringSnapshot = await window.firebaseCollections.getDocs(window.firebaseCollections.collection(window.firebaseDb, 'agenda_recurring_notes'));
         let recurringNotes = {};
         recurringSnapshot.forEach(doc => { recurringNotes[doc.id] = doc.data().notes || []; });
         if (Object.keys(recurringNotes).length === 0) {
             recurringNotes = JSON.parse(localStorage.getItem("crm_agenda_recurring_notes")) || {};
         }
         localStorage.setItem("crm_agenda_recurring_notes", JSON.stringify(recurringNotes));
     } else {
         AppState.judNotes = JSON.parse(localStorage.getItem("crm_moura_jud_notes")) || {};
     }
  } catch (e) {
     console.error("Erro ao buscar jud_notes/agenda do Firebase:", e);
     AppState.judNotes = JSON.parse(localStorage.getItem("crm_moura_jud_notes")) || {};
  }
  
  window.saveJudNotesToFirebase = async function(customerId) {
      localStorage.setItem("crm_moura_jud_notes", JSON.stringify(AppState.judNotes));
      if (window.firebaseDb && window.firebaseCollections) {
          try {
              if (customerId) {
                 const docRef = window.firebaseCollections.doc(window.firebaseDb, 'jud_notes', String(customerId));
                 window.firebaseCollections.setDoc(docRef, { notes: AppState.judNotes[customerId] || [] }, { merge: true }).catch(e => console.error(e));
              } else {
                 for (const custId of Object.keys(AppState.judNotes)) {
                    const docRef = window.firebaseCollections.doc(window.firebaseDb, 'jud_notes', String(custId));
                    window.firebaseCollections.setDoc(docRef, { notes: AppState.judNotes[custId] || [] }, { merge: true }).catch(e => console.error(e));
                 }
              }
          } catch(e) {
              console.error('Erro ao salvar jud_notes no Firebase', e);
          }
      }
  };

  window.saveAgendaNotesToFirebase = async function() {
      const personalNotes = JSON.parse(localStorage.getItem("crm_agenda_personal_notes")) || {};
      const recurringNotes = JSON.parse(localStorage.getItem("crm_agenda_recurring_notes")) || {};
      if (window.firebaseDb && window.firebaseCollections) {
          try {
             for (const key of Object.keys(personalNotes)) {
                const docRef = window.firebaseCollections.doc(window.firebaseDb, 'agenda_personal_notes', key);
                window.firebaseCollections.setDoc(docRef, { notes: personalNotes[key] || [] }, { merge: true }).catch(e => console.error(e));
             }
             for (const key of Object.keys(recurringNotes)) {
                const docRef = window.firebaseCollections.doc(window.firebaseDb, 'agenda_recurring_notes', key);
                window.firebaseCollections.setDoc(docRef, { notes: recurringNotes[key] || [] }, { merge: true }).catch(e => console.error(e));
             }
          } catch(e) {
              console.error('Erro ao salvar agenda notes no Firebase', e);
          }
      }
  };
  // --- FIM MIGRACAO FIREBASE JUD NOTES & AGENDA NOTES ---

  // --- INICIALIZAÇÃO DE ESTADOS GLOBAIS (Timeline e Judiciais) ---
  const timelineStr = localStorage.getItem("crm_moura_timeline_nodes");
  window.TimelineState = timelineStr ? JSON.parse(timelineStr) : [
    { id: 'n1', dias: 15, acao: 'cob_interna', label: 'Início Cobrança Interna' },
    { id: 'n2', dias: 31, acao: 'cob_terceirizada', label: 'Início Terceirizada' },
    { id: 'n3', dias: 151, acao: 'juridico', label: 'Envio Jurídico' }
  ];
  if (!localStorage.getItem("crm_moura_timeline_v2")) {
      window.TimelineState = [
        { id: 'n1', dias: 15, acao: 'cob_interna', label: 'Início Cobrança Interna' },
        { id: 'n2', dias: 31, acao: 'cob_terceirizada', label: 'Início Terceirizada' },
        { id: 'n3', dias: 151, acao: 'juridico', label: 'Envio Jurídico' }
      ];
      localStorage.setItem("crm_moura_timeline_nodes", JSON.stringify(window.TimelineState));
      localStorage.setItem("crm_moura_timeline_v2", "true");
  }

  const judStr = localStorage.getItem("crm_moura_judiciais");
  window.EtapasJudiciaisState = judStr ? JSON.parse(judStr) : [
    { id: 'j1', nome: 'Not. Jud. via Carta', dias: 60, explicacao: "Notificação Judicial: Comunicação oficial da Justiça para informar alguém sobre um fato ou intenção jurídica, registrando formalmente a entrega da mensagem sem que haja um julgamento imediato." },
    { id: 'j2', nome: 'Not. Jud. via Ofic. de Justiça', dias: 60, explicacao: "Comunicação oficial entregue pessoalmente por um servidor público da Justiça, garantindo fé pública e comprovação legal imediata de que o destinatário tomou ciência do fato." },
    { id: 'j3', nome: 'Citação por Edital', dias: 120, explicacao: "Modalidade de citação utilizada quando o destinatário não é localizado, garantindo a comunicação oficial por meio de publicação pública." },
    { id: 'j4', nome: 'Homologação Acordo', dias: 15, explicacao: "Decisão judicial que confirma e valida formalmente um acordo firmado entre as partes, tornando seus termos legalmente reconhecidos." },
    { id: 'j5', nome: 'BACENJUD', dias: 120, explicacao: "Consulta ao sistema judicial para localizar informações e verificar a existência de ativos financeiros vinculados ao devedor, possibilitando eventual bloqueio de valores." }
  ];
  if (!localStorage.getItem("crm_moura_judiciais_v2")) {
      window.EtapasJudiciaisState = [
        { id: 'j1', nome: 'Not. Jud. via Carta', dias: 60, explicacao: "Notificação Judicial: Comunicação oficial da Justiça para informar alguém sobre um fato ou intenção jurídica, registrando formalmente a entrega da mensagem sem que haja um julgamento imediato." },
        { id: 'j2', nome: 'Not. Jud. via Ofic. de Justiça', dias: 60, explicacao: "Comunicação oficial entregue pessoalmente por um servidor público da Justiça, garantindo fé pública e comprovação legal imediata de que o destinatário tomou ciência do fato." },
        { id: 'j3', nome: 'Citação por Edital', dias: 120, explicacao: "Modalidade de citação utilizada quando o destinatário não é localizado, garantindo a comunicação oficial por meio de publicação pública." },
        { id: 'j4', nome: 'Homologação Acordo', dias: 15, explicacao: "Decisão judicial que confirma e valida formalmente um acordo firmado entre as partes, tornando seus termos legalmente reconhecidos." },
        { id: 'j5', nome: 'BACENJUD', dias: 120, explicacao: "Consulta ao sistema judicial para localizar informações e verificar a existência de ativos financeiros vinculados ao devedor, possibilitando eventual bloqueio de valores." }
      ];
      localStorage.setItem("crm_moura_judiciais", JSON.stringify(window.EtapasJudiciaisState));
      localStorage.setItem("crm_moura_judiciais_v2", "true");
  }
  // --- FIM ESTADOS GLOBAIS ---

  AppState.weSendStatus = JSON.parse(localStorage.getItem("crm_moura_wesend_status")) || {};
  AppState.rules = JSON.parse(localStorage.getItem("crm_moura_rules")) || INITIAL_RULES_CONFIG;
  if (!localStorage.getItem("crm_moura_rules")) {
    localStorage.setItem("crm_moura_rules", JSON.stringify(INITIAL_RULES_CONFIG));
  }
  
  // Migrar regras salvas do formato Nome Completo para Username Formatado (sem ponto)
  try {
     const savedUsersStr = localStorage.getItem('crm_users');
     if (savedUsersStr) {
         const nameMap = {};
         JSON.parse(savedUsersStr).forEach(u => {
             if (u.name && u.sienge_user) {
                 nameMap[u.name.toUpperCase()] = u.sienge_user.toUpperCase().replace(/\./g, ' ').trim();
             }
         });
         let changed = false;
         Object.values(AppState.rules).forEach(rule => {
             if (Array.isArray(rule.operator)) {
                 for (let i = 0; i < rule.operator.length; i++) {
                     if (nameMap[rule.operator[i]]) {
                         rule.operator[i] = nameMap[rule.operator[i]];
                         changed = true;
                     }
                 }
             } else if (typeof rule.operator === 'string' && nameMap[rule.operator]) {
                 rule.operator = nameMap[rule.operator];
                 changed = true;
             }
         });
         if (changed) {
             localStorage.setItem("crm_moura_rules", JSON.stringify(AppState.rules));
         }
     }
  } catch(e) {}
  
  // Atualizar badge da sidebar
  updateSidebarAgendaBadge();
  
  // Inicializar o seletor de API do Sienge
  const mode = getSiengeApiMode();
  const btnSimulado = document.getElementById("btn-mode-simulado");
  const btnReal = document.getElementById("btn-mode-real");
  if (btnSimulado) btnSimulado.classList.toggle("active", mode === "simulado");
  if (btnReal) btnReal.classList.toggle("active", mode === "real");
  try {
    await loadAndApplyPermissions();
    
    // Buscar tabelas auxiliares do Sienge (GET)
    AppState.companies = await SiengeApiService.getCompanies();
    const idxRes = await SiengeApiService.getIndexers();
    AppState.indexers = idxRes && idxRes.results ? idxRes.results : [];
    
    try {
      AppState.cachedCostCenters = await SiengeApiService.getCostCenters();
    } catch(e) {
      console.warn("Erro ao buscar cost centers na inicialização, usando mock:", e);
      AppState.cachedCostCenters = window.MOCK_DATA ? window.MOCK_DATA.COST_CENTERS : [];
    }
    if (typeof window.applyDynamicCityRules === 'function') {
      window.applyDynamicCityRules();
    }
    
    if (mode === "real") {
      AppState.units = {};
      AppState.remadeInstallments = {};
      AppState.paidBills = [];
    } else {
      AppState.units = window.MOCK_DATA.UNITS;
      AppState.remadeInstallments = window.MOCK_DATA.REMADE_INSTALLMENTS;
    }
    
    // Auto-filtrar a Agenda se for Operador
    const u = AppState.currentUser;
    if (u && ((u.profile_name && (u.profile_name.toUpperCase() === "OPERADOR COBRANÇA" || u.profile_name.toUpperCase() === "OPERADOR" || u.profile_name.toUpperCase() === "OPERADOR COBRANCA")) || u.role === "OPERADOR")) {
      const safeNameForOp = u.name || "";
      const opName = u.sienge_user ? u.sienge_user.toUpperCase().replace(/\./g, ' ').trim() : safeNameForOp.toUpperCase();
      if (typeof window.setAgendaOperator === 'function') {
        window.setAgendaOperator(opName);
      }
    }
    
    // Iniciar na aba padrão
    switchTab("dashboard");
  } catch (err) {
    console.error(err);
    alert("Falha na conexão com as APIs Sienge: " + err.message);
  }
}

async function loadAndApplyPermissions() {
  // Buscar permissões do usuário se estiver no modo real e logado
  if (AppState.currentUser && AppState.currentUser.email) {
    try {
      let profileId = AppState.currentUser.profile_name ? AppState.currentUser.profile_name.trim().toLowerCase().replace(/\s+/g, '_') : 'admin';
      let permsStr = localStorage.getItem('crm_perms_' + profileId);
      
      if (permsStr) {
         let permsObj = JSON.parse(permsStr);
         AppState.currentUser.permissions = Object.keys(permsObj).filter(k => permsObj[k] === true);
         
         // Forçar permissões de ADMIN para o Israel e Admin (fallback de segurança)
         if (AppState.currentUser.email && (AppState.currentUser.email.toLowerCase() === 'israel@mouraleite.com.br' || AppState.currentUser.email.toLowerCase() === 'admin@mouraleite.com.br')) {
             AppState.currentUser.permissions = ['anexos', 'config', 'config.tags', 'config.usuarios', 'contas.pagar'];
         }
      } else {
         console.warn("Permissões não encontradas no localStorage para o perfil:", profileId, "Aplicando padrão.");
         AppState.currentUser.permissions = ['anexos', 'config', 'config.tags', 'config.usuarios', 'contas.pagar'];
      }
    } catch (e) {
      console.error("Erro ao carregar permissões:", e);
      AppState.currentUser.permissions = ['anexos', 'config', 'config.tags', 'config.usuarios', 'contas.pagar'];
    }
  } else {
    // Mock para testar localmente caso sem login real
    AppState.currentUser = AppState.currentUser || {};
    AppState.currentUser.permissions = ['anexos', 'config', 'config.tags', 'config.usuarios', 'contas.pagar'];
  }

  // Aplicar permissões no Menu
  document.querySelectorAll('[data-permission]').forEach(el => {
    const reqPerm = el.getAttribute('data-permission');
    if (AppState.currentUser.permissions && AppState.currentUser.permissions.includes(reqPerm)) {
      el.style.display = ''; // mostrar
    } else {
      el.style.display = 'none'; // esconder
    }
  });
}

function toggleNavMenu(event, submenuId) {
  event.preventDefault();
  
  // Se a sidebar estiver recolhida, expande ela primeiro
  const sidebar = document.querySelector('.sidebar');
  if (sidebar && sidebar.classList.contains('collapsed')) {
    sidebar.classList.remove('collapsed');
    const mainContent = document.querySelector('.main-content');
    if (mainContent) mainContent.classList.remove('expanded');
    const toggleBtnIcon = document.querySelector("#sidebar-toggle-btn i");
    if (toggleBtnIcon) {
      toggleBtnIcon.setAttribute("data-lucide", "chevron-left");
      if (window.lucide) lucide.createIcons();
    }
  }

  const submenu = document.getElementById(submenuId);
  if (submenu) {
    const parentGroup = submenu.closest('.nav-group');
    if (submenu.style.display === 'none') {
      submenu.style.display = 'block';
      if(parentGroup) parentGroup.classList.add('active');
    } else {
      submenu.style.display = 'none';
      if(parentGroup) parentGroup.classList.remove('active');
    }
  }
}

