function getCompanyName(companyId) {
  if (!AppState.companies) return `Empresa #${companyId}`;
  const comp = AppState.companies.find(c => Number(c.id) === Number(companyId));
  if (!comp) return `Empresa #${companyId}`;
  
  const compName = comp.name || comp.tradeName || `Empresa #${companyId}`;
  return compName.toUpperCase()
    .replace(/\bEMPREENDIMENTOS\b/gi, "EMPREENDIMENTO")
    .replace(/\bLTDA\b/gi, "")
    .replace(/\bS\.?A\.?\b/gi, "")
    .replace(/\bEIRELI\b/gi, "")
    .replace(/\bPRINCIPAL\b/gi, "")
    .replace(/\bLOTEAMENTOS\b/gi, "")
    .replace(/\bDESENVOLVIMENTO URBANO\b/gi, "")
    .replace(/\bDESENVOLVIMENTO IMOBILIÁRIO SPE\b/gi, "")
    .replace(/\bDESENVOLVIMENTO IMOBILIÁRIO\b/gi, "")
    .replace(/\bSPE\b/gi, "")
    .replace(/\bLOTEADORA\b/gi, "")
    .replace(/\bPARCERIA\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();
}

const operatorColors = {};
let operatorColorIndex = 0;
let _cachedCrmUsersBadge = null;
function getOperatorBadgeStyle(opName) {
  if (opName === "OUTROS" || opName === "NÃO ATRIBUÍDO" || opName === "SEM CARTEIRA INADIMPLENTE") {
    return "background-color: #e2e8f0; color: #475569;";
  }
  
  if (!_cachedCrmUsersBadge) {
    try {
      _cachedCrmUsersBadge = JSON.parse(localStorage.getItem('crm_users')) || [];
    } catch (e) {
      _cachedCrmUsersBadge = [];
    }
  }

  if (_cachedCrmUsersBadge && _cachedCrmUsersBadge.length > 0) {
    const target = String(opName).toUpperCase().trim();
    const user = _cachedCrmUsersBadge.find(u => {
      const uName = u.name ? u.name.toUpperCase() : "";
      const uSienge = u.sienge_user ? u.sienge_user.toUpperCase().replace(/\./g, ' ').trim() : "";
      return uName === target || uSienge === target;
    });
    
    if (user && user.badge_color) {
      if (user.badge_color.startsWith('#')) {
        const hex = user.badge_color;
        return `background-color: color-mix(in srgb, ${hex} 15%, white); color: color-mix(in srgb, ${hex} 60%, black); border: 1px solid color-mix(in srgb, ${hex} 30%, white);`;
      }
      return user.badge_color;
    }
  }

  if (!operatorColors[opName]) {
    const colors = [
      "background-color: #dcfce7; color: #166534;", // green
      "background-color: #ffedd5; color: #c2410c;", // orange
      "background-color: #bbf7d0; color: #14532d;", // dark green
      "background-color: #fed7aa; color: #9a3412;"  // dark orange
    ];
    operatorColors[opName] = colors[operatorColorIndex % colors.length];
    operatorColorIndex++;
  }
  return operatorColors[opName];
}

function getPrimaryCostCenter(id) {
  if (!id) return "C.C. N/D";
  const strId = Array.isArray(id) ? String(id[0]) : String(id);
  return strId.split(',')[0].trim();
}

function getCostCenterName(id) {
    const rawId = getPrimaryCostCenter(id);
    if (!AppState.cachedCostCenters) return "C.C. " + rawId;
    const cc = AppState.cachedCostCenters.find(c => String(c.id) === String(rawId));
    if (cc && cc.name) return cc.name;
    return "C.C. " + rawId;
}

window.extractCityFromCostCenter = function(ccId, ccName) {
    if (!ccId) return null;
    const ccIdStr = String(ccId);
    if (!ccIdStr.startsWith("1") && !ccIdStr.startsWith("2") && !ccIdStr.startsWith("3")) {
        return null;
    }
    let cleanName = (ccName || "").replace(/^(?:\d+\s*-\s*)+/, '');
    if (cleanName.toUpperCase().startsWith("C.C. ")) {
        cleanName = cleanName.substring(5);
    }
    const cityMatch = cleanName.split('-')[0].trim().toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    
    if (ccIdStr === "14201" || cleanName.toUpperCase().includes("ARAÇARI") || cleanName.toUpperCase().includes("ARACARI")) {
        return "ARACARIGUAMA";
    }
    if (["137", "138", "139", "140"].some(p => ccIdStr.startsWith(p)) || cleanName.toUpperCase().includes("AVARE")) {
        return "AVARE";
    }
    if (cityMatch && cityMatch.length > 2 && isNaN(cityMatch)) {
        return cityMatch;
    }
    return null;
};

function parseSafeDate(dStr) {
    if (!dStr) return new Date(0);
    let str = String(dStr).trim();
    if (str.includes('/')) {
        const p = str.split('/');
        return new Date(`${p[2]}-${p[1]}-${p[0]}T12:00:00Z`);
    } else if (str.includes('-') && str.split('-')[0].length <= 2) {
        const p = str.split('-');
        return new Date(`${p[2]}-${p[1]}-${p[0]}T12:00:00Z`);
    }
    const d = new Date(str + "T12:00:00Z");
    if (isNaN(d.getTime())) {
        const d2 = new Date(str);
        return isNaN(d2.getTime()) ? new Date(0) : d2;
    }
    return d;
}
function getDelayBadgeHtml(days, isZeroPaid = false) {
  if (isZeroPaid) {
    return `
      <div style="padding: 3px 10px; font-size: 0.75rem; line-height: 1.2; border-radius: 12px; display: inline-flex; align-items: center; gap: 4px; border: 1px solid #fca5a5; background-color: #fee2e2; color: #991b1b; font-weight: 600;" title="0% Pago / Sem Receita">
        <i data-lucide="alert-circle" style="width: 14px; height: 14px; flex-shrink: 0;"></i> 0% Pago - ${days} dia${days === 1 ? '' : 's'}
      </div>
    `;
  }

  let badgeClass = "delay-badge-light";
  let iconName = "";
  let titleText = "Leve: até 30 dias";

  if (days > 120) {
    badgeClass = "delay-badge-critical";
    iconName = "octagon-alert";
    titleText = "Crítico: acima de 120 dias";
  } else if (days > 90) {
    badgeClass = "delay-badge-severe";
    iconName = "shield-alert";
    titleText = "Grave: 91 a 120 dias";
  } else if (days > 30) {
    badgeClass = "delay-badge-moderate";
    iconName = "alert-triangle";
    titleText = "Moderado: 31 a 90 dias";
  }

  const iconHtml = iconName ? `<i data-lucide="${iconName}" style="width: 14px; height: 14px; flex-shrink: 0;"></i>` : "";

  return `
    <div class="delay-badge ${badgeClass}" title="${titleText}">
      ${iconHtml}
      <span>${days} dia${days === 1 ? '' : 's'}</span>
    </div>
  `;
}

