// ----------------------------------------------------
// 8. SIMULADOR DE DISTRATO (RESCISÃO E DEVOLUÇÃO)
// ----------------------------------------------------
let g_distCustomer = null;
let g_distSale = null;
let g_distBills = [];

async function showDistratoView(customer, sale, bills) {
  g_distCustomer = customer;
  g_distSale = sale;
  g_distBills = bills;

  if (sale && sale.id) {
      AppState.selectedSaleId = sale.id;
  }
  
  // Setar aba
  sessionStorage.setItem('currentSubView', 'distrato');
  document.getElementById("view-customer-details").style.display = "none";
  document.getElementById("view-distrato").style.display = "block";
  
  // Manter barra de contexto do cliente visível
  const ctxBarDist = document.getElementById('client-context-bar');
  if (ctxBarDist) ctxBarDist.style.display = 'inline-flex';
  if (typeof lucide !== 'undefined' && lucide.createIcons) lucide.createIcons();

  // Cabeçalho
  // (Removido dist-method-badge conforme solicitado)
  
  // Total pago simulado e Valor do Contrato (sem juros de mora)
  let totalPaid = 0;
  let totalPaidOrig = 0;
  let totalPaidDesc = 0;
  let distratoContractValue = 0;
  let paidQty = 0;
  let unpaidQty = 0;
  let unpaidTotal = 0;
  
  if (AppState.currentContractKpis) {
      const kpis = AppState.currentContractKpis;
      console.log("AppState.currentContractKpis is TRUTHY:", kpis);
      totalPaidOrig = kpis.kpiPago || 0;
      totalPaidDesc = kpis.kpiDesconto || 0;
      totalPaid = totalPaidOrig - totalPaidDesc;
      paidQty = kpis.kpiQtdPagas || 0;
      
      unpaidTotal = (kpis.kpiVencidasOriginal || 0) + (kpis.kpiAVencer || 0);
      unpaidQty = (kpis.kpiQtdVencidas || 0) + (kpis.kpiQtdAVencer || 0);
      
      distratoContractValue = totalPaid + unpaidTotal;
      console.log("Calculated from KPIs: totalPaid=", totalPaid, "unpaidTotal=", unpaidTotal, "distratoContractValue=", distratoContractValue);
  } else {
      console.log("AppState.currentContractKpis is FALSY. Using fallback.");
      totalPaid = (sale.updatedContractValue * (sale.percPaid || 0)) || 0;
      totalPaidOrig = totalPaid;
      distratoContractValue = sale.updatedContractValue || 0;
  }
  sale.calculatedTotalPaid = totalPaid;
  sale.distratoContractValue = distratoContractValue;
  sale.calculatedPaidQty = paidQty;
  sale.calculatedUnpaidQty = unpaidQty;
  sale.calculatedUnpaidTotal = unpaidTotal;
  
  const totalQty = paidQty + unpaidQty;
  const contractValStr = distratoContractValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  const formatAlign = (val, qty) => {
    return `<span style="display:inline-block; width:140px; text-align:right;">${val}</span> <span style="display:inline-block; border-left: 1px solid #cbd5e1; margin-left:10px; padding-left:10px; font-weight: normal; font-size: 0.9rem; color: #64748b; width: 90px; text-align: left;">${qty} parcelas</span>`;
  };
  
  console.log("Updating DOM: dist-contract-val ->", contractValStr);
  document.getElementById("dist-contract-val").innerHTML = formatAlign(contractValStr, totalQty);
  
  const totalPaidStr = totalPaid.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  document.getElementById("dist-total-paid").innerHTML = formatAlign(totalPaidStr, paidQty);
  
  const unpaidTotalStr = unpaidTotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  document.getElementById("dist-unpaid-total").innerHTML = formatAlign(unpaidTotalStr, unpaidQty);

  const breakdownEl = document.getElementById("dist-paid-breakdown");
  if (breakdownEl) {
      breakdownEl.textContent = `Orig. ${totalPaidOrig.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })} - Desc. ${totalPaidDesc.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`;
  }

  // Valores padrão de despesas
  const isSubjudice = sale.subjudice === "S";
  const fruitionInput = document.getElementById("dist-fruition-months");
  fruitionInput.value = 1; // Padrão
  fruitionInput.readOnly = !isSubjudice;
  const fruitionContainer = document.getElementById("dist-fruition-container");
  if (fruitionContainer) {
      fruitionContainer.style.display = isSubjudice ? "block" : "none";
  }

  // Inicializar campos editáveis com formato de moeda
  const initCurrencyField = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.value = Number(val).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  initCurrencyField("dist-taxa-assoc", 0);
  initCurrencyField("dist-iptu", 0);
  initCurrencyField("dist-agua", 0);
  initCurrencyField("dist-luz", 0);
  initCurrencyField("dist-homolog", 0);
  initCurrencyField("dist-outros", 0);

  const saleDateLimit = new Date("2019-01-01");
  const saleDate = sale.saleDate ? new Date(sale.saleDate) : new Date();
  const isPre2019 = saleDate < saleDateLimit;
  
  // Comissão: habilitado apenas para vendas antes da lei (pré-2019)
  initCurrencyField("dist-comissao", isPre2019 ? 5000 : 0);
  const comissaoEl = document.getElementById("dist-comissao");
  const comissaoGroup = document.getElementById("dist-comissao-group");
  if (comissaoEl) {
    comissaoEl.disabled = !isPre2019;
    comissaoEl.readOnly = !isPre2019;
    comissaoEl.style.opacity = isPre2019 ? "1" : "0.5";
    comissaoEl.style.cursor = isPre2019 ? "text" : "not-allowed";
    comissaoEl.title = isPre2019 
      ? "Contrato pré-2019: comissão aplicável" 
      : "Comissão não se aplica a contratos após a Lei do Distrato (2019)";
  }
  if (comissaoGroup) {
    // Adicionar badge indicando status
    let badge = comissaoGroup.querySelector('.comissao-badge');
    if (!badge) {
      badge = document.createElement('span');
      badge.className = 'comissao-badge';
      badge.style.cssText = 'font-size: 0.7rem; padding: 2px 6px; border-radius: 4px; margin-left: 8px; font-weight: 600;';
      const label = comissaoGroup.querySelector('span');
      if (label) label.appendChild(badge);
    }
    badge.textContent = isPre2019 ? '(Pré-Lei)' : '(N/A pós 2019)';
    badge.style.background = isPre2019 ? '#fff3cd' : '#f1f5f9';
    badge.style.color = isPre2019 ? '#856404' : '#94a3b8';
  }

  const restPctEl = document.getElementById("dist-restitution-pct");
  if(restPctEl) restPctEl.value = 60; // Padrão
  
  const restInstEl = document.getElementById("dist-restitution-installments");
  if(restInstEl) restInstEl.value = 12;

  // Aplicar máscara de moeda nos campos de texto
  if (typeof window.applyDistratoCurrencyMask === 'function') {
    window.applyDistratoCurrencyMask();
    // Re-desabilitar o campo comissão após a máscara ser aplicada
    const comissaoElAfter = document.getElementById("dist-comissao");
    if (comissaoElAfter && !isPre2019) {
      comissaoElAfter.disabled = true;
    }
  }

  calculateDistrato();
  toggleDistratoPaymentFields();
}

function calculateDistrato() {
  if (!g_distSale) return;

  const contractVal = g_distSale.distratoContractValue || g_distSale.updatedContractValue;
  const totalPaid = g_distSale.calculatedTotalPaid || 0;
  
  const elTotalPagoCalc = document.getElementById("dist-calc-total-pago");
  if (elTotalPagoCalc) {
    elTotalPagoCalc.textContent = totalPaid.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  
  // 1. Multas (Penalty, Fruição, Comissão)
  const penalty = contractVal * 0.10; // 10% do valor do contrato
  
  // Converte string formatada pt-BR (ex: "1.500,75") para número
  const parseCurrencyInput = (id) => {
    const el = document.getElementById(id);
    if (!el) return 0;
    // Remove pontos de milhar e troca vírgula por ponto
    const raw = el.value.replace(/\./g, '').replace(',', '.');
    const val = parseFloat(raw) || 0;
    return val < 0 ? 0 : val;
  };
  
  const fruitionMonths = parseCurrencyInput("dist-fruition-months");
  const fruitionRate = 0.0075; // 0.75% a.m.
  const fruition = contractVal * fruitionRate * fruitionMonths;
  
  const comissao = parseCurrencyInput("dist-comissao");
  const homolog = parseCurrencyInput("dist-homolog");
  
  const totalMulta = penalty + fruition + comissao + homolog;
  
  // Restituição Total (pela lei do distrato: Recebido - Total Multa)
  const restituicaoTotal = Math.max(0, totalPaid - totalMulta);
  
  // 2. Despesas
  const taxaAssoc = parseCurrencyInput("dist-taxa-assoc");
  const iptu = parseCurrencyInput("dist-iptu");
  const agua = parseCurrencyInput("dist-agua");
  const luz = parseCurrencyInput("dist-luz");
  const outros = parseCurrencyInput("dist-outros");

  const outrasDeducoes = taxaAssoc + iptu + agua + luz + outros;
  
  // Restituição Líquida (pela lei do distrato)
  const restituicaoLiquida = Math.max(0, restituicaoTotal - outrasDeducoes);

window.handleCustomPctInput = function() {
  const totalPaid = g_distSale.calculatedTotalPaid || 0;
  let pct = Number(document.getElementById("dist-restitution-pct").value) || 0;
  if (pct > 100) {
    pct = 100;
    document.getElementById("dist-restitution-pct").value = 100;
  }
  const val = totalPaid * (pct / 100);
  
  const valEl = document.getElementById("dist-restitution-val");
  if (valEl) {
    valEl.value = val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  calculateDistrato();
};

window.handleCustomValInput = function() {
  const valEl = document.getElementById("dist-restitution-val");
  if (!valEl) return;
  
  let valStr = valEl.value.replace(/\D/g, '');
  if (!valStr) valStr = '0';
  let valNum = parseInt(valStr, 10) / 100;

  const totalPaid = g_distSale.calculatedTotalPaid || 0;
  
  if (totalPaid > 0 && valNum > totalPaid) {
    valNum = totalPaid;
  }

  valEl.value = valNum.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  
  if (totalPaid > 0) {
    const pct = (valNum / totalPaid) * 100;
    const pctEl = document.getElementById("dist-restitution-pct");
    if (pctEl) {
      pctEl.value = pct.toFixed(1);
    }
  }
  calculateDistrato();
};

window.selectDistratoOption = function(id, val) {
  const choiceEl = document.getElementById("dist-restitution-choice");
  if (choiceEl) {
    choiceEl.value = id;
    window.handleDistratoChoiceChange();
  }
};

window.handleDistratoChoiceChange = function() {
  calculateDistrato();
};

  // 3. Negociação de Devolução
  const minRefund = totalPaid * 0.55;
  const maxRefund = totalPaid * 0.65;
  const leiRefund = restituicaoLiquida;
  const leiRefundPct = totalPaid > 0 ? ((leiRefund / totalPaid) * 100).toFixed(1).replace('.0', '') : 0;

  const minDisabled = minRefund < leiRefund;
  const maxDisabled = maxRefund < leiRefund;

  // Sort and render options
  const options = [
    { id: "min", label: "Devolução Mínima (55%)", value: minRefund, color: "#cbd5e1", titleColor: "#64748b", disabled: minDisabled },
    { id: "max", label: "Devolução Máxima (65%)", value: maxRefund, color: "#cbd5e1", titleColor: "#64748b", disabled: maxDisabled },
    { id: "lei", label: `Lei do Distrato (${leiRefundPct}%)`, value: leiRefund, color: "#f97316", titleColor: "#ea580c", highlight: true, disabled: false }
  ];
  options.sort((a, b) => a.value - b.value);

  const container = document.getElementById("dist-negotiation-options");
  if (container) {
    container.innerHTML = options.map(opt => `
      <div style="background: ${opt.highlight ? '#fff7ed' : '#f8fafc'}; padding: 10px; border-radius: 6px; border: 2px solid ${opt.color}; text-align: center; cursor: ${opt.disabled ? 'not-allowed' : 'pointer'}; opacity: ${opt.disabled ? '0.5' : '1'}; transition: all 0.2s;" 
           ${opt.disabled ? '' : `onclick="selectDistratoOption('${opt.id}', ${opt.value})"`} 
           ${opt.disabled ? '' : `onmouseover="this.style.transform='translateY(-2px)'; this.style.boxShadow='0 4px 6px -1px rgba(0, 0, 0, 0.1)'"`} 
           ${opt.disabled ? '' : `onmouseout="this.style.transform='translateY(0)'; this.style.boxShadow='none'"`}>
        <div style="font-size: 0.75rem; color: ${opt.titleColor}; font-weight: ${opt.highlight ? '700' : '600'}; margin-bottom: 4px;">${opt.label}</div>
        <div style="font-weight: 800; color: ${opt.highlight ? '#c2410c' : '#334155'}; font-size: 1.1rem;">${opt.value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</div>
        <div style="font-size: 0.7rem; color: #94a3b8; margin-top: 4px;">${opt.disabled ? 'Abaixo da Lei Distrato' : 'Clique para escolher'}</div>
      </div>
    `).join('');
  }

  const minOption = document.querySelector('#dist-restitution-choice option[value="min"]');
  if (minOption) minOption.disabled = minDisabled;
  const maxOption = document.querySelector('#dist-restitution-choice option[value="max"]');
  if (maxOption) maxOption.disabled = maxDisabled;

  // Handle chosen option
  const choiceEl = document.getElementById("dist-restitution-choice");
  let choice = choiceEl ? choiceEl.value : "custom";
  
  if (choice === "min" && minDisabled) {
    choice = "lei";
    if (choiceEl) choiceEl.value = "lei";
  }
  if (choice === "max" && maxDisabled) {
    choice = "lei";
    if (choiceEl) choiceEl.value = "lei";
  }

  const pctContainer = document.getElementById("dist-custom-pct-container");
  
  let negotiatedRefund = 0;
  let restitutionPct = 0;

  if (choice === "min") {
    negotiatedRefund = minRefund;
    restitutionPct = 55;
    if (pctContainer) pctContainer.style.display = "none";
  } else if (choice === "max") {
    negotiatedRefund = maxRefund;
    restitutionPct = 65;
    if (pctContainer) pctContainer.style.display = "none";
  } else if (choice === "lei") {
    negotiatedRefund = leiRefund;
    restitutionPct = totalPaid > 0 ? (leiRefund / totalPaid) * 100 : 0;
    if (pctContainer) pctContainer.style.display = "none";
  } else {
    // custom
    let pctEl = document.getElementById("dist-restitution-pct");
    let valEl = document.getElementById("dist-restitution-val");
    restitutionPct = Number(pctEl.value) || 0;
    
    let valStr = valEl ? valEl.value.replace(/\D/g, '') : '0';
    if (!valStr) valStr = '0';
    let valNum = parseInt(valStr, 10) / 100;

    if (totalPaid > 0 && valNum > totalPaid) {
      valNum = totalPaid;
      if (valEl) valEl.value = valNum.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }
    
    // Fallback if valNum is 0 but we have a valid percentage typed
    if (valNum === 0 && restitutionPct > 0) {
      if (restitutionPct > 100) restitutionPct = 100;
      valNum = totalPaid * (restitutionPct / 100);
      if (valEl) valEl.value = valNum.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }
    
    // NUNCA DEIXAR MENOR QUE LEI DO DISTRATO
    if (valNum < leiRefund) {
      valNum = leiRefund;
      if (valEl) valEl.value = valNum.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }
    
    negotiatedRefund = valNum;
    
    if (totalPaid > 0) {
      restitutionPct = (valNum / totalPaid) * 100;
      if (pctEl) pctEl.value = restitutionPct.toFixed(1);
    }

    if (pctContainer) pctContainer.style.display = "flex";
  }

  // Parcelamento based on Negotiated Refund
  let instQty = Number(document.getElementById("dist-restitution-installments").value) || 12;
  if (instQty > 12) {
    instQty = 12;
    document.getElementById("dist-restitution-installments").value = 12;
  }
  const refundInstallment = negotiatedRefund / instQty;

  // Preencher DOM
  document.getElementById("dist-calc-penalty").textContent = penalty.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  document.getElementById("dist-calc-fruition").textContent = fruition.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  document.getElementById("dist-sum-total-multa").textContent = totalMulta.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  document.getElementById("dist-sum-restituicao-total").textContent = restituicaoTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  document.getElementById("dist-sum-outras-deducoes").textContent = outrasDeducoes.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  document.getElementById("dist-sum-restituicao-liquida").textContent = restituicaoLiquida.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  
  const negotiatedRefundEl = document.getElementById("dist-negotiated-refund");
  if (negotiatedRefundEl) negotiatedRefundEl.textContent = negotiatedRefund.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  const distSumInstEl = document.getElementById("dist-sum-installments-refund");
  if (distSumInstEl) distSumInstEl.textContent = refundInstallment.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  // Verificação de alçada
  const approvalAlert = document.getElementById("dist-approval-alert");
  if (approvalAlert) {
    const isExactlyLei = Math.abs(negotiatedRefund - leiRefund) < 0.01;
    if (choice !== "lei" && !isExactlyLei && (restitutionPct < 55 || restitutionPct > 65)) {
      approvalAlert.style.display = "flex";
    } else {
      approvalAlert.style.display = "none";
    }
  }

  // Guardar cálculo de simulação no estado
  AppState.currentDistratoResult = {
    penalty,
    fruition,
    fruitionMonths,
    totalPaid,
    baseRefund: restituicaoLiquida,
    restitutionPct,
    totalDeductions: totalMulta + outrasDeducoes,
    totalMulta,
    restituicaoTotal,
    outrasDeducoes,
    refundNet: negotiatedRefund,
    instQty,
    refundInstallment,
    extraDebits: { homolog, comissao, taxaAssoc, iptu, agua, luz, outros }
  };
}

function toggleDistratoPaymentFields() {
  const type = document.getElementById("dist-bank-transfer-type").value;
  document.getElementById("dist-bank-ted-fields").style.display = type === "TED" ? "flex" : "none";
  document.getElementById("dist-bank-pix-fields").style.display = type === "PIX" ? "flex" : "none";
}

function generateDistratoPDF() {
  const results = AppState.currentDistratoResult;
  if (!results) return;

  // Validação: Contratos emitidos até 31/12/2018 precisam de comissão informada (maior que 0)
  const saleDate = new Date(g_distSale.saleDate + 'T12:00:00'); // Evitar problemas de fuso
  const dataLimite = new Date("2018-12-31T23:59:59");
  const comissaoInfo = results.extraDebits.comissao || 0;
  
  if (saleDate <= dataLimite && comissaoInfo <= 0) {
    alert("Preencha a comissão deste contrato.");
    return;
  }

  const unit = AppState.units[g_distSale.unitId] || {};
  const preambleText = AppState.preambles[unit.costCenterId] || "PREÂMBULO DO EMPREENDIMENTO IMOBILIÁRIO.";

  // Dados Bancários
  const payType = document.getElementById("dist-bank-transfer-type").value;
  const beneficiaryName = document.getElementById("dist-bank-beneficiary-name").value || g_distCustomer.name;
  const beneficiaryCpf = document.getElementById("dist-bank-cpf").value || g_distCustomer.cpfCnpj;

  let payInfoHtml = "";
  if (payType === "TED") {
    const bank = document.getElementById("dist-bank-name").value || "N/D";
    const agency = document.getElementById("dist-bank-agency").value || "N/D";
    const account = document.getElementById("dist-bank-account").value || "N/D";
    const digit = document.getElementById("dist-bank-digit").value || "";
    payInfoHtml = `TED Bancário: Banco ${bank} | Agência: ${agency} | Conta: ${account}-${digit}`;
  } else {
    const pixType = document.getElementById("dist-bank-pix-type").value;
    const pixKey = document.getElementById("dist-bank-pix-key").value || "N/D";
    payInfoHtml = `PIX: Chave (${pixType}) - ${pixKey}`;
  }

  const docHtml = `
    <div style="text-align: center; margin-bottom: 2rem;">
      <h2 style="color: #105436; font-size: 16pt; font-weight: bold; margin-bottom: 5px;">TERMO DE DISTRATO E RESCISÃO DE CONTRATO IMOBILIÁRIO</h2>
      <h3 style="font-size: 12pt; color: #666; margin: 0;">Moura Leite Loteamentos</h3>
    </div>

    <p style="text-align: justify; margin-bottom: 1.5rem;">
      Pelo presente instrumento, a loteadora proprietária da unidade:<br>
      <strong>${preambleText}</strong>
    </p>

    <p style="text-align: justify; margin-bottom: 1.5rem;">
      E o cliente adquirente:<br>
      <strong>CLIENTE:</strong> ${g_distCustomer.name}, portador do CPF/CNPJ nº ${g_distCustomer.cpfCnpj}, resolvem rescindir o contrato de promessa de compra e venda referente à 
      <strong>Unidade: ${unit.id} (Quadra ${unit.block}, Lote ${unit.lot})</strong> do empreendimento correspondente.
    </p>

    <div style="margin: 1.5rem 0; padding: 15px; border: 1.5px solid #105436; border-radius: 6px;">
      <h4 style="color: #105436; margin-top: 0; font-weight: bold;">DEMONSTRATIVO FINANCEIRO DE DEVOLUÇÃO</h4>
      
      <table style="width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 10pt;">
        <tr>
          <td style="padding: 5px; font-weight: bold;">Total pago pelo cliente:</td>
          <td style="padding: 5px; text-align: right;">R$ ${results.totalPaid.toFixed(2)}</td>
        </tr>
        <tr style="border-bottom: 1px solid #ddd;">
          <td style="padding: 5px; font-weight: bold; color: green;">Percentual acordado de restituição (${results.restitutionPct}%):</td>
          <td style="padding: 5px; text-align: right; color: green;">R$ ${results.baseRefund.toFixed(2)}</td>
        </tr>
        <tr>
          <td style="padding: 5px; font-weight: bold; color: red;">Dedução - Multa Contratual (10% contrato):</td>
          <td style="padding: 5px; text-align: right; color: red;">- R$ ${results.penalty.toFixed(2)}</td>
        </tr>
        <tr>
          <td style="padding: 5px; font-weight: bold; color: red;">Dedução - Taxa de Fruição (${results.fruitionMonths} meses):</td>
          <td style="padding: 5px; text-align: right; color: red;">- R$ ${results.fruition.toFixed(2)}</td>
        </tr>
        
        ${Object.entries(results.extraDebits).map(([key, val]) => {
          if (val === 0) return "";
          const nameMap = {
            taxaAssoc: "Taxa Associativa",
            iptu: "IPTU Vencido",
            agua: "Conta de Água",
            luz: "Conta de Luz",
            homolog: "Homologação do Acordo",
            outros: "Outras despesas",
            comissao: "Comissão"
          };
          return `
            <tr>
              <td style="padding: 5px; color: red;">Dedução - ${nameMap[key] || key}:</td>
              <td style="padding: 5px; text-align: right; color: red;">- R$ ${val.toFixed(2)}</td>
            </tr>
          `;
        }).join('')}
        
        <tr style="border-top: 2px solid #105436; font-size: 11pt; font-weight: bold;">
          <td style="padding: 10px 5px;">VALOR LÍQUIDO A RESTITUIR:</td>
          <td style="padding: 10px 5px; text-align: right; color: #105436;">R$ ${results.refundNet.toFixed(2)}</td>
        </tr>
      </table>
    </div>

    <p style="text-align: justify; margin-bottom: 1.5rem;">
      O valor líquido de restituição será pago em <strong>${results.instQty}</strong> parcelas mensais de 
      <strong>R$ ${results.refundInstallment.toFixed(2)}</strong>, sendo creditadas através da seguinte forma de pagamento:<br>
      <strong>Beneficiário:</strong> ${beneficiaryName} | <strong>CPF/CNPJ:</strong> ${beneficiaryCpf}<br>
      <strong>Dados de Crédito:</strong> ${payInfoHtml}
    </p>

    <p style="text-align: justify; margin-bottom: 1.5rem;">
      Com a assinatura deste termo, o cliente concede a mais plena, rasa e irrevogável quitação do contrato mencionado, liberando a credora de quaisquer obrigações futuras, autorizando a imediata comercialização do lote pela Moura Leite Loteamentos.
    </p>

    <p style="text-align: right; margin-top: 3rem; margin-bottom: 3rem;">
      Avaré/SP, ${new Date().toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' })}.
    </p>

    <div style="display: flex; justify-content: space-between; margin-top: 4rem;">
      <div style="width: 45%; border-top: 1.5px solid #000; text-align: center; font-size: 10pt; padding-top: 5px;">
        MOURA LEITE LOTEAMENTOS<br>Credora
      </div>
      <div style="width: 45%; border-top: 1.5px solid #000; text-align: center; font-size: 10pt; padding-top: 5px;">
        ${g_distCustomer.name.toUpperCase()}<br>Cliente
      </div>
    </div>
  `;

  document.getElementById("pdf-modal-title").textContent = "Termo de Rescisão e Distrato - PDF";
  document.getElementById("pdf-document-content").innerHTML = docHtml;
  document.getElementById("pdf-view-overlay").classList.add("active");
  lucide.createIcons();
}

