window.exportWeSendToExcel = async function() {
  const chks = document.querySelectorAll(".chk-wesend-row:checked");
  if (chks.length === 0) {
    alert("Nenhum contrato selecionado para exportação.");
    return;
  }
  
  const sales = getSiengeApiMode() === "simulado" ? window.MOCK_DATA.SALES : (AppState.sales && AppState.sales.length > 0 ? AppState.sales : []);
  const customers = getSiengeApiMode() === "simulado" ? window.MOCK_DATA.CUSTOMERS : AppState.customers;
  const bills = getSiengeApiMode() === "simulado"
    ? window.MOCK_DATA.DEFAULTERS_RECEIVABLE_BILLS
    : (AppState.defaultersBills && AppState.defaultersBills.length > 0
        ? AppState.defaultersBills
        : []);
  
  const data = [
    ["Cliente", "Empreendimento", "Lote", "Contrato ID", "Dias em Atraso", "Valor em Atraso (R$)", "Última Ação"]
  ];
  
  chks.forEach(chk => {
    const saleId = Number(chk.getAttribute("data-sale-id"));
    const sale = sales.find(s => String(s.receivableBillId) === String(saleId) || String(s.id) === String(saleId)) || {
      id: saleId,
      customerId: 0,
      unitId: `U-0-ND`
    };
    
    let customerName = "Desconhecido";
    if (customers[sale.customerId]) {
      customerName = customers[sale.customerId].name;
    } else {
      const matchingBill = bills.find(b => String(b.saleId) === String(saleId));
      if (matchingBill) {
        customerName = matchingBill.clientName || matchingBill.customerName || `Cliente #${matchingBill.customerId}`;
      }
    }
    const customer = { name: customerName };
    const unit = AppState.units[sale.unitId] || {};
    const costCenter = window.MOCK_DATA.COST_CENTERS.find(cc => cc.id === unit.costCenterId) || {};
    
    const contractBills = bills.filter(b => String(b.saleId) === String(saleId) && b.slipStatus === "Vencido" && b.daysDelay >= 61);
    const totalOverdue = contractBills.reduce((acc, b) => acc + b.value + b.interest + b.fine, 0);
    const maxDaysDelay = contractBills.reduce((max, b) => b.daysDelay > max ? b.daysDelay : max, 0);
    
    const statusKey = `crm_wesend_status_${saleId}`;
    const currentStatus = localStorage.getItem(statusKey) || "Pendente";
    
    data.push([
      customer.name,
      costCenter.name || "N/D",
      `Quadra ${unit.block || 'N/D'}, Lote ${unit.lot || 'N/D'}`,
      `Contrato #${saleId}`,
      `${maxDaysDelay} dias`,
      totalOverdue.toFixed(2),
      currentStatus
    ]);
  });
  
  const worksheet = XLSX.utils.aoa_to_sheet(data);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Notificações We Send");
  XLSX.writeFile(workbook, "Contratos_Notificados_We_Send.xlsx");
};

function triggerWeSendNotification(saleId, name) {
  const statusKey = `crm_wesend_status_${saleId}`;
  
  alert(`Disparando Notificação Extrajudicial Digital via We Send para ${name}...\n\n` +
        `Processando assinatura digital com carimbo do tempo ICP-Brasil pelo servidor We Send RS...`);
        
  localStorage.setItem(statusKey, "Assinado Digitalmente ICP-Brasil");
  
  // Adicionar ocorrência
  const sales = getSiengeApiMode() === "simulado" ? window.MOCK_DATA.SALES : (AppState.sales && AppState.sales.length > 0 ? AppState.sales : []);
  const sale = sales.find(s => s.id === saleId);
  const customerId = sale ? sale.customerId : AppState.selectedCustomerId;
  
  if (customerId) {
    if (!AppState.notes[customerId]) {
      AppState.notes[customerId] = [];
    }
    AppState.notes[customerId].push({
      date: new Date().toISOString(),
      author: "SISTEMA (WE SEND)",
      text: `DISPARADO: Notificação Extrajudicial Digital certificada ICP-Brasil enviada via We Send. Status: Assinado Digitalmente.`,
      promiseDate: null,
      promiseStatus: null,
      reminder: null
    });
    localStorage.setItem("crm_moura_notes", JSON.stringify(AppState.notes));
  }

  loadWeSendTab();
}

function triggerCorreiosNotification(customerId, saleId, value) {
  const customer = getCustomerFromState(customerId);
  const salesList = getSiengeApiMode() === "simulado" ? window.MOCK_DATA.SALES : (AppState.sales && AppState.sales.length > 0 ? AppState.sales : []);
  const sale = salesList.find(s => s.id === saleId) || {};
  const unit = AppState.units[sale.unitId] || {};
  const costCenter = window.MOCK_DATA.COST_CENTERS.find(cc => cc.id === unit.costCenterId) || {};
  
  const preamble = AppState.preambles[unit.costCenterId] || "PREÂMBULO DO EMPREENDIMENTO IMOBILIÁRIO.";

  const docHtml = `
    <div style="text-align: center; margin-bottom: 3rem;">
      <h2 style="color: #105436; font-size: 16pt; font-weight: bold;">NOTIFICAÇÃO EXTRAJUDICIAL DE INADIMPLEMENTO</h2>
      <h3 style="font-size: 11pt; color: #666;">ENTREGA REGISTRADA - VIA CORREIOS</h3>
    </div>

    <p style="text-align: right; margin-bottom: 2rem;">
      Avaré/SP, ${new Date().toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' })}.
    </p>

    <p style="text-align: justify; margin-bottom: 1.5rem;">
      À(Ao) Sr(a).<br>
      <strong>${customer.name}</strong><br>
      Endereço: ${customer.address}<br>
      Ref: Unidade ${unit.id} (Quadra ${unit.block}, Lote ${unit.lot}) do ${costCenter.name}.
    </p>

    <p style="text-align: justify; margin-bottom: 1.5rem;">
      Prezado(a) Senhor(a),
    </p>

    <p style="text-align: justify; margin-bottom: 1.5rem; text-indent: 2em;">
      Notificamos Vossa Senhoria de que, na qualidade de adquirente da unidade imobiliária retro citada, consta em nossos registros de contas a receber o inadimplemento de parcelas de financiamento contratual cuja dívida consolidada importa na quantia de <strong>${value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</strong>.
    </p>

    <p style="text-align: justify; margin-bottom: 1.5rem; text-indent: 2em;">
      Solicitamos o comparecimento ao escritório da Moura Leite Loteamentos no prazo improrrogável de 15 (quinze) dias a contar do recebimento desta para regularização do débito. O não atendimento da presente notificação caracterizará a mora definitiva para efeitos do art. 32 da Lei 6.766/79, ensejando a rescisão extrajudicial ou judicial da promessa de compra e venda.
    </p>

    <p style="text-align: justify; margin-bottom: 3rem;">
      Atenciosamente,
    </p>

    <div style="width: 250px; border-top: 1.5px solid #000; text-align: center; font-size: 10pt; padding-top: 5px;">
      MOURA LEITE LOTEAMENTOS<br>Departamento de Cobrança Jurídica
    </div>
  `;

  document.getElementById("pdf-modal-title").textContent = "Notificação Extrajudicial Correios (Física)";
  document.getElementById("pdf-document-content").innerHTML = docHtml;
  document.getElementById("pdf-view-overlay").classList.add("active");
  lucide.createIcons();
}

