function renderRulesSettingsTable() {
  const body = document.getElementById("rules-config-table-body");
  if (!body) return;
  
  body.innerHTML = "";
  
  if (getSiengeApiMode() === "real" && !AppState.defaultersLoaded) {
    body.innerHTML = `
      <tr>
        <td colspan="7" style="text-align: center; padding: 40px; color: #64748b; background-color: #f8fafc;">
          <div style="display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 15px;">
            <div class="loading-spinner" style="width:32px; height:32px; border:3px solid rgba(16,84,54,0.15); border-top-color:var(--color-primary); border-radius:50%; animation:spin 0.8s linear infinite;"></div>
            <strong style="font-size: 1.1rem; color: var(--color-primary);">Atualizando Base de Dados...</strong>
            <p style="margin:0;">Novas cidades e títulos inadimplentes estão sendo atualizados no momento. Por favor, aguarde.</p>
          </div>
        </td>
      </tr>
    `;
    return;
  }

  
  const paramsStr = localStorage.getItem("crm_moura_rules_params");
  const params = paramsStr ? JSON.parse(paramsStr) : { interna: 30, terceirizada: 90, juridico: 91, email: 5, whatsapp: 10, carta: 30, jud_notificacao: 15, jud_ajuizamento: 30, jud_citacao: 60, renegSinal: 30, renegParcelas: 12, renegTaxa: 3.0 };

  if (document.getElementById("rule-param-email")) document.getElementById("rule-param-email").value = params.email;
  if (document.getElementById("rule-param-whatsapp")) document.getElementById("rule-param-whatsapp").value = params.whatsapp;
  if (document.getElementById("rule-param-carta")) document.getElementById("rule-param-carta").value = params.carta;
  if (document.getElementById("rule-param-sinal")) document.getElementById("rule-param-sinal").value = params.renegSinal || 30;
  if (document.getElementById("rule-param-parcelas")) document.getElementById("rule-param-parcelas").value = params.renegParcelas || 12;
  if (document.getElementById("rule-param-taxa")) document.getElementById("rule-param-taxa").value = params.renegTaxa || 3.0;
  
  window.renderTimeline();
  window.renderEtapasJudiciais();
  if (window.updateJudFaseDropdown) window.updateJudFaseDropdown();
  
  // Computar estatísticas por cidade a partir de AppState.defaultersBills
  const cityStats = {};
  if (AppState.defaultersBills && Array.isArray(AppState.defaultersBills)) {
    AppState.defaultersBills.forEach(bill => {
      let ccId = bill.costCenterId;
      if (bill.costCentersId && bill.costCentersId.length > 0) {
        ccId = Array.isArray(bill.costCentersId) ? bill.costCentersId[0] : bill.costCentersId;
      }
      if (!ccId && bill.unitId) ccId = bill.unitId.split('-')[1];

      if (ccId) {
        const ccIdStr = String(ccId);
        let city = null;
        let ccObj = null;
        if (AppState.cachedCostCenters) {
          ccObj = AppState.cachedCostCenters.find(cc => String(cc.id) === ccIdStr);
        }
        
        if (ccObj) {
           city = window.extractCityFromCostCenter(ccIdStr, ccObj.name);
        }
        
        if (city) {
          if (!cityStats[city]) {
             cityStats[city] = {
               totalOverdue: 0,
               ate30: new Set(),
               acima30: new Set(),
               subjudiceSales: new Set(),
               billCount: 0,
               enterprises: {}
             };
          }
          
          const billVal = bill.totalValue || (bill.value || 0) + (bill.interest || 0) + (bill.fine || 0);
          cityStats[city].totalOverdue += billVal;
          cityStats[city].billCount++;
          
          const empName = ccObj ? `${ccId} - ${ccObj.name}` : String(ccId);
          if (!cityStats[city].enterprises[empName]) {
             cityStats[city].enterprises[empName] = { totalOverdue: 0, billCount: 0, ate30: new Set(), acima30: new Set(), subjudiceSales: new Set() };
          }
          cityStats[city].enterprises[empName].totalOverdue += billVal;
          cityStats[city].enterprises[empName].billCount++;
          
          if (bill.saleId) {
             let isSubj = bill.subjudice === "S" || bill.subjudice === true;
             if (isSubj) {
                cityStats[city].subjudiceSales.add(bill.saleId);
                cityStats[city].enterprises[empName].subjudiceSales.add(bill.saleId);
             } else {
                const days = bill.daysDelay || 0;
                if (days <= 30) {
                   cityStats[city].ate30.add(bill.saleId);
                   cityStats[city].enterprises[empName].ate30.add(bill.saleId);
                } else {
                   cityStats[city].acima30.add(bill.saleId);
                   cityStats[city].enterprises[empName].acima30.add(bill.saleId);
                }
             }
          }
        }
      }
    });
  }
  
  // Forçar configuração v2 de Cidades (Operadores)
  if (!localStorage.getItem("crm_moura_cidades_v2")) {
     const defaultCities = {
         "ARAÇARIGUAMA": ["LETICIA OLIVEIRA", "THAIANE CORDEIRO"],
         "AVARÉ": ["LETICIA OLIVEIRA", "THAIANE CORDEIRO"],
         "BOITUVA": ["LETICIA OLIVEIRA", "THAIANE CORDEIRO"],
         "BOTUCATU": ["MICHELLE PEREIRA"],
         "CERQUEIRA CÉSAR": ["LETICIA OLIVEIRA"],
         "FARTURA": ["LETICIA OLIVEIRA"],
         "ITATINGA": ["MICHELLE VIEIRA"],
         "PIRAJU": ["MICHELLE VIEIRA"],
         "TAGUAI": ["MICHELLE VIEIRA"],
         "TATUÍ": ["MICHELLE VIEIRA"]
     };
     Object.keys(AppState.rules).forEach(k => {
         if (String(k).startsWith("CID_")) {
             const rule = AppState.rules[k];
             const cityName = rule.desc ? String(rule.desc).toUpperCase() : "";
             if (defaultCities[cityName]) {
                 rule.operator = defaultCities[cityName];
             } else {
                 rule.operator = [];
             }
         }
     });
     localStorage.setItem("crm_moura_rules", JSON.stringify(AppState.rules));
     localStorage.setItem("crm_moura_cidades_v2", "true");
  }
  
  const sortedRules = Object.values(AppState.rules)
    .filter(r => r.id && String(r.id).startsWith("CID_"))
    .sort((a, b) => {
      const descA = a.desc || '';
      const descB = b.desc || '';
      return descA.localeCompare(descB, 'pt-BR');
    });
  
  const opSummary = {};

  sortedRules.forEach((rule, index) => {
    const normalizedDesc = rule.desc ? rule.desc.trim().toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "") : '';
    const stats = cityStats[normalizedDesc] || cityStats[rule.desc] || { totalOverdue: 0, billCount: 0, enterprises: {}, ate30: new Set(), acima30: new Set(), subjudiceSales: new Set() };
    
    const isZero = stats.totalOverdue === 0;
    const formattedOverdue = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(stats.totalOverdue);
    const billsCount = stats.billCount;
    const ate30Count = stats.ate30 ? stats.ate30.size : 0;
    const acima30Count = stats.acima30 ? stats.acima30.size : 0;
    const subjudiceCount = stats.subjudiceSales ? stats.subjudiceSales.size : 0;
    
    let selectHtml = '';
    const unassignedText = isZero ? "SEM CARTEIRA INADIMPLENTE" : "NÃO ATRIBUÍDO";
    let assignedOp = rule.operator;
    let assignedOpsList = [];
    if (Array.isArray(assignedOp)) {
        assignedOpsList = assignedOp;
    } else if (assignedOp && assignedOp !== "OUTROS" && assignedOp !== unassignedText) {
        assignedOpsList = [assignedOp];
    }
    
    if (isZero) {
      selectHtml = `<span style="display:inline-block; padding:6px 10px; font-size:0.75rem; font-weight:700; background: #f1f5f9; color: #64748b; border: 1px solid #cbd5e1; border-radius:4px;">SEM CARTEIRA INADIMPLENTE</span>`;
    } else {
      let ops = window.getDynamicOperators();
      const operators = [...ops, "NÃO ATRIBUÍDO"];
      
      let pillsHtml = assignedOpsList.map(op => {
        return `<span style="display:inline-flex; align-items:center; background-color: #115e59; color: white; padding: 4px 10px; border-radius: 16px; font-size: 0.75rem; font-weight: 600; margin: 2px;" data-op="${op}">${op} <button onclick="window.removeOperatorFromRule('${rule.id}', '${op}')" style="background:transparent; border:none; color:white; margin-left:6px; cursor:pointer; font-weight:bold; font-size:0.9rem; padding:0; display:flex; align-items:center;">&times;</button></span>`;
      }).join('');
      
      let optionsHtml = `<option value="">+ Adicionar Operador</option>`;
      operators.forEach(op => {
        if (!assignedOpsList.includes(op)) {
          optionsHtml += `<option value="${op}">${op}</option>`;
        }
      });
      optionsHtml += `<option value="${unassignedText}" ${assignedOpsList.length === 0 ? 'selected' : ''} style="color:#94a3b8;">Desatribuir Todos</option>`;
      
      selectHtml = `
        <div class="rule-operator-container" data-rule-id="${rule.id}" data-bills-count="${billsCount}" style="display:flex; flex-direction:column; gap:6px;">
          <div id="pills-${rule.id}" style="display:flex; flex-wrap:wrap;">
            ${pillsHtml}
          </div>
          <select class="form-control" style="padding:4px 8px; font-size:0.8rem; border-radius:4px; border:1px solid #cbd5e1; max-width:180px;" onchange="window.addOperatorToRule('${rule.id}', this.value)">
            ${optionsHtml}
          </select>
        </div>
      `;
    }
    
    if (!isZero) {
      if (!opSummary[assignedOp]) opSummary[assignedOp] = 0;
      opSummary[assignedOp] += billsCount;
    }
    
    const rowColor = isZero ? "background-color: #f1f5f9; color: #64748b; border-bottom: 1px solid #e2e8f0; opacity: 0.85;" : "background-color: #FFF4E8; color: #C05500; border-bottom: 2px solid #fcd9b2; font-weight: 600;";
    const hasEnterprises = Object.keys(stats.enterprises).length > 0;
    const expandBtnHtml = hasEnterprises ? `<button class="btn btn-sm" onclick="toggleCityEnterprises(${index})" style="padding: 0; margin-right: 8px; border: none; background: transparent; box-shadow: none; cursor: pointer; color: var(--color-primary);" title="Ver Empreendimentos"><i data-lucide="plus-circle" id="city-icon-${index}" style="width: 18px; height: 18px;"></i></button>` : '<span style="display:inline-block; width: 26px;"></span>';

    const row = document.createElement("tr");
    if (rowColor) row.setAttribute("style", rowColor);
    row.innerHTML = `
      <td>
        <div style="display: flex; align-items: center;">
          ${expandBtnHtml}
          <strong>${rule.desc}</strong>
        </div>
      </td>
      <td style="text-align: center; font-weight: 600;">${ate30Count}</td>
      <td style="text-align: center; font-weight: 600;">${acima30Count}</td>
      <td style="text-align: center; font-weight: 600;">${subjudiceCount}</td>
      <td style="text-align: center; font-weight: 600;">${billsCount}</td>
      <td style="font-weight: 600; ${isZero ? '' : 'color: var(--color-danger);'}">${formattedOverdue}</td>
      <td>${selectHtml}</td>
    `;
    body.appendChild(row);
    
    if (hasEnterprises) {
      Object.keys(stats.enterprises).sort((a,b) => a.localeCompare(b, 'pt-BR')).forEach(empName => {
        const entStats = stats.enterprises[empName];
        const entOverdue = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(entStats.totalOverdue);
        const entAte30 = entStats.ate30 ? entStats.ate30.size : 0;
        const entAcima30 = entStats.acima30 ? entStats.acima30.size : 0;
        const entSubjudice = entStats.subjudiceSales ? entStats.subjudiceSales.size : 0;
        
        const entRow = document.createElement("tr");
        entRow.className = `city-enterprises-${index}`;
        entRow.style.display = "none";
        entRow.style.backgroundColor = "#ffffff";
        entRow.style.borderBottom = "1px solid #e2e8f0";
        
        entRow.innerHTML = `
          <td style="padding-left: 45px; font-size: 0.8rem; color: #64748b;">
            ${empName}
          </td>
          <td style="text-align: center; font-size: 0.8rem; color: #64748b;">${entAte30}</td>
          <td style="text-align: center; font-size: 0.8rem; color: #64748b;">${entAcima30}</td>
          <td style="text-align: center; font-size: 0.8rem; color: #64748b;">${entSubjudice}</td>
          <td style="text-align: center; font-size: 0.8rem; font-weight: 600; color: #475569;">${entStats.billCount}</td>
          <td style="font-size: 0.8rem; font-weight: 600; color: #ef4444;">${entOverdue}</td>
          <td></td>
        `;
        body.appendChild(entRow);
      });
    }
  });
  
  const summaryContainer = document.getElementById("operator-assignment-summary");
  if (summaryContainer) {
    window._lastOpSummary = opSummary;
    renderOperatorSummary(opSummary);
  }
  
  setTimeout(() => lucide.createIcons(), 50);
}

window.addOperatorToRule = function(ruleId, op) {
  if (!op || !AppState.rules || !AppState.rules[ruleId]) return;
  
  if (op === "NÃO ATRIBUÍDO" || op === "SEM CARTEIRA INADIMPLENTE") {
    AppState.rules[ruleId].operator = [op];
  } else {
    let currentOps = AppState.rules[ruleId].operator;
    if (!Array.isArray(currentOps)) {
      currentOps = currentOps && currentOps !== "OUTROS" && currentOps !== "NÃO ATRIBUÍDO" && currentOps !== "SEM CARTEIRA INADIMPLENTE" ? [currentOps] : [];
    }
    // Remove unassigned dummy items if exist
    currentOps = currentOps.filter(o => o !== "NÃO ATRIBUÍDO" && o !== "SEM CARTEIRA INADIMPLENTE");
    if (!currentOps.includes(op)) {
      currentOps.push(op);
    }
    AppState.rules[ruleId].operator = currentOps;
  }
  
  window.updateOperatorSummary();
  renderRulesSettingsTable();
  if (typeof loadDashboardData === 'function') {
      loadDashboardData();
  }
};

window.removeOperatorFromRule = function(ruleId, op) {
  if (!AppState.rules || !AppState.rules[ruleId]) return;
  
  let currentOps = AppState.rules[ruleId].operator;
  if (!Array.isArray(currentOps)) {
    currentOps = currentOps ? [currentOps] : [];
  }
  
  currentOps = currentOps.filter(o => o !== op);
  
  if (currentOps.length === 0) {
    AppState.rules[ruleId].operator = ["NÃO ATRIBUÍDO"];
  } else {
    AppState.rules[ruleId].operator = currentOps;
  }
  
  window.updateOperatorSummary();
  renderRulesSettingsTable();
  if (typeof loadDashboardData === 'function') {
      loadDashboardData();
  }
};

window.renderOperatorSummary = function(summaryObj) {
  const summaryContainer = document.getElementById("operator-assignment-summary");
  if (!summaryContainer) return;
  
  let summaryHtml = '<div style="width: 100%; font-weight: bold; color: var(--color-primary); margin-bottom: 5px;"><i data-lucide="users" style="width: 16px; height: 16px; margin-right: 5px; vertical-align: middle;"></i> Títulos Atribuídos por Operador</div>';
  if (Object.keys(summaryObj).length === 0) {
     summaryHtml += '<span>Nenhum título atribuído</span>';
  } else {
     Object.entries(summaryObj).sort((a,b) => b[1] - a[1]).forEach(([op, count]) => {
       if (count > 0) {
         summaryHtml += `<div style="background: white; padding: 6px 12px; border-radius: 6px; border: 1px solid #cbd5e1;"><strong>${op}:</strong> ${count} títulos</div>`;
       }
     });
  }
  summaryContainer.innerHTML = summaryHtml;
  lucide.createIcons();
};

window.updateOperatorSummary = function() {
  const containers = document.querySelectorAll(".rule-operator-container");
  const newSummary = {};
  
  containers.forEach(container => {
    const count = parseInt(container.getAttribute("data-bills-count")) || 0;
    const ruleId = container.getAttribute("data-rule-id");
    
    if (ruleId && AppState.rules && AppState.rules[ruleId]) {
      const ops = AppState.rules[ruleId].operator;
      const opArray = Array.isArray(ops) ? ops : (ops ? [ops] : []);
      
      opArray.forEach(op => {
        if (op && op !== "OUTROS" && op !== "NÃO ATRIBUÍDO" && op !== "SEM CARTEIRA INADIMPLENTE") {
          if (!newSummary[op]) newSummary[op] = 0;
          // Distribution visualization: For summary, divide bills among assigned operators
          newSummary[op] += Math.ceil(count / opArray.filter(o => o !== "NÃO ATRIBUÍDO").length);
        }
      });
    }
  });
  
  if (AppState.rules) {
    localStorage.setItem("crm_moura_rules", JSON.stringify(AppState.rules));
  }
  
  window.renderOperatorSummary(newSummary);
};

window.toggleCityEnterprises = function(index) {
  const trs = document.getElementsByClassName(`city-enterprises-${index}`);
  let isHidden = true;
  if (trs.length > 0) {
    isHidden = trs[0].style.display === "none";
    for (let i = 0; i < trs.length; i++) {
      trs[i].style.display = isHidden ? "table-row" : "none";
    }
  }
  
  const icon = document.getElementById(`city-icon-${index}`);
  if (icon) {
    // If it was hidden and we just showed it, change icon to minus
    if (isHidden) {
      icon.setAttribute('data-lucide', 'minus-circle');
    } else {
      icon.setAttribute('data-lucide', 'plus-circle');
    }
    lucide.createIcons();
  }
};

function checkAdminPermissions() {
  const adminEmail = localStorage.getItem("crm_moura_admin_email") || "leticia@mouraleite.com";
  const emailInput = document.getElementById("admin-email-config");
  if (emailInput) emailInput.value = adminEmail;
  
  const isCurrentAdmin = AppState.currentUser && AppState.currentUser.email.toLowerCase() === adminEmail.toLowerCase();
  
  const alertEl = document.getElementById("admin-permission-alert");
  if (alertEl) {
    alertEl.style.display = isCurrentAdmin ? "none" : "block";
  }
  
  const preambleTextArea = document.getElementById("preamble-text-area");
  if (preambleTextArea) {
    preambleTextArea.disabled = false; // Removido bloqueio para permitir cópia e escrita
  }
  
  const preambleRespArea = document.getElementById("preamble-responsibles-area");
  if (preambleRespArea) {
    preambleRespArea.disabled = false;
  }
  
  const btnSavePreamble = document.getElementById("btn-save-preamble");
  if (btnSavePreamble) {
    btnSavePreamble.disabled = false;
  }
  
  const btnSaveRules = document.getElementById("btn-save-rules-config");
  if (btnSaveRules) {
    btnSaveRules.disabled = !isCurrentAdmin;
  }
  
  document.querySelectorAll(".rule-operator-select").forEach(sel => {
    sel.disabled = !isCurrentAdmin;
  });
}

window.loadPreambleConfigData = async function() {
  try {
    const host = (window.location.hostname === "" || window.location.hostname === "127.0.0.1") ? "localhost" : window.location.hostname;
    const port = 3000;
    
    if (!AppState.cachedCompanies) {
      try {
        AppState.cachedCompanies = await SiengeApiService.getCompanies();
      } catch(e) {
        console.warn("Proxy unavailable, using mock companies");
        AppState.cachedCompanies = window.MOCK_DATA ? window.MOCK_DATA.COMPANIES : [];
      }
    }
    
    if (!AppState.cachedCostCenters) {
      try {
        AppState.cachedCostCenters = await SiengeApiService.getCostCenters();
      } catch(e) {
        console.warn("Proxy unavailable, using mock cost centers");
        AppState.cachedCostCenters = window.MOCK_DATA ? window.MOCK_DATA.COST_CENTERS : [];
      }
    }
    
    const empSelect = document.getElementById("preamble-empresa");
    if (empSelect && AppState.cachedCompanies) {
      const currentVal = empSelect.value;
      let html = '<option value="">Selecione a Empresa</option>';
      
      let targetCompanyIds = null;
      try {
        const localCustom = localStorage.getItem('crm_empresas_custom');
        if (localCustom) {
          const customData = JSON.parse(localCustom);
          const internalIds = Object.entries(customData)
            .filter(([id, c]) => c.cobranca_interna == 1 || c.cobranca_interna === true)
            .map(([id, c]) => Number(id));
          if (internalIds.length > 0) {
            targetCompanyIds = internalIds;
          }
        }
      } catch(e) {}
      
      let companiesToRender = AppState.cachedCompanies;
      if (!Array.isArray(companiesToRender)) {
        html += `<option value="">ERRO: cachedCompanies is not array! type: ${typeof companiesToRender}</option>`;
        empSelect.innerHTML = html;
        return;
      }
      if (targetCompanyIds) {
        companiesToRender = companiesToRender.filter(c => targetCompanyIds.includes(Number(c.id)));
      }
      
      if (companiesToRender.length === 0) {
        html += `<option value="">Nenhuma empresa sobrou após filtro. targetIds: ${JSON.stringify(targetCompanyIds)}</option>`;
        html += `<option value="">Total empresas: ${AppState.cachedCompanies.length}</option>`;
        if (AppState.cachedCompanies.length > 0) {
          html += `<option value="">Primeira emp: ${JSON.stringify(AppState.cachedCompanies[0])}</option>`;
        }
      } else {
        companiesToRender.sort((a, b) => a.id - b.id).forEach(c => {
          const companyName = c.corporateName || c.tradeName || c.name || `Empresa ${c.id}`;
          html += `<option value="${c.id}">${c.id} - ${companyName}</option>`;
        });
      }
      empSelect.innerHTML = html;
      
      if (currentVal && companiesToRender.find(c => c.id == currentVal)) {
        empSelect.value = currentVal;
      } else if (companiesToRender.length === 1) {
        empSelect.value = companiesToRender[0].id;
      }
      
      if (empSelect.value) {
        window.loadCentrosCustoForPreamble();
      }
    }
  } catch(e) {
    console.error("Erro ao carregar companies/costcenters para preâmbulo", e);
    const empSelect = document.getElementById("preamble-empresa");
    if (empSelect) {
      empSelect.innerHTML = `<option value="">EXCEPTION: ${e.message}</option>`;
    }
  }
};

window.loadCentrosCustoForPreamble = function(selectedIds = []) {
  const empSelect = document.getElementById("preamble-empresa");
  const ccListDiv = document.getElementById("preamble-cc-list");
  if (!empSelect || !ccListDiv) return;
  
  const empId = empSelect.value;
  if (!empId) {
    ccListDiv.innerHTML = '<div style="color: #888; font-style: italic;">Selecione uma empresa primeiro.</div>';
    return;
  }
  
  // Filtramos estritamente pela empresa selecionada (usando o idCompany retornado pelo ERP)
  const allCCs = AppState.cachedCostCenters || [];
  let filteredCCs = allCCs.filter(cc => String(cc.idCompany) === String(empId) || String(cc.companyId) === String(empId));
  
  if (filteredCCs.length === 0) {
    ccListDiv.innerHTML = '<div style="color: #888; font-style: italic;">Nenhum centro de custo associado a esta empresa (verifique se a API retorna companyId).</div>';
    return;
  }
  
  // Ordenar conforme pedido: Empresa (já selecionada, então só CC do menor para maior)
  filteredCCs.sort((a, b) => a.id - b.id);
  
  let html = '<div style="display: flex; flex-wrap: wrap; gap: 6px; max-height: 250px; overflow-y: auto; padding-right: 5px;">';
  filteredCCs.forEach(cc => {
    // Verificar se já está vinculado a OUTRO preâmbulo
    const currentEditId = document.getElementById("preamble-edit-id").value;
    let vinculatedToOther = null;
    if (AppState.preamblesList) {
      vinculatedToOther = AppState.preamblesList.find(p => p.id != currentEditId && p.centrosCustoIds && p.centrosCustoIds.includes(cc.id));
    }
    
    const isChecked = window.currentPreambleSelectedCCs && window.currentPreambleSelectedCCs.includes(cc.id);
    const disabled = vinculatedToOther ? 'disabled' : '';
    const labelStyle = vinculatedToOther ? 'color: #aaa; text-decoration: line-through; background-color: #f5f5f5;' : 'background-color: #ffffff;';
    const title = vinculatedToOther ? `Já vinculado ao Preâmbulo ${vinculatedToOther.id}` : '';
    
    html += `
      <label style="display: inline-flex; align-items: center; gap: 4px; padding: 4px 8px; border: 1px solid #ddd; border-radius: 12px; cursor: ${vinculatedToOther ? 'not-allowed' : 'pointer'}; ${labelStyle} transition: all 0.2s; box-shadow: 0 1px 2px rgba(0,0,0,0.05);" title="${title}" onmouseover="this.style.borderColor='#1b8253'" onmouseout="this.style.borderColor='#ddd'">
        <input type="checkbox" class="preamble-cc-checkbox" value="${cc.id}" ${isChecked ? 'checked' : ''} ${disabled} onchange="window.togglePreambleCC(parseInt(this.value, 10), this.checked)" style="margin: 0; width: 12px; height: 12px;">
        <span style="font-size: 0.8rem; font-weight: 500;">${cc.id}</span>
      </label>
    `;
  });
  html += '</div>';
  
  ccListDiv.innerHTML = html;
  if (typeof window.updatePreambleSelectedBadges === 'function') window.updatePreambleSelectedBadges();
};

window.togglePreambleCC = function(ccId, isChecked) {
  if (!window.currentPreambleSelectedCCs) window.currentPreambleSelectedCCs = [];
  if (isChecked) {
    if (!window.currentPreambleSelectedCCs.includes(ccId)) {
      window.currentPreambleSelectedCCs.push(ccId);
    }
  } else {
    window.currentPreambleSelectedCCs = window.currentPreambleSelectedCCs.filter(id => id !== ccId);
  }
  window.updatePreambleSelectedBadges();
};

window.toggleAllPreambleCC = function(checked) {
  const checkboxes = document.querySelectorAll('.preamble-cc-checkbox:not(:disabled)');
  checkboxes.forEach(cb => {
    cb.checked = checked;
    window.togglePreambleCC(parseInt(cb.value, 10), checked);
  });
};

window.removePreambleSelectedCC = function(ccId) {
  if (!window.currentPreambleSelectedCCs) return;
  window.currentPreambleSelectedCCs = window.currentPreambleSelectedCCs.filter(id => id !== ccId);
  const cb = document.querySelector(`.preamble-cc-checkbox[value="${ccId}"]`);
  if (cb) cb.checked = false;
  window.updatePreambleSelectedBadges();
};

window.updatePreambleSelectedBadges = function() {
  const badgesContainer = document.getElementById("preamble-cc-selected-badges");
  if (!badgesContainer) return;
  
  if (!window.currentPreambleSelectedCCs || window.currentPreambleSelectedCCs.length === 0) {
    badgesContainer.innerHTML = '<span style="font-size: 0.8rem; color: #999;">Nenhum selecionado</span>';
    return;
  }
  
  let html = '';
  window.currentPreambleSelectedCCs.forEach(ccId => {
    html += `<span style="background: var(--color-primary); color: white; padding: 2px 8px; border-radius: 12px; font-size: 0.75rem; font-weight: 600; display: inline-flex; align-items: center; gap: 4px;">
               ${ccId} 
               <span style="cursor: pointer; background: rgba(255,255,255,0.3); border-radius: 50%; width: 14px; height: 14px; display: inline-flex; justify-content: center; align-items: center;" onclick="window.removePreambleSelectedCC(${ccId})">&times;</span>
             </span>`;
  });
  badgesContainer.innerHTML = html;
};

// Fechar o dropdown de Centros de Custo ao clicar fora
document.addEventListener('click', function(event) {
  const dropdown = document.getElementById('preamble-cc-dropdown');
  if (dropdown && (dropdown.hasAttribute('open') || dropdown.open)) {
    if (!dropdown.contains(event.target)) {
      dropdown.removeAttribute('open');
      dropdown.open = false;
    }
  }
}, true);

window.openNewPreambleModal = async function() {
  window.currentPreambleSelectedCCs = [];
  window.updatePreambleSelectedBadges();
  const box = document.getElementById("preamble-editor-modal");
  if (box) box.classList.add("active");
  
  const title = document.getElementById("preamble-editor-title");
  if (title) title.innerHTML = `Novo Preâmbulo`;
  
  document.getElementById("preamble-edit-mode").value = "new";
  document.getElementById("preamble-edit-id").value = "";
  
  const textEl = document.getElementById("preamble-text-area");
  const statusEl = document.getElementById("preamble-status-select");
  const empSelect = document.getElementById("preamble-empresa");
  
  if (textEl) textEl.value = "";
  if (statusEl) statusEl.value = "Ativo";
  if (empSelect) empSelect.value = "";
  
  const ccListDiv = document.getElementById("preamble-cc-list");
  if (ccListDiv) ccListDiv.innerHTML = '<div style="color: #888; font-style: italic;">Selecione uma empresa primeiro.</div>';
  
  const container = document.getElementById("preamble-responsibles-container");
  if (container) container.innerHTML = "";
  addResponsibleField();
  
  await window.loadPreambleConfigData();
};

window.selectPreambleForEdit = async function(id) {
  if (!AppState.preamblesList) return;
  const p = AppState.preamblesList.find(x => x.id === id);
  if (!p) return;
  
  window.currentPreambleSelectedCCs = [...(p.centrosCustoIds || [])];
  window.updatePreambleSelectedBadges();
  
  const box = document.getElementById("preamble-editor-modal");
  if (box) box.classList.add("active");
  
  const title = document.getElementById("preamble-editor-title");
  if (title) {
    title.innerHTML = `Editando Preâmbulo <strong>${p.id}</strong>`;
  }
  
  document.getElementById("preamble-edit-mode").value = "edit";
  document.getElementById("preamble-edit-id").value = p.id;
  
  const textEl = document.getElementById("preamble-text-area");
  const statusEl = document.getElementById("preamble-status-select");
  const empSelect = document.getElementById("preamble-empresa");
  
  if (textEl) textEl.value = p.text || "";
  if (statusEl) statusEl.value = p.status || "Ativo";
  
  await window.loadPreambleConfigData();
  
  if (empSelect) {
    if (p.empresaId) {
      empSelect.value = p.empresaId;
    }
    // Sempre chamamos loadCentrosCustoForPreamble para renderizar os checkboxes, 
    // passando os IDs que já estavam salvos neste preâmbulo.
    window.loadCentrosCustoForPreamble(p.centrosCustoIds || []);
  }
  
  const container = document.getElementById("preamble-responsibles-container");
  if (container) container.innerHTML = "";
  
  if (p.responsibles) {
    const resps = p.responsibles.split('\n').filter(r => r.trim() !== "");
    if (resps.length > 0) {
      resps.forEach(r => addResponsibleField(r.trim()));
    } else {
      addResponsibleField();
    }
  } else {
    addResponsibleField();
  }
};

window.cancelPreambleEdit = function() {
  const box = document.getElementById("preamble-editor-modal");
  if (box) box.classList.remove("active");
  
  document.getElementById("preamble-edit-mode").value = "";
  document.getElementById("preamble-edit-id").value = "";
  const textEl = document.getElementById("preamble-text-area");
  if (textEl) textEl.value = "";
  const statusEl = document.getElementById("preamble-status-select");
  if (statusEl) statusEl.value = "Ativo";
  
  const container = document.getElementById("preamble-responsibles-container");
  if (container) container.innerHTML = "";
};

window.addResponsibleField = function(value = "") {
  const container = document.getElementById("preamble-responsibles-container");
  if (!container) return;
  
  const div = document.createElement("div");
  div.style.display = "flex";
  div.style.gap = "8px";
  div.style.alignItems = "center";
  
  div.innerHTML = `
    <input type="text" class="form-control resp-input" value="${value}" placeholder="Nome ou Empresa responsável" style="flex: 1;">
    <button class="btn btn-danger btn-sm" onclick="removeResponsibleField(this)" title="Remover" style="padding: 6px 10px;">
      <i data-lucide="trash-2" style="width: 16px;"></i>
    </button>
  `;
  container.appendChild(div);
  lucide.createIcons();
};

window.removeResponsibleField = function(btn) {
  const div = btn.parentElement;
  if (div) div.remove();
};

window.savePreamble = function() {
  try {
    const mode = document.getElementById("preamble-edit-mode").value;
    const text = document.getElementById("preamble-text-area").value.trim();
    const status = document.getElementById("preamble-status-select").value;
    
    const respInputs = document.querySelectorAll("#preamble-responsibles-container .resp-input");
    const responsiblesArr = [];
    respInputs.forEach(input => {
      const val = input.value.trim();
      if (val) responsiblesArr.push(val);
    });
    const responsibles = responsiblesArr.join('\n');
    
    if (!text) {
      alert("O preâmbulo não pode estar vazio.");
      return;
    }
    
    const empSelect = document.getElementById("preamble-empresa");
    const empresaId = empSelect ? empSelect.value : "";
    
    const centrosCustoIds = [...(window.currentPreambleSelectedCCs || [])];
    
    if (!AppState.preamblesList) {
      AppState.preamblesList = JSON.parse(localStorage.getItem('crm_moura_preambles_list')) || [];
    }
    
    // Validar duplicidade (mesmo se desabilitado por DOM tinkering)
    const currentEditId = mode === "new" ? -1 : parseInt(document.getElementById("preamble-edit-id").value, 10);
    for (let ccId of centrosCustoIds) {
      const duplicado = AppState.preamblesList.find(p => p.id !== currentEditId && p.centrosCustoIds && p.centrosCustoIds.includes(ccId));
      if (duplicado) {
        alert(`O MESMO CENTRO DE CUSTO NÃO PODE ESTAR EM MAIS DE UM PREAMBULO.\nO Centro de Custo ${ccId} já pertence ao Preâmbulo ${duplicado.id}.`);
        return;
      }
    }
    
    if (mode === "new") {
      const nextId = AppState.preamblesList.length > 0 ? Math.max(...AppState.preamblesList.map(x => x.id)) + 1 : 1;
      AppState.preamblesList.push({
        id: nextId,
        text: text,
        responsibles: responsibles,
        status: status,
        empresaId: empresaId,
        centrosCustoIds: centrosCustoIds
      });
    } else {
      const p = AppState.preamblesList.find(x => x.id === currentEditId);
      if (p) {
        p.text = text;
        p.responsibles = responsibles;
        p.status = status;
        p.empresaId = empresaId;
        p.centrosCustoIds = centrosCustoIds;
      } else {
        alert("Erro: Preâmbulo não encontrado para edição.");
        return;
      }
    }
    
    localStorage.setItem("crm_moura_preambles_list", JSON.stringify(AppState.preamblesList));
    
    cancelPreambleEdit();
    loadPreamblesConfigTab();
  } catch (err) {
    alert("Erro interno ao salvar preâmbulo: " + err.message);
    console.error(err);
  }
};

window.saveAdminEmailConfig = function() {
  const input = document.getElementById("admin-email-config");
  if (!input) return;
  const email = input.value.trim().toLowerCase();
  
  if (!email || !email.includes("@")) {
    alert("Por favor, digite um e-mail válido.");
    return;
  }
  
  localStorage.setItem("crm_moura_admin_email", email);
  alert(`E-mail do administrador configurado para: ${email}\nPermissões atualizadas!`);
  
  loadPreamblesConfigTab();
};

window.populateFilaOperators = function() {
  const select = document.getElementById("fila-config-operator");
  if (!select) return;
  
  // Maintain current selection if possible
  const currentVal = select.value;
  
  select.innerHTML = '<option value="Todos">Configuração Padrão (Todos)</option>';
  
  if (AppState.configUsers) {
    const operators = AppState.configUsers.filter(u => u.perfil === "Operador" && (!u.operator_type || u.operator_type === "interno"));
    operators.forEach(op => {
      const option = document.createElement("option");
      option.value = op.name.toUpperCase();
      option.textContent = op.name.toUpperCase();
      select.appendChild(option);
    });
  } else {
    const operators = window.getDynamicOperators('interno');
    operators.forEach(op => {
      const option = document.createElement("option");
      option.value = op;
      option.textContent = op;
      select.appendChild(option);
    });
  }
  
  if (currentVal && Array.from(select.options).some(o => o.value === currentVal)) {
    select.value = currentVal;
  }
  
  window.loadFilaConfigForOperator();
};

window.loadFilaConfigForOperator = function() {
  const op = document.getElementById("fila-config-operator")?.value || "Todos";
  
  if (!AppState.rules) AppState.rules = {};
  if (!AppState.rules.filaConfig) AppState.rules.filaConfig = {};
  
  const defaultConfig = {
    capacity: 25,
    r1: 50, // Maiores valores
    r2: 20, // Mais tempo atraso
    r3: 10, // >1 contrato
    r4: 10, // <1 ano
    r5: 10, // Mais parcelas vencidas
    paymentDays: 15 // Dias sem fila após pagamento
  };
  
  // Se não existir, tenta carregar o 'Todos', senão usa default
  const config = AppState.rules.filaConfig[op] || AppState.rules.filaConfig["Todos"] || defaultConfig;
  
  document.getElementById("fila-capacity").value = config.capacity || 25;
  document.getElementById("fila-rule-1").value = config.r1 || 0;
  document.getElementById("fila-rule-2").value = config.r2 || 0;
  document.getElementById("fila-rule-3").value = config.r3 || 0;
  document.getElementById("fila-rule-4").value = config.r4 || 0;
  document.getElementById("fila-rule-5").value = config.r5 || 0;
  document.getElementById("fila-rule-6").value = config.r6 || 0;
  document.getElementById("fila-rule-7").value = config.r7 || 0;
  if(document.getElementById("fila-rule-payment-days")) document.getElementById("fila-rule-payment-days").value = config.paymentDays !== undefined ? config.paymentDays : 15;
  
  if (window.updateCapacityVisual) window.updateCapacityVisual(config.capacity || 25);
  if (window.updateCalendarVisual) window.updateCalendarVisual(config.paymentDays !== undefined ? config.paymentDays : 15);
  
  window.updateFilaTotalPercentage();
  if (window.sortFilaCircles) window.sortFilaCircles();
};

window.updateCapacityVisual = function(val) {
   const container = document.getElementById('capacity-visual');
   if(!container) return;
   let num = parseInt(val) || 0;
   let html = '';
   let maxIcons = 50;
   for(let i=1; i<=maxIcons; i++) {
       let isHighlighted = i <= num;
       let color = isHighlighted ? 'var(--color-primary, #105436)' : '#cbd5e1'; // Highlighted vs grey
       html += `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="transition: stroke 0.3s ease;"><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>`;
   }
   if(num > maxIcons) {
       html += `<div style="grid-column: 1 / -1; font-size: 0.95rem; font-weight: 800; color: #f59e0b; margin-top: 2px;">+${num - maxIcons} clientes</div>`;
   }
   container.innerHTML = html;
};

window.updateCalendarVisual = function(val) {
   const container = document.getElementById('calendar-visual');
   if(!container) return;
   let num = parseInt(val) || 0;
   let html = `<div style="display: grid; grid-template-columns: repeat(7, 1fr); gap: 2px; background: #fff; border: 1px solid #e2e8f0; border-radius: 4px; padding: 4px;">`;
   const days = ['D','S','T','Q','Q','S','S'];
   days.forEach(d => {
       html += `<div style="text-align: center; font-size: 9px; font-weight: 700; color: #94a3b8; padding-bottom: 2px; border-bottom: 1px solid #e2e8f0; margin-bottom: 2px;">${d}</div>`;
   });
   let displayMax = 31;
   for(let i=1; i<=displayMax; i++) {
       let isBlocked = i <= num;
       let bg = isBlocked ? '#ef4444' : '#f8fafc';
       let color = isBlocked ? 'white' : '#cbd5e1';
       let border = isBlocked ? 'none' : '1px solid #e2e8f0';
       html += `<div style="height: 16px; border-radius: 3px; background: ${bg}; border: ${border}; display: flex; align-items: center; justify-content: center; font-size: 9px; font-weight: 600; color: ${color};">
         ${isBlocked ? 'x' : i}
       </div>`;
   }
   html += `</div>`;
   if(num > 31) {
       html += `<div style="text-align: center; font-size: 0.8rem; font-weight: 700; color: #ef4444; margin-top: 4px;">+ ${num - 31} dias...</div>`;
   }
   container.innerHTML = html;
};

window.updateFilaTotalPercentage = function(triggeredInput) {
  let total = 0;
  for(let i=1; i<=7; i++) {
    const input = document.getElementById('fila-rule-'+i);
    if (!input) continue;
    const val = parseFloat(input.value) || 0;
    total += val;
  }
  
  if (total > 100 && triggeredInput) {
    const excess = total - 100;
    const currentVal = parseFloat(triggeredInput.value) || 0;
    const newVal = Math.max(0, currentVal - excess);
    triggeredInput.value = newVal;
    total = 100;
  }

  for(let i=1; i<=7; i++) {
    const input = document.getElementById('fila-rule-'+i);
    if (!input) continue;
    const val = parseFloat(input.value) || 0;
    
    // Update individual circle
    const circle = document.getElementById('circle-ui-'+i);
    if (circle) {
      circle.style.background = `conic-gradient(var(--color-primary, #10b981) ${val}%, transparent ${val}%)`;
      if (val > 0) {
        circle.classList.add('circle-filling-animation');
      } else {
        circle.classList.remove('circle-filling-animation');
      }
    }
  }
  
  const label = document.getElementById('fila-total-percent-text');
  const circleTotal = document.getElementById('circle-ui-total');
  
  if(label) {
    label.innerHTML = total + '<span style="font-size: 0.8rem; margin-left: 2px;">%</span>';
    let color = '#92BB97'; // default light green
    if (total > 30) color = '#8DA497';
    if (total > 60) color = '#128143';
    if (total === 100) color = '#004E33'; // Moura Leite dark green
    if (total > 100) color = '#EF493B'; // Red
    
    label.style.color = color;
    if (circleTotal) {
        circleTotal.style.background = `conic-gradient(${color} ${Math.min(total, 100)}%, transparent ${Math.min(total, 100)}%)`;
        if (total === 100) {
            circleTotal.classList.add('circle-complete-animation');
        } else {
            circleTotal.classList.remove('circle-complete-animation');
        }
    }
  }
};

window.sortFilaCircles = function() {
  const values = [];
  for(let i=1; i<=7; i++) {
    const input = document.getElementById('fila-rule-'+i);
    if (!input) continue;
    const val = parseFloat(input.value) || 0;
    values.push({ id: i, val: val });
  }
  
  // Sort descending
  values.sort((a,b) => b.val - a.val);
  values.forEach((item, index) => {
     const wrap = document.getElementById('wrap-ui-'+item.id);
     if (wrap && wrap.style.order !== String(index)) {
         wrap.style.order = index;
         wrap.classList.remove('circle-flash');
         void wrap.offsetWidth; // trigger reflow
         wrap.classList.add('circle-flash');
     }
  });
};

window.saveFilaConfig = function() {
  const op = document.getElementById("fila-config-operator")?.value || "Todos";
  
  // Validar campos vazios (null)
  for(let i=1; i<=7; i++) {
    const el = document.getElementById("fila-rule-"+i);
    if(el && el.value === "") {
      alert("Erro: Nenhum campo de peso deve ficar vazio (null). Preencha com 0 se não for usar.");
      return;
    }
  }
  
  const r1 = parseInt(document.getElementById("fila-rule-1")?.value || 0);
  const r2 = parseInt(document.getElementById("fila-rule-2")?.value || 0);
  const r3 = parseInt(document.getElementById("fila-rule-3")?.value || 0);
  const r4 = parseInt(document.getElementById("fila-rule-4")?.value || 0);
  const r5 = parseInt(document.getElementById("fila-rule-5")?.value || 0);
  const r6 = parseInt(document.getElementById("fila-rule-6")?.value || 0);
  const r7 = parseInt(document.getElementById("fila-rule-7")?.value || 0);
  const paymentDays = parseInt(document.getElementById("fila-rule-payment-days")?.value || 15);
  
  const total = r1 + r2 + r3 + r4 + r5 + r6 + r7;
  if (total !== 100) {
    alert("Erro: A soma das porcentagens deve ser exatamente 100%.");
    return;
  }
  
  const capacity = parseInt(document.getElementById("fila-capacity")?.value || 25);
  
  if (!AppState.rules) AppState.rules = {};
  if (!AppState.rules.filaConfig) AppState.rules.filaConfig = {};
  
  AppState.rules.filaConfig[op] = {
    capacity: capacity,
    r1: r1,
    r2: r2,
    r3: r3,
    r4: r4,
    r5: r5,
    r6: r6,
    r7: r7,
    paymentDays: paymentDays
  };
  
  localStorage.setItem("crm_moura_rules", JSON.stringify(AppState.rules));
  alert(`Configuração da Fila de Cobrança para o operador '${op}' salva com sucesso!`);
};

