window.renderTempJudicialList = function() {
  const container = document.getElementById('jud-list-container');
  if (container) {
    if (window.tempJudicialList.length === 0) {
       container.innerHTML = `<div style="text-align: center; color: #94a3b8; padding: 20px; font-size: 0.9rem;">Nenhuma etapa configurada.</div>`;
       return;
    }
    container.innerHTML = window.tempJudicialList.map((opt, index) => {
      return `
      <div class="jud-item">
        <div style="display: flex; flex-direction: column; gap: 4px;">
           <span style="font-size: 0.95rem; color: #334155; font-weight: 600;">${opt.nome}</span>
           <span style="font-size: 0.8rem; color: #64748b;"><i data-lucide="clock" style="width: 12px; height: 12px; vertical-align: middle;"></i> ${opt.dias} dias estimados</span>
        </div>
        <button class="jud-trash-btn" onclick="removeJudicialFromList(${index})" title="Remover Etapa"><i data-lucide="trash-2" style="width: 16px; height: 16px;"></i></button>
      </div>
    `}).join('');
    if (typeof lucide !== 'undefined') lucide.createIcons();
  }
};

window.addJudicialToList = function() {
  const inputNome = document.getElementById('new-jud-nome');
  const inputDias = document.getElementById('new-jud-dias');
  const valNome = inputNome.value.trim();
  const valDias = parseInt(inputDias.value.trim()) || 0;
  
  if (!valNome) {
    alert('Digite o nome da etapa.');
    return;
  }
  
  const exists = window.tempJudicialList.find(x => x.nome.toLowerCase() === valNome.toLowerCase());
  if (exists) {
    alert('Esta etapa já existe na lista.');
    return;
  }
  
  window.tempJudicialList.push({
    id: 'j' + Date.now(),
    nome: valNome,
    dias: valDias
  });
  
  inputNome.value = '';
  inputDias.value = '';
  renderTempJudicialList();
  inputNome.focus();
};

window.removeJudicialFromList = function(index) {
  const opt = window.tempJudicialList[index];
  const rawOccurrences = localStorage.getItem("crm_moura_occurrences") || "[]";
  if (rawOccurrences.includes(opt.nome)) {
      alert(`Ação bloqueada: Não é possível excluir a etapa "${opt.nome}" pois ela já possui histórico registrado em cobranças judiciais.`);
      return;
  }
  window.tempJudicialList.splice(index, 1);
  renderTempJudicialList();
};

window.closeJudicialOptionsEditor = function() {
  const overlay = document.getElementById('judicial-options-overlay');
  if (overlay) {
    overlay.remove();
  }
};

window.saveJudicialOptionsList = function() {
  window.EtapasJudiciaisState = JSON.parse(JSON.stringify(window.tempJudicialList));
  localStorage.setItem("crm_moura_judiciais", JSON.stringify(window.EtapasJudiciaisState));
  
  if (window.renderEtapasJudiciais) window.renderEtapasJudiciais();
  if (window.updateJudFaseDropdown) window.updateJudFaseDropdown();
  
  closeJudicialOptionsEditor();
};

window.updateJudFaseDropdown = function() {
  const sel = document.getElementById("jud-fase");
  if(!sel) return;
  let html = `<option value="">Selecione...</option>`;
  if(window.EtapasJudiciaisState) {
    window.EtapasJudiciaisState.forEach(e => {
       html += `<option value="${e.nome}" data-dias="${e.dias}">${e.nome}</option>`;
    });
  }
  html += `<option value="Nota Interna">Nota Interna</option>`;
  sel.innerHTML = html;
};

window.handleJudFaseChange = function(sel) {
   const selectedOption = sel.options[sel.selectedIndex];
   const dias = selectedOption.getAttribute('data-dias');
   
   const prazoInput = document.getElementById('jud-prazo-date');
   const prazoRow = document.getElementById('jud-prazo-row');
   const prazoLabel = document.getElementById('jud-prazo-label');
   const pinRow = document.getElementById('jud-pin-row');
   const btnSave = document.getElementById('btn-save-jud-occurrence');

   if (sel.value === 'Nota Interna') {
       if (prazoRow) prazoRow.style.display = 'none';
       if (pinRow) pinRow.style.display = 'block';
       if (btnSave) btnSave.innerHTML = '<i data-lucide="save" style="width: 16px;"></i> Gravar nota interna';
       if (prazoInput) {
           prazoInput.removeAttribute('readonly');
           prazoInput.value = '';
       }
   } else {
       if (prazoRow) prazoRow.style.display = 'block';
       if (pinRow) pinRow.style.display = 'none';
       if (btnSave) btnSave.innerHTML = '<i data-lucide="save" style="width: 16px;"></i> Registrar Andamento';
       if (prazoLabel) prazoLabel.innerHTML = 'Prazo para resolução <span style="color: var(--color-danger);">*</span>';
       if (prazoInput) {
           prazoInput.setAttribute('readonly', 'true');
           if(dias && !isNaN(dias)) {
               const d = new Date();
               d.setDate(d.getDate() + parseInt(dias));
               prazoInput.value = d.toISOString().split('T')[0];
           } else {
               prazoInput.value = '';
           }
       }
   }
   if (typeof lucide !== 'undefined') lucide.createIcons();
};


window.removerEtapaJudicial = function(id) {
  const etapa = window.EtapasJudiciaisState.find(e => e.id === id);
  if (etapa) {
      const rawOccurrences = localStorage.getItem("crm_moura_occurrences") || "[]";
      if (rawOccurrences.includes(etapa.nome)) {
          alert(`Ação bloqueada: Não é possível excluir a etapa "${etapa.nome}" pois ela já possui histórico registrado em cobranças judiciais.`);
          return;
      }
      
      if (confirm(`Deseja realmente excluir a etapa "${etapa.nome}"?`)) {
          window.EtapasJudiciaisState = window.EtapasJudiciaisState.filter(e => e.id !== id);
          localStorage.setItem("crm_moura_judiciais", JSON.stringify(window.EtapasJudiciaisState));
          window.renderEtapasJudiciais();
      }
  }
};

window.saveAzureConfig = function() {
  const enabled = document.getElementById("azure-enable-chk").checked;
  const clientId = document.getElementById("azure-client-id").value.trim();
  const tenantId = document.getElementById("azure-tenant-id").value.trim();
  
  if (enabled && (!clientId || !tenantId)) {
    alert("Para habilitar o login Microsoft real, informe o Client ID e Tenant ID.");
    return;
  }

  MouraAuth.saveAuthConfig({ enabled, clientId, tenantId });
  alert("Configurações do Azure AD gravadas com sucesso! A página será reiniciada.");
  window.location.reload();
}

window.copyToClipboard = function(text, btn) {
  if (!text) return;
  navigator.clipboard.writeText(text).then(() => {
    if (!btn) return;
    const originalHTML = btn.innerHTML;
    
    // Obter as dimensões do ícone original para manter o tamanho
    let w = '13px', h = '13px', color = 'var(--color-primary)';
    const svg = btn.querySelector('svg') || btn.querySelector('i');
    if (svg && svg.style) {
        if (svg.style.width) w = svg.style.width;
        if (svg.style.height) h = svg.style.height;
    }

    btn.innerHTML = `<i data-lucide="check" style="width:${w}; height:${h}; color:var(--color-success);"></i>`;
    if (typeof lucide !== 'undefined') lucide.createIcons();
    
    let isReverted = false;
    const revert = () => {
        if (isReverted) return;
        isReverted = true;
        btn.innerHTML = originalHTML;
        if (typeof lucide !== 'undefined') lucide.createIcons();
        btn.removeEventListener('mouseleave', onMouseLeave);
        btn.removeEventListener('mouseenter', onMouseEnter);
    };

    const onMouseEnter = () => revert();
    const onMouseLeave = () => {
        btn.addEventListener('mouseenter', onMouseEnter);
    };

    // Só reverte quando o mouse sai e volta (ou por timeout de segurança)
    btn.addEventListener('mouseleave', onMouseLeave, { once: true });
    setTimeout(revert, 4000); // fallback
  }).catch(err => {
    console.error("Erro ao copiar:", err);
  });
};
window.copyCustomerName = function() {
  const nameEl = document.getElementById('det-name');
  if (!nameEl) return;
  const nameSpan = nameEl.querySelector('span');
  const name = nameSpan ? nameSpan.textContent.trim() : nameEl.innerText.trim();
  if (!name) return;
  const copyBtn = nameEl.querySelector('button');
  if (copyBtn) {
    copyToClipboard(name, copyBtn);
  } else {
    navigator.clipboard.writeText(name).catch(() => {});
  }
};

async function loadCustomerBoletos(customerId, saleId) {
  const container = document.getElementById("tab-boletos").querySelector('.crm-card');
  if (!container) return;

  container.innerHTML = `
    <h3 style="font-size: 1.1rem; color: var(--color-primary); margin-bottom: 15px;">Boletos do Contrato</h3>
    <p style="font-size: 0.9rem; color: #666;">Buscando boletos no Sienge...</p>
    <div class="loading-spinner" style="width:28px; height:28px; border:3px solid rgba(16,84,54,0.15); border-top-color:var(--color-primary); border-radius:50%; animation:spin 0.8s linear infinite; margin-top: 15px;"></div>
  `;

  try {
    let currentSale = (AppState.sales || []).find(s => String(s.id) === String(saleId) || String(s.receivableBillId) === String(saleId));
    let realCustomerId = currentSale && currentSale.customerId ? currentSale.customerId : customerId;
    
    const data = await SiengeApiService.getCustomerFinancialStatements(realCustomerId);
    if (!data || !data.results || data.results.length === 0) {
      container.innerHTML = `
        <h3 style="font-size: 1.1rem; color: var(--color-primary); margin-bottom: 15px;">Boletos do Contrato</h3>
        <p style="font-size: 0.9rem; color: #666;">Nenhum boleto encontrado (sem resultados financeiros).</p>
      `;
      return;
    }

    const firstResult = data.results[0];
    const billsReceivable = firstResult.billsReceivable || [];
    
    let billIdToMatch = currentSale ? (currentSale.receivableBillId || saleId) : saleId;
    
    // Filter by current contract
    const currentBill = billsReceivable.find(b => String(b.billReceivableId) === String(billIdToMatch) || String(b.receivableBillId) === String(billIdToMatch) || String(b.billReceivableId) === String(saleId));
    if (!currentBill) {
      container.innerHTML = `
        <h3 style="font-size: 1.1rem; color: var(--color-primary); margin-bottom: 15px;">Boletos do Contrato</h3>
        <p style="font-size: 0.9rem; color: #666;">Nenhum boleto encontrado para o contrato atual.</p>
      `;
      return;
    }

    let boletosHtml = `<table class="crm-table" style="width:100%; border-collapse:collapse; margin-top: 15px;">
      <thead>
        <tr style="background:#f5f5f5; text-align:left;">
          <th style="padding:10px; border-bottom:1px solid #ddd;">Título</th>
          <th style="padding:10px; border-bottom:1px solid #ddd;">Parcela</th>
          <th style="padding:10px; border-bottom:1px solid #ddd;">Venc. Orig.</th>
          <th style="padding:10px; border-bottom:1px solid #ddd;">Venc. Boleto</th>
          <th style="padding:10px; border-bottom:1px solid #ddd;">Valor Original</th>
          <th style="padding:10px; border-bottom:1px solid #ddd;">Valor Corrigido</th>
          <th style="padding:10px; border-bottom:1px solid #ddd;">Status</th>
          <th style="padding:10px; border-bottom:1px solid #ddd;">Ações</th>
        </tr>
      </thead>
      <tbody>`;
    
    let count = 0;
    
    (currentBill.installments || []).forEach(inst => {
      // Se não tem recibos, ou tem recibos mas nenhum tem receiptType preenchido = não está pago
      const isPaid = inst.receipts && inst.receipts.some(r => r.receiptType !== null && r.receiptType !== undefined);

      if (inst.generatedBillet === true && !isPaid) {
        count++;
        const dueDateObj = inst.dueDate ? new Date(inst.dueDate + 'T12:00:00') : null;
        const dueDateStr = dueDateObj ? dueDateObj.toLocaleDateString('pt-BR') : 'N/D';
        
        let diasAtraso = 0;
        let isOverdue = false;
        if (dueDateObj) {
            const today = new Date();
            today.setHours(0,0,0,0);
            const dueAtMidnight = new Date(dueDateObj);
            dueAtMidnight.setHours(0,0,0,0);
            diasAtraso = Math.floor((today - dueAtMidnight) / (1000 * 60 * 60 * 24));
            isOverdue = diasAtraso > 0;
        }

        const isBaixado = diasAtraso > 28;
        
        let statusBadge = '';
        if (isBaixado) {
            statusBadge = `<span style="background:var(--color-danger); color:#fff; padding:2px 6px; border-radius:4px; font-size:0.75rem;">Baixado (>28 dias)</span>`;
        } else if (isOverdue) {
            statusBadge = `<span style="background:var(--color-warning); color:#fff; padding:2px 6px; border-radius:4px; font-size:0.75rem; color:#856404; background-color:#fff3cd; border: 1px solid #ffeeba;">Vencido, mas cliente pode pagar</span>`;
        } else {
            statusBadge = `<span style="background:var(--color-primary); color:#fff; padding:2px 6px; border-radius:4px; font-size:0.75rem;">A Vencer</span>`;
        }

        let actionsHtml = '';
        if (isBaixado) {
            actionsHtml = `<button class="btn btn-primary btn-sm btn-reprocess-${inst.installmentId}" style="font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; background:var(--color-danger); border-color:var(--color-danger);" onclick="reprocessBoleto(${saleId}, ${inst.installmentId}, ${currentBill.costCenterId})"><i data-lucide="refresh-cw" style="width:12px;height:12px;"></i> Reprocessar Boleto</button>`;
        } else {
            actionsHtml = `<button class="btn btn-primary btn-sm btn-view-${inst.installmentId}" style="font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; white-space: nowrap;" onclick="openBoletoPdf(${saleId}, ${inst.installmentId}, this)"><i data-lucide="file-text" style="width:12px;height:12px;"></i> Ver Boleto</button>
                           <button class="btn btn-outline btn-sm btn-download-${inst.installmentId}" style="font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; margin-left: 5px; white-space: nowrap;" onclick="downloadBoletoPdf(${saleId}, ${inst.installmentId}, this)"><i data-lucide="download" style="width:12px;height:12px;"></i> Download</button>`;
        }
        
        const valorCorrigido = inst.correctedValue || inst.balanceDue || inst.originalValue || 0;
        
        boletosHtml += `
          <tr id="row-inst-${inst.installmentId}">
            <td style="padding:10px; border-bottom:1px solid #eee; font-weight:600; color:var(--color-primary);">${currentBill.billReceivableId || currentBill.documentCode || 'N/D'}</td>
            <td style="padding:10px; border-bottom:1px solid #eee;">${inst.installmentNumber || 'N/D'}</td>
            <td style="padding:10px; border-bottom:1px solid #eee;">${dueDateStr}</td>
            <td style="padding:10px; border-bottom:1px solid #eee;" id="true-due-date-${inst.installmentId}">Buscando...</td>
            <td style="padding:10px; border-bottom:1px solid #eee;">${new Intl.NumberFormat('pt-BR', {style: 'currency', currency: 'BRL'}).format(inst.originalValue || 0)}</td>
            <td style="padding:10px; border-bottom:1px solid #eee; color:var(--color-danger); font-weight:bold;" id="valor-corrigido-${inst.installmentId}">${new Intl.NumberFormat('pt-BR', {style: 'currency', currency: 'BRL'}).format(valorCorrigido)}</td>
            <td style="padding:10px; border-bottom:1px solid #eee;" id="status-badge-${inst.installmentId}">${statusBadge}</td>
            <td style="padding:10px; border-bottom:1px solid #eee;" id="actions-col-${inst.installmentId}">${actionsHtml}</td>
          </tr>
        `;
      }
    });

    boletosHtml += `</tbody></table>`;
    
    if (count === 0) {
      container.innerHTML = `
        <h3 style="font-size: 1.1rem; color: var(--color-primary); margin-bottom: 15px;">Boletos do Contrato</h3>
        <p style="font-size: 0.9rem; color: #666;">Não há boletos gerados e em aberto para este contrato no momento.</p>
      `;
    } else {
      container.innerHTML = `
        <h3 style="font-size: 1.1rem; color: var(--color-primary); margin-bottom: 15px; display: flex; align-items: center;">Boletos do Contrato <span style="background:var(--color-primary); color:#fff; padding:2px 8px; border-radius:12px; font-size:0.8rem; margin-left:8px;">${count}</span></h3>
        <p style="font-size: 0.9rem; color: #666;">Aqui estão os boletos disponíveis (não pagos) para o contrato atual.</p>
        ${boletosHtml}
      `;
    }
    
    if (window.lucide) {
      lucide.createIcons();
    }

    // Busca assíncrona das datas verdadeiras e status baseado no código de barras
    setTimeout(async () => {
      for (const inst of (currentBill.installments || [])) {
        const isPaid = inst.receipts && inst.receipts.some(r => r.receiptType !== null && r.receiptType !== undefined);
        if (inst.generatedBillet === true && !isPaid) {
          try {
            const slip = await SiengeApiService.getPaymentSlipNotification(saleId, inst.installmentId);
            let trueDateStr = 'N/D';
            let dtFebraban = null;
            if (slip && slip.results && slip.results.length > 0) {
               const digitable = slip.results[0].digitableNumber || "";
               const clean = digitable.replace(/\D/g, '');
               if (clean.length >= 47) {
                  const factor = parseInt(clean.substring(33, 37), 10);
                  if (factor >= 1000) {
                     let totalDays = factor;
                     if (factor < 5000 && new Date().getFullYear() >= 2025) {
                        totalDays += 9000; // Rollover 2025
                     }
                     dtFebraban = new Date(new Date('1997-10-07T12:00:00Z').getTime() + (totalDays * 24 * 60 * 60 * 1000));
                     trueDateStr = dtFebraban.toLocaleDateString('pt-BR');
                  }
                  
                  const valueCents = parseInt(clean.substring(37, 47), 10);
                  if (!isNaN(valueCents) && valueCents > 0) {
                     const realValue = valueCents / 100;
                     const tdValue = document.getElementById(`valor-corrigido-${inst.installmentId}`);
                     if (tdValue) {
                         tdValue.textContent = new Intl.NumberFormat('pt-BR', {style: 'currency', currency: 'BRL'}).format(realValue);
                     }
                  }
               }
            }
            
            const tdDate = document.getElementById(`true-due-date-${inst.installmentId}`);
            if (tdDate) tdDate.textContent = trueDateStr;

            if (dtFebraban) {
               // Recalcula o atraso baseado na data do boleto
               const today = new Date();
               today.setHours(0,0,0,0);
               dtFebraban.setHours(0,0,0,0);
               const diasAtraso = Math.floor((today - dtFebraban) / (1000 * 60 * 60 * 24));
               const isBaixado = diasAtraso > 28;
               const isOverdue = diasAtraso > 0;
               
               const tdBadge = document.getElementById(`status-badge-${inst.installmentId}`);
               const tdActions = document.getElementById(`actions-col-${inst.installmentId}`);
               
               if (tdBadge && tdActions) {
                  if (isBaixado) {
                      tdBadge.innerHTML = `<span style="background:var(--color-danger); color:#fff; padding:2px 6px; border-radius:4px; font-size:0.75rem;">Baixado (> 28 dias)</span>`;
                      tdActions.innerHTML = `<button class="btn btn-primary btn-sm" style="font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; background:var(--color-danger); border-color:var(--color-danger);" onclick="reprocessBoleto(${saleId}, ${inst.installmentId}, ${currentBill.costCenterId})"><i data-lucide="refresh-cw" style="width:12px;height:12px;"></i> Reprocessar Boleto</button>`;
                  } else if (isOverdue) {
                      const diasValidade = 28 - diasAtraso;
                      tdBadge.innerHTML = `<span style="background:var(--color-warning); color:#fff; padding:2px 6px; border-radius:4px; font-size:0.75rem; color:#856404; background-color:#fff3cd; border: 1px solid #ffeeba;">Vencido (válido por ${diasValidade} dias)</span>`;
                      tdActions.innerHTML = `<button class="btn btn-primary btn-sm" style="font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; white-space: nowrap;" onclick="openBoletoPdf(${saleId}, ${inst.installmentId}, this)"><i data-lucide="file-text" style="width:12px;height:12px;"></i> Ver Boleto</button>
                                             <button class="btn btn-outline btn-sm" style="font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; margin-left: 5px; white-space: nowrap;" onclick="downloadBoletoPdf(${saleId}, ${inst.installmentId}, this)"><i data-lucide="download" style="width:12px;height:12px;"></i> Download</button>`;
                  } else {
                      tdBadge.innerHTML = `<span style="background:var(--color-primary); color:#fff; padding:2px 6px; border-radius:4px; font-size:0.75rem;">A Vencer</span>`;
                      tdActions.innerHTML = `<button class="btn btn-primary btn-sm" style="font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; white-space: nowrap;" onclick="openBoletoPdf(${saleId}, ${inst.installmentId}, this)"><i data-lucide="file-text" style="width:12px;height:12px;"></i> Ver Boleto</button>
                                             <button class="btn btn-outline btn-sm" style="font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; margin-left: 5px; white-space: nowrap;" onclick="downloadBoletoPdf(${saleId}, ${inst.installmentId}, this)"><i data-lucide="download" style="width:12px;height:12px;"></i> Download</button>`;
                  }
                  if (window.lucide) lucide.createIcons();
               }
            } else {
               const tdDate = document.getElementById(`true-due-date-${inst.installmentId}`);
               if (tdDate) tdDate.textContent = 'Não disponivel';
            }
          } catch(e) {
             const tdDate = document.getElementById(`true-due-date-${inst.installmentId}`);
             if (tdDate) tdDate.textContent = 'Erro';
          }
        }
      }
    }, 100);


  } catch (error) {
    console.error("Erro ao carregar boletos do cliente:", error);
    container.innerHTML = `
      <h3 style="font-size: 1.1rem; color: var(--color-primary); margin-bottom: 15px;">Boletos do Contrato</h3>
      <p style="font-size: 0.9rem; color: var(--color-danger);">Erro ao buscar dados na API.</p>
    `;
  }
}

async function gerarInformeRendimentos() {
  const resultContainer = document.getElementById("informe-rendimentos-result");
  const yearInput = document.getElementById("informe-year");
  const year = yearInput ? yearInput.value : new Date().getFullYear() - 1;

  if (!AppState.selectedCustomerId || !AppState.selectedSaleId) {
    resultContainer.innerHTML = `<p style="color: var(--color-danger); font-size: 0.9rem; margin-top: 10px;">Selecione um cliente e contrato primeiro.</p>`;
    return;
  }

  const salesList = (typeof getSiengeApiMode === 'function' && getSiengeApiMode() === "simulado") ? window.MOCK_DATA.SALES : (AppState.sales && AppState.sales.length > 0 ? AppState.sales : []);
  const currentSale = salesList.find(s => String(s.id) === String(AppState.selectedSaleId) || String(s.receivableBillId) === String(AppState.selectedSaleId));
  if (!currentSale) {
    resultContainer.innerHTML = `<p style="color: var(--color-danger); font-size: 0.9rem; margin-top: 10px;">Contrato não encontrado.</p>`;
    return;
  }

  const companyId = currentSale.companyId || 2;
  const customerId = AppState.selectedCustomerId;

  resultContainer.innerHTML = `<div style="display:flex; align-items:center; gap:8px; margin-top: 10px;"><div class="loading-spinner" style="width:16px; height:16px; border:2px solid rgba(16,84,54,0.15); border-top-color:var(--color-primary); border-radius:50%; animation:spin 0.8s linear infinite;"></div> <span style="font-size: 0.9rem; color: #666;">Gerando informe de rendimentos para ${year}...</span></div>`;

  try {
    const res = await SiengeApiService.getCustomerIncomeTaxReportPdf(customerId, companyId, year);
    
    let urlReport = null;
    if (res && res.results && res.results.length > 0) {
      if (res.results[0].urlReport) urlReport = res.results[0].urlReport;
      else if (res.results[0].value) urlReport = res.results[0].value;
      else if (typeof res.results[0] === 'string') urlReport = res.results[0];
    } else if (typeof res === 'string') {
      urlReport = res;
    }
    
    if (urlReport) {
      const customer = getCustomerFromState(customerId) || { name: "CLIENTE" };
      const customerName = customer.name;
      
      resultContainer.innerHTML = `
        <div style="margin-top: 15px; padding: 15px; background: rgba(16,84,54,0.05); border: 1px solid rgba(16,84,54,0.1); border-radius: 6px;">
          <p style="color: var(--color-primary); font-weight: 600; margin-bottom: 10px; font-size: 0.95rem;">
            <i data-lucide="check-circle" style="width: 16px; color: var(--color-success); vertical-align: middle;"></i> Informe gerado com sucesso!
          </p>
          <a href="${urlReport}" target="_blank" class="btn btn-outline" style="text-decoration: none; display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; font-size: 0.85rem;">
            <i data-lucide="external-link" style="width: 14px;"></i> Abrir ${customerName.toUpperCase()} - INFORME DE RENDIMENTO ${year}
          </a>
        </div>
      `;
      if (window.lucide) lucide.createIcons();
      
      const newWin = window.open(urlReport, '_blank');
      if (newWin) {
          console.log(`Informe aberto: INFORME DE RENDIMENTO ${year} - ${customerName}`);
      } else {
          alert('Por favor, permita pop-ups para abrir o relatório automaticamente.');
      }
    } else {
      resultContainer.innerHTML = `<p style="color: var(--color-danger); font-size: 0.9rem; margin-top: 10px;">Não foi possível gerar o informe para o ano ${year}. (Sem retorno da API)</p>`;
    }
  } catch (error) {
    console.error("Erro ao gerar informe de rendimentos:", error);
    resultContainer.innerHTML = `<p style="color: var(--color-danger); font-size: 0.9rem; margin-top: 10px;">Erro ao comunicar com a API Sienge: ${error.message}</p>`;
  }
}

