window.selectDocTemplate = function(type) {
  document.querySelectorAll('.doc-menu-item').forEach(el => el.classList.remove('active'));
  document.querySelectorAll('.doc-editor-form').forEach(el => el.classList.remove('active'));
  
  const menuEl = document.getElementById(`menu-doc-${type}`);
  const editorEl = document.getElementById(`editor-${type}`);
  
  if (menuEl) menuEl.classList.add('active');
  if (editorEl) editorEl.classList.add('active');
};

window.copyVar = function(el) {
  const text = el.innerText;
  navigator.clipboard.writeText(text).then(() => {
    const oldText = el.innerText;
    el.innerText = 'Copiado!';
    setTimeout(() => { el.innerText = oldText; }, 1000);
  });
};

function saveDocPadrao(tipo) {
  const keyMap = {
    reneg: ['doc-reneg-title', 'doc-reneg-subtitle', 'doc-reneg-clauses'],
    boleto: ['doc-boleto-inst1', 'doc-boleto-inst2', 'doc-boleto-obs'],
    carta: ['doc-carta-assunto', 'doc-carta-saudacao', 'doc-carta-corpo', 'doc-carta-assinatura'],
    distrato: ['doc-distrato-title', 'doc-distrato-pct', 'doc-distrato-clauses'],
  };
  const ids = keyMap[tipo] || [];
  const data = {};
  ids.forEach(id => {
    const el = document.getElementById(id);
    if (el) data[id] = el.value;
  });
  localStorage.setItem(`crm_docpadrao_${tipo}`, JSON.stringify(data));
  
  // Feedback visual
  const btn = document.querySelector(`[onclick="saveDocPadrao('${tipo}')"]`);
  if (btn) {
    const orig = btn.innerHTML;
    btn.innerHTML = '<i data-lucide="check" style="width:13px;"></i> Salvo!';
    btn.style.background = 'var(--color-success, #16a34a)';
    btn.style.color = '#fff';
    setTimeout(() => { btn.innerHTML = orig; btn.style.background = ''; btn.style.color = ''; lucide.createIcons(); }, 2000);
  }
  
  // Carregar templates salvos no editor de cláusulas da reneg se tipo for reneg
  if (tipo === 'reneg') {
    const clausesEl = document.getElementById('reneg-clauses-editor');
    if (clausesEl && data['doc-reneg-clauses']) {
      clausesEl.value = data['doc-reneg-clauses'];
    }
  }
}

function previewDocPadrao(tipo) {
  const labelMap = {
    reneg: 'Termo de Acordo',
    boleto: 'Boleto de Cobrança',
    carta: 'Carta de Cobrança',
    distrato: 'Distrato / Rescisão',
  };
  const label = labelMap[tipo] || tipo;
  const data = JSON.parse(localStorage.getItem(`crm_docpadrao_${tipo}`) || '{}');
  let content = '';
  if (tipo === 'reneg') {
    const title = document.getElementById('doc-reneg-title')?.value || '';
    const subtitle = document.getElementById('doc-reneg-subtitle')?.value || '';
    const clauses = document.getElementById('doc-reneg-clauses')?.value || '';
    content = `<h2 style="text-align:center;">${title}</h2><p style="text-align:center;color:#666;">${subtitle}</p><hr><pre style="white-space:pre-wrap;font-family:serif;font-size:14px;line-height:1.6;">${clauses}</pre>`;
  } else if (tipo === 'boleto') {
    const inst1 = document.getElementById('doc-boleto-inst1')?.value || '';
    const inst2 = document.getElementById('doc-boleto-inst2')?.value || '';
    const obs = document.getElementById('doc-boleto-obs')?.value || '';
    content = `<h2>Prévia de Instruções do Boleto</h2><p><strong>Instrução 1:</strong> ${inst1}</p><p><strong>Instrução 2:</strong> ${inst2}</p><p><strong>Observações:</strong> ${obs}</p>`;
  } else if (tipo === 'carta') {
    const assunto = document.getElementById('doc-carta-assunto')?.value || '';
    const saudacao = document.getElementById('doc-carta-saudacao')?.value || '';
    const corpo = document.getElementById('doc-carta-corpo')?.value || '';
    const assinatura = document.getElementById('doc-carta-assinatura')?.value || '';
    content = `<h2>Prévia: ${assunto}</h2><p>${saudacao}</p><pre style="white-space:pre-wrap;font-family:serif;font-size:14px;line-height:1.6;">${corpo}</pre><br><p><strong>${assinatura}</strong></p>`;
  } else if (tipo === 'distrato') {
    const title = document.getElementById('doc-distrato-title')?.value || '';
    const pct = document.getElementById('doc-distrato-pct')?.value || '';
    const clauses = document.getElementById('doc-distrato-clauses')?.value || '';
    content = `<h2 style="text-align:center;">${title}</h2><p><strong>Percentual de Retenção Padrão:</strong> ${pct}%</p><hr><pre style="white-space:pre-wrap;font-family:serif;font-size:14px;line-height:1.6;">${clauses}</pre>`;
  }
  
  const win = window.open('', '_blank', 'width=700,height=600,scrollbars=yes');
  if (win) {
    win.document.write(`<!DOCTYPE html><html><head><title>Prévia - ${label}</title><style>body{font-family:Georgia,serif;padding:40px;max-width:700px;margin:auto;color:#222;}h2{color:#105436;}hr{border:1px solid #ccc;}</style></head><body>${content}<hr><p style="font-size:12px;color:#999;">Prévia gerada pelo CRM Moura Leite — Documentos Padrões</p></body></html>`);
    win.document.close();
  }
}

// Carregar templates salvos ao inicializar
function loadDocPadraoTemplates() {
  const tipos = ['reneg', 'boleto', 'carta', 'distrato'];
  const fieldMap = {
    reneg: ['doc-reneg-title', 'doc-reneg-subtitle', 'doc-reneg-clauses'],
    boleto: ['doc-boleto-inst1', 'doc-boleto-inst2', 'doc-boleto-obs'],
    carta: ['doc-carta-assunto', 'doc-carta-saudacao', 'doc-carta-corpo', 'doc-carta-assinatura'],
    distrato: ['doc-distrato-title', 'doc-distrato-pct', 'doc-distrato-clauses'],
  };
  tipos.forEach(tipo => {
    const saved = localStorage.getItem(`crm_docpadrao_${tipo}`);
    if (saved) {
      try {
        const data = JSON.parse(saved);
        (fieldMap[tipo] || []).forEach(id => {
          const el = document.getElementById(id);
          if (el && data[id] !== undefined) el.value = data[id];
        });
      } catch(e) {}
    }
  });
}

