window.loadRelacionamentoUnidades = async function(cc) {
  const selectUnidade = document.getElementById('relacionamento-filter-unidade');
  if (!selectUnidade) return;

  selectUnidade.innerHTML = '<option value="">Carregando unidades...</option>';
  selectUnidade.disabled = true;

  if (!cc) {
    selectUnidade.innerHTML = '<option value="">Selecione um empreendimento primeiro...</option>';
    return;
  }

  try {
    let allUnits = [];
    let offset = 0;
    const limit = 200;
    let hasMore = true;

    while (hasMore) {
      const port = (window.location.port === "5500" || !window.location.port) ? "3000" : window.location.port;
      const host = (window.location.hostname === "" || window.location.hostname === "127.0.0.1") ? "localhost" : window.location.hostname;
      const url = `http://${host}:${port}/sienge-proxy/units?limit=${limit}&offset=${offset}&enterpriseId=${cc}&additionalData=NONE`;
      
      const res = await fetch(url, { headers: { 'Authorization': window.getBasicAuthHeader ? getBasicAuthHeader() : '' } });
      if (!res.ok) throw new Error("Falha Sienge HTTP " + res.status);
      
      const data = await res.json();
      const results = data.results || [];
      allUnits = allUnits.concat(results);
      
      if (results.length === 0) {
        hasMore = false;
      } else {
        offset += results.length;
      }
    }

    allUnits = allUnits.filter(u => u.commercialStock !== 'T');
    allUnits.sort((a, b) => {
      if (!a.name) return 1;
      if (!b.name) return -1;
      return a.name.toString().localeCompare(b.name.toString(), undefined, { numeric: true, sensitivity: 'base' });
    });

    selectUnidade.innerHTML = '<option value="">Selecione uma unidade...</option>';
    
    // Buscar contratos para mostrar cliente
    const port = (window.location.port === "5500" || !window.location.port) ? "3000" : window.location.port;
    const host = (window.location.hostname === "" || window.location.hostname === "127.0.0.1") ? "localhost" : window.location.hostname;
    
    for (const u of allUnits) {
      selectUnidade.innerHTML += `<option value="${u.id}">${u.name}</option>`;
    }
    
    selectUnidade.disabled = false;

  } catch (e) {
    console.error(e);
    selectUnidade.innerHTML = '<option value="">Erro ao carregar unidades</option>';
  }
};

window.toggleRelacionamentoFilters = function() {
  const nome = document.getElementById('relacionamento-filter-nome');
  const tel = document.getElementById('relacionamento-filter-telefone');
  const email = document.getElementById('relacionamento-filter-email');
  const doc = document.getElementById('relacionamento-filter-doc');
  const titulo = document.getElementById('relacionamento-filter-titulo');
  const contrato = document.getElementById('relacionamento-filter-contrato');
  const emp = document.getElementById('relacionamento-filter-emp');
  const uni = document.getElementById('relacionamento-filter-unidade');

  const hasNome = nome && nome.value.trim() !== '';
  const hasTel = tel && tel.value.trim() !== '';
  const hasEmail = email && email.value.trim() !== '';
  const hasDoc = doc && doc.value.trim() !== '';
  const hasTitulo = titulo && titulo.value.trim() !== '';
  const hasContrato = contrato && contrato.value.trim() !== '';
  const hasEmp = emp && emp.value !== '';

  if (nome) nome.disabled = hasTel || hasEmail || hasDoc || hasTitulo || hasContrato || hasEmp;
  if (tel) tel.disabled = hasNome || hasEmail || hasDoc || hasTitulo || hasContrato || hasEmp;
  if (email) email.disabled = hasNome || hasTel || hasDoc || hasTitulo || hasContrato || hasEmp;
  if (doc) doc.disabled = hasNome || hasTel || hasEmail || hasTitulo || hasContrato || hasEmp;
  if (titulo) titulo.disabled = hasNome || hasTel || hasEmail || hasDoc || hasContrato || hasEmp;
  if (contrato) contrato.disabled = hasNome || hasTel || hasEmail || hasDoc || hasTitulo || hasEmp;
  if (emp) emp.disabled = hasNome || hasTel || hasEmail || hasDoc || hasTitulo || hasContrato;
  if (uni) uni.disabled = !hasEmp || hasNome || hasTel || hasEmail || hasDoc || hasTitulo || hasContrato;
};

