  const n = document.getElementById('relacionamento-filter-nome'); if (n) n.value = '';
  const t = document.getElementById('relacionamento-filter-telefone'); if (t) t.value = '';
  const e = document.getElementById('relacionamento-filter-email'); if (e) e.value = '';
  const doc = document.getElementById('relacionamento-filter-doc'); if (doc) doc.value = '';
  const titulo = document.getElementById('relacionamento-filter-titulo'); if (titulo) titulo.value = '';
  const contrato = document.getElementById('relacionamento-filter-contrato'); if (contrato) contrato.value = '';
  const emp = document.getElementById('relacionamento-filter-emp'); if (emp) emp.value = '';
  const uni = document.getElementById('relacionamento-filter-unidade');
  if (uni) {
    uni.innerHTML = '<option value="">Selecione o emp...</option>';
    uni.value = '';
    uni.disabled = true;
  }

  window.SelectedDynamicCustomerDoc = null;
  window.SelectedDynamicCustomerId = null;
  window.SelectedDynamicCustomerName = null;
