window.saveJudicialOccurrence = function() {
  const faseEl = document.getElementById("jud-fase");
  const noteEl = document.getElementById("jud-note-text");
  const prazoEl = document.getElementById("jud-prazo-date");
  const pinEl = document.getElementById("jud-pin-checkbox");

  const fase = faseEl ? faseEl.value : "";
  const text = noteEl ? noteEl.value.trim().toUpperCase() : "";
  const prazo = prazoEl ? prazoEl.value : "";
  const isPinned = pinEl ? pinEl.checked : false;

  if (!fase) {
    alert("Selecione o Andamento/Fase Processual.");
    return;
  }
  if (!text) {
    alert("Descreva os detalhes da ocorrência judicial.");
    return;
  }
  
  if (fase !== 'Nota Interna') {
    if (!prazo) {
      alert("Informe o prazo para resolução.");
      return;
    }
  }

  const occurrence = {
    id: 'jud_' + Date.now(),
    date: new Date().toISOString(),
    author: AppState.currentUser ? AppState.currentUser.name : "Advogado",
    fase: fase,
    text: text,
    prazo: (fase !== 'Nota Interna') ? prazo : null,
    pinned: isPinned,
    type: "Judicial"
  };

  if (!AppState.judNotes) {
    const local = localStorage.getItem("crm_moura_jud_notes");
    AppState.judNotes = local ? JSON.parse(local) : {};
  }
  const localJudNotes = localStorage.getItem("crm_moura_jud_notes");
  if (localJudNotes) {
    AppState.judNotes = JSON.parse(localJudNotes);
  }

  if (!AppState.judNotes[AppState.selectedCustomerId]) {
    AppState.judNotes[AppState.selectedCustomerId] = [];
  }
  
  AppState.judNotes[AppState.selectedCustomerId].push(occurrence);
  localStorage.setItem("crm_moura_jud_notes", JSON.stringify(AppState.judNotes));

  // Clear fields
  if(faseEl) faseEl.value = "";
  if(noteEl) noteEl.value = "";
  if(prazoEl) prazoEl.value = "";
  if(pinEl) pinEl.checked = false;

  // Restore defaults
  const prazoRow = document.getElementById('jud-prazo-row');
  const pinRow = document.getElementById('jud-pin-row');
  if (prazoRow) prazoRow.style.display = 'block';
  if (pinRow) pinRow.style.display = 'none';

  window.renderJudicialTimeline();
};

window.filterJudicialHistory = function(filter, btnEl) {
  const container = document.getElementById('jud-history-filters');
  if (container) {
    const btns = container.querySelectorAll('.btn');
    btns.forEach(b => {
      b.style.background = 'transparent';
      b.style.color = 'var(--color-primary)';
    });
    if (btnEl) {
      btnEl.style.background = 'var(--color-primary)';
      btnEl.style.color = 'white';
    }
  }
  
  window.currentJudicialHistoryFilter = filter;
  window.renderJudicialTimeline();
};

window.saveProcessNumber = function(value) {
    if (!AppState.selectedCustomerId) return;
    if (!AppState.judicialProcessNumbers) AppState.judicialProcessNumbers = {};
    AppState.judicialProcessNumbers[AppState.selectedCustomerId] = value;
    localStorage.setItem("crm_moura_jud_processes", JSON.stringify(AppState.judicialProcessNumbers));
};

window.copiarEConsultarProcesso = function() {
    const processInput = document.getElementById("jud-process-number");
    if (processInput && processInput.value.trim() !== "") {
        const val = processInput.value.trim();
        const urlParams = `&numero_processo=${val}&numero=${val}&txtNumProcesso=${val}&processo=${val}`;
        const eprocUrl = `https://eproc-consulta.tjsp.jus.br/consulta_1g/externo_controlador.php?acao=tjsp@consulta_unificada_publica/consultar${urlParams}`;

        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(val).then(() => {
                alert("Número " + val + " copiado para a área de transferência!\nCole-o (Ctrl+V) na página de Consulta do Tribunal, caso não preencha sozinho.");
                window.open(eprocUrl, "_blank");
            }).catch(err => {
                window.open(eprocUrl, "_blank");
            });
        } else {
            // Fallback
            processInput.select();
            document.execCommand('copy');
            alert("Número copiado!\nCole-o (Ctrl+V) na página de Consulta do Tribunal, caso não preencha sozinho.");
            window.open(eprocUrl, "_blank");
        }
    } else {
        alert("Por favor, preencha o número do processo primeiro.");
    }
};

window.renderJudicialTimeline = function() {
  const container = document.getElementById("jud-timeline");
  if (!container) return;

  const processInput = document.getElementById("jud-process-number");
  if (processInput && AppState.selectedCustomerId) {
      if (!AppState.judicialProcessNumbers) {
          AppState.judicialProcessNumbers = JSON.parse(localStorage.getItem("crm_moura_jud_processes") || "{}");
      }
      processInput.value = AppState.judicialProcessNumbers[AppState.selectedCustomerId] || "";
  }

  if (!AppState.judNotes) {
    const local = localStorage.getItem("crm_moura_jud_notes");
    AppState.judNotes = local ? JSON.parse(local) : {};
  }

  let list = [...(AppState.judNotes[AppState.selectedCustomerId] || [])];
  
  if (window.currentJudicialHistoryFilter && window.currentJudicialHistoryFilter !== 'Todos') {
    list = list.filter(occ => {
      if (window.currentJudicialHistoryFilter === 'Nota interna' && occ.fase === 'Nota Interna') return true;
      if (window.currentJudicialHistoryFilter === 'Etapa' && occ.fase !== 'Nota Interna') return true;
      return false;
    });
  }
  
  if (list.length === 0) {
    container.innerHTML = '<span style="color: #999; font-size: 0.85rem;">Nenhum andamento encontrado.</span>';
    container.style.display = 'flex';
    container.style.alignItems = 'center';
    container.style.justifyContent = 'center';
    return;
  }
  
  container.style.display = 'block';
  
  // Sort: pinned first, then descending by date
  list.sort((a, b) => {
    if (a.pinned && !b.pinned) return -1;
    if (!a.pinned && b.pinned) return 1;
    return new Date(b.date) - new Date(a.date);
  });

  let mostRecentOccId = null;
  if (list.length > 0) {
    mostRecentOccId = list.reduce((a, b) => new Date(a.date) > new Date(b.date) ? a : b).id;
  }

  const today = new Date();
  today.setHours(0,0,0,0);

  let html = `<div style="display:flex; flex-direction:column; gap:12px;">`;
  
  list.forEach((occ, index) => {
    const d = new Date(occ.date);
    const dateStr = d.toLocaleDateString("pt-BR") + " " + d.toLocaleTimeString("pt-BR", {hour: '2-digit', minute:'2-digit'});
    
    let isExpired = false;
    let prazoHtml = "";
    if (occ.prazo) {
      const pDate = new Date(occ.prazo + "T00:00:00");
      isExpired = pDate < today;
      const color = isExpired ? "var(--color-danger)" : "var(--color-primary)";
      const icon = isExpired ? "alert-circle" : "calendar";
      const textPrazo = isExpired ? "Prazo Vencido" : "Prazo Estimado";
      prazoHtml = `
        <div style="font-size: 0.75rem; display: flex; align-items: center; gap: 4px; color: ${color}; font-weight: 600; text-align: right;">
          <i data-lucide="${icon}" style="width: 12px; height: 12px;"></i>
          ${textPrazo}: ${pDate.toLocaleDateString("pt-BR")}
        </div>
      `;
    }

    let repetirBtnHtml = "";
    if (occ.id === mostRecentOccId && !isExpired && occ.fase !== 'Nota Interna') {
        repetirBtnHtml = `
            <button class="btn btn-outline btn-sm" type="button" onclick="window.repeatJudicialOcc(${index})" style="padding: 2px 6px; font-size: 0.65rem; display: inline-flex; align-items: center; gap: 2px; margin-left: 4px;">
               <i data-lucide="copy" style="width: 10px; height: 10px;"></i> Repetir
            </button>
        `;
    }

    const isCancelled = occ.status === "Cancelada";
    
    let cancelInfoHtml = "";
    if (isCancelled) {
      cancelInfoHtml = `
        <div style="font-size:0.75rem; color:var(--color-danger); font-weight:700; display: flex; align-items: center; gap: 4px; margin-top: 4px;">
          <i data-lucide="alert-triangle" style="width: 14px; height: 14px;"></i> Cancelada: "${occ.cancelReason || ''}"
        </div>
      `;
    }

    const elapsedMs = new Date() - new Date(occ.date);
    const isWithin24h = elapsedMs <= 24 * 60 * 60 * 1000;
    const currentUser = window.currentUser || (AppState.currentUser ? AppState.currentUser.name : null) || "OPERADOR";
    const isAuthor = currentUser && (occ.author === currentUser || currentUser === "Operador"); 
    
    let judActionsHtml = "";
    if (!isCancelled) {
      let btns = [];
      if (isWithin24h && isAuthor) {
          btns.push(`
            <button class="btn btn-outline btn-sm" style="padding: 2px 6px; font-size: 0.65rem; display: inline-flex; align-items: center; gap: 2px;" onclick="editJudicialOccReal(${AppState.selectedCustomerId}, '${occ.date}')">
              <i data-lucide="edit-3" style="width:10px; height:10px;"></i> Editar
            </button>
            <button class="btn btn-outline btn-sm" style="padding: 2px 6px; font-size: 0.65rem; border-color: rgba(211, 47, 47, 0.3); color: #d32f2f; display: inline-flex; align-items: center; gap: 2px;" onclick="cancelJudicialOcc(${AppState.selectedCustomerId}, '${occ.date}')">
              <i data-lucide="trash-2" style="width:10px; height:10px;"></i> Excluir
            </button>
          `);
      } else if (!isWithin24h && isAuthor) {
          btns.push(`
            <button class="btn btn-outline btn-sm" style="padding: 2px 6px; font-size: 0.65rem; display: inline-flex; align-items: center; gap: 2px;" onclick="errataJudicialOcc(${AppState.selectedCustomerId}, '${occ.date}')">
              <i data-lucide="file-edit" style="width:10px; height:10px;"></i> Errata
            </button>
          `);
      }
      
      if (btns.length > 0) {
        judActionsHtml = `<div style="display: flex; gap: 4px;">${btns.join('')}</div>`;
      }
    }

    let pastTextsHtml = '';
    if (occ.pastTexts && occ.pastTexts.length > 0) {
      pastTextsHtml = occ.pastTexts.map(t => `<del style="color: var(--color-text-muted);">${t}</del>`).join('<br>') + '<br>';
    }
    
    let mainText = occ.text;
    if (isCancelled) {
      mainText = `<del style="color: var(--color-text-muted);">${mainText}</del>`;
    }

    let pinBtnHtml = "";
    if (occ.fase === 'Nota Interna') {
        pinBtnHtml = `
            <button class="btn btn-outline btn-sm" type="button" onclick="window.toggleReplyInput('${occ.date}')" style="padding: 2px 6px; font-size: 0.65rem; display: inline-flex; align-items: center; gap: 2px; margin-left: 4px;">
               <i data-lucide="message-square" style="width: 10px; height: 10px;"></i> Responder
            </button>
        `;
    }

    let pinBadge = ''; // Removido do formato antigo
    let cardStyle = `background: white; border-radius: 6px; padding: 12px; border: 1px solid #e2e8f0; border-left: 3px solid ${occ.pinned ? 'var(--color-primary)' : 'var(--color-danger)'}; box-shadow: 0 1px 2px rgba(0,0,0,0.02);`;
    
    if (occ.fase === 'Nota Interna') {
      cardStyle = `background: #fffbeb !important; border-radius: 6px; padding: 12px; border: 1px solid #fde68a !important; border-left: 4px solid #f59e0b !important; box-shadow: 2px 2px 6px rgba(0,0,0,0.05) !important; position: relative !important;`;
      
      html += `
      <div style="${cardStyle}">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 4px;">
          <div style="display:flex; align-items:center; flex-wrap:wrap; gap: 6px;">
            <span style="font-size: 0.8rem;">Por: <strong>${occ.author}</strong></span>
            <span style="background: rgba(0,0,0,0.05); padding: 2px 6px; border-radius: 4px; font-size: 0.65rem; color: var(--color-text-muted);"><i data-lucide="sticky-note" style="width: 10px; height: 10px; display: inline-block; margin-right: 2px;"></i>Nota interna</span>
          </div>
          <div style="display:flex; align-items:center; gap: 8px;">
            ${judActionsHtml}
            <span style="font-size:0.7rem; color:var(--color-text-muted); white-space:nowrap;">${dateStr}</span>
            <button type="button" onclick="window.togglePinJudicialOccurrence('${occ.date}')" style="background:none; border:none; padding:0; cursor:pointer; color:${occ.pinned ? 'var(--color-primary)' : '#cbd5e1'}; transition: color 0.2s; margin-top:-2px;" title="${occ.pinned ? 'Desfixar' : 'Fixar'}">
               <i data-lucide="paperclip" style="width: 16px; height: 16px;"></i>
            </button>
          </div>
        </div>
      `;
    } else {
      let titleIcon = '';
      html += `
      <div style="${cardStyle}">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px;">
          <div>
            <div style="font-size: 0.85rem; font-weight: 700; color: #1e293b; display: flex; align-items: center;">${titleIcon}${occ.fase} ${occ.pinned ? `<span style="background: var(--color-primary); color: white; padding: 2px 6px; border-radius: 4px; font-size: 0.65rem; margin-left: 8px; display: inline-flex; align-items: center; gap: 2px;"><i data-lucide="pin" style="width: 10px; height: 10px;"></i> Fixado</span>` : ''}</div>
            <div style="font-size: 0.7rem; color: #64748b; margin-top: 2px;">Por ${occ.author} em ${dateStr}</div>
          </div>
          <div style="display: flex; align-items: center; gap: 12px;">
            ${judActionsHtml}
            <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 6px;">
              ${prazoHtml}
            </div>
          </div>
        </div>
      `;
    }
    
    let editInfoHtml = '';
    if (occ.lastEdit) {
      editInfoHtml += `<div style="font-size: 0.65rem; color: var(--color-text-muted); margin-top: 4px; font-style: italic;">(Editado por ${occ.lastEdit.author} em ${new Date(occ.lastEdit.date).toLocaleString('pt-BR')})</div>`;
    }
    if (occ.lastErrata) {
      editInfoHtml += `<div style="font-size: 0.65rem; color: var(--color-text-muted); margin-top: 4px; font-style: italic;">(Errata por ${occ.lastErrata.author} em ${new Date(occ.lastErrata.date).toLocaleString('pt-BR')})</div>`;
    }
    
    html += `
        <div style="font-size: 0.85rem; color: #334155; white-space: pre-wrap; ${occ.fase === 'Nota Interna' ? 'line-height: 24px; background-image: repeating-linear-gradient(transparent, transparent 23px, rgba(245,158,11,0.2) 23px, rgba(245,158,11,0.2) 24px); background-attachment: local; padding: 0 4px;' : 'line-height: 1.5;'}">${pastTextsHtml}${mainText}</div>
        ${editInfoHtml}
        ${isCancelled ? cancelInfoHtml : ''}
        ${(occ.fase === 'Nota Interna' && occ.replies && occ.replies.length > 0) ? `
          <div style="margin-top: 8px; border-left: 2px solid rgba(245,158,11,0.4); padding-left: 8px; margin-left: 4px; display: flex; flex-direction: column; gap: 6px;">
            ${occ.replies.map(reply => `
              <div style="background: rgba(255,255,255,0.6); padding: 6px 8px; border-radius: 4px; border: 1px solid rgba(0,0,0,0.05); font-size: 0.75rem;">
                <div style="display: flex; justify-content: space-between; margin-bottom: 2px; font-size: 0.7rem; color: var(--color-text-muted);">
                  <strong>${reply.author}</strong> <span>${new Date(reply.date).toLocaleString('pt-BR')}</span>
                </div>
                <div style="color: #1e293b; white-space: pre-wrap;">${reply.text}</div>
              </div>
            `).join('')}
          </div>
        ` : ''}
        ${(repetirBtnHtml || pinBtnHtml) ? `
        <div class="timeline-card-footer" style="margin-top: 10px; display:flex; justify-content:flex-end; align-items:center;">
          <div>
            ${repetirBtnHtml}
            ${pinBtnHtml}
          </div>
        </div>
        ` : ''}
        ${(occ.fase === 'Nota Interna') ? `
        <div id="reply-container-${occ.date}" style="display: none; margin-top: 8px; padding-top: 8px; border-top: 1px dashed rgba(0,0,0,0.1);">
          <textarea id="reply-input-${occ.date}" rows="2" style="width: 100%; border: 1px solid var(--color-border); border-radius: 4px; padding: 6px; font-size: 0.75rem; resize: none; margin-bottom: 4px;" placeholder="Digite sua resposta..."></textarea>
          <div style="text-align: right;">
            <button class="btn btn-primary btn-sm" style="padding: 2px 8px; font-size: 0.7rem;" onclick="window.addReplyToOccurrence('${occ.date}', true)">Enviar</button>
          </div>
        </div>
        ` : ''}
      </div>
    `;
  });
  
  html += `</div>`;
  container.innerHTML = html;
  
  if (typeof lucide !== 'undefined') lucide.createIcons();
};

window.errataJudicialOcc = function(customerId, occDate) {
  const list = AppState.judNotes[customerId] || [];
  const occ = list.find(x => x.date === occDate);
  if (!occ) return;
  
  const currentUser = window.currentUser || (AppState.currentUser ? AppState.currentUser.name : null) || "OPERADOR";
  if (!currentUser || (occ.author !== currentUser && currentUser !== "Operador")) {
    alert("Apenas o autor da ocorrência pode inserir uma errata.");
    return;
  }
  
  const newText = prompt("Insira a Errata (o texto anterior ficará tachado):");
  if (newText === null) return;
  if (!newText.trim()) {
    alert("O texto não pode ser vazio.");
    return;
  }
  
  occ.pastTexts = occ.pastTexts || [];
  occ.pastTexts.push(occ.text);
  occ.text = newText.trim().toUpperCase();
  occ.lastErrata = { author: currentUser, date: new Date().toISOString() };
  localStorage.setItem("crm_moura_jud_notes", JSON.stringify(AppState.judNotes));
  window.renderJudicialTimeline();
};

window.editJudicialOccReal = function(customerId, occDate) {
  const list = AppState.judNotes[customerId] || [];
  const occ = list.find(x => x.date === occDate);
  if (!occ) return;
  
  const elapsedMs = new Date() - new Date(occ.date);
  if (elapsedMs > 24 * 60 * 60 * 1000) {
      alert("O prazo de 24 horas para edição expirou. Utilize a Errata.");
      return;
  }
  
  const currentUser = window.currentUser || (AppState.currentUser ? AppState.currentUser.name : null) || "OPERADOR";
  if (!currentUser || (occ.author !== currentUser && currentUser !== "Operador")) {
    alert("Apenas o autor da ocorrência pode editá-la.");
    return;
  }
  
  const newText = prompt("Edite o texto da ocorrência:", occ.text);
  if (newText === null) return;
  if (!newText.trim()) {
    alert("O texto da ocorrência não pode ser vazio.");
    return;
  }
  
  occ.text = newText.trim().toUpperCase();
  occ.lastEdit = { author: currentUser, date: new Date().toISOString() };
  localStorage.setItem("crm_moura_jud_notes", JSON.stringify(AppState.judNotes));
  window.renderJudicialTimeline();
};

window.cancelJudicialOcc = function(customerId, occDate) {
  const list = AppState.judNotes[customerId] || [];
  const occ = list.find(x => x.date === occDate);
  if (!occ) return;
  
  const elapsedMs = new Date() - new Date(occ.date);
  if (elapsedMs > 24 * 60 * 60 * 1000) {
      alert("O prazo de 24 horas expirou. Não é mais possível apagar ou cancelar esta ocorrência.");
      return;
  }
  
  const currentUser = window.currentUser || (AppState.currentUser ? AppState.currentUser.name : null) || "OPERADOR";
  if (!currentUser || (occ.author !== currentUser && currentUser !== "Operador")) {
    alert("Apenas o autor da ocorrência pode cancelá-la.");
    return;
  }
  
  const confirmDelete = confirm("Tem certeza que deseja apagar/excluir esta ocorrência judicial?");
  if (!confirmDelete) return;
  
  AppState.judNotes[customerId] = list.filter(x => x.date !== occDate);
  
  localStorage.setItem("crm_moura_jud_notes", JSON.stringify(AppState.judNotes));
  window.renderJudicialTimeline();
};

window.togglePinJudicialOccurrence = function(occDate) {
  const list = AppState.judNotes[AppState.selectedCustomerId] || [];
  const occ = list.find(x => x.date === occDate);
  if (!occ) return;
  
  occ.pinned = !occ.pinned;
  localStorage.setItem("crm_moura_jud_notes", JSON.stringify(AppState.judNotes));
  window.renderJudicialTimeline();
};

window.repeatJudicialOcc = function(index) {
  const list = AppState.judNotes[AppState.selectedCustomerId] || [];
  const occ = list[index];
  if (!occ) return;
  
  const faseEl = document.getElementById("jud-fase");
  const noteEl = document.getElementById("jud-note-text");
  
  if (faseEl) {
      faseEl.value = occ.fase || '';
      if (window.handleJudFaseChange) window.handleJudFaseChange(faseEl);
  }
  if (noteEl) {
      noteEl.value = occ.text || '';
      noteEl.focus();
  }
};

window.openAnexosClienteModal = function(customerId) {
  // Limpar a aba comercial de anexos para evitar conflito de IDs
  const otherRoot = document.getElementById('anexos-root');
  if (otherRoot) otherRoot.innerHTML = '';

  const modal = document.getElementById('anexos-cliente-modal');
  if (modal) {
      modal.style.display = 'flex';
      modal.classList.add('active');
  }
  
  if (typeof AnexosApp !== 'undefined') {
    window.anexosTargetId = 'anexos-cliente-root';
    AnexosApp.resetAndRender();
    
    AnexosState.contexto = 'Cliente';
    AnexosState.idCliente = customerId;
    
    // Buscar costCenterId e saleId
    let costCenterId = null;
    let saleId = null;

    if (typeof AppState !== 'undefined') {
        saleId = AppState.selectedSaleId;
        if (!saleId && AppState.sales && AppState.sales.length > 0) {
            saleId = AppState.sales[0].id;
        }
        
        if (saleId && AppState.sales) {
            const sale = AppState.sales.find(s => String(s.id) === String(saleId) || String(s.receivableBillId) === String(saleId));
            if (sale) {
                costCenterId = sale.enterpriseId || sale.costCenterId;
                saleId = sale.id; // ensure we use the actual sales-contract ID
            }
        }

        if (!costCenterId) {
            let clientMatch = null;
            if (AppState.dashboardList) clientMatch = AppState.dashboardList.find(c => String(c.customerId) === String(customerId));
            if (!clientMatch && AppState.subjudiceList) clientMatch = AppState.subjudiceList.find(c => String(c.customerId) === String(customerId));
            if (!clientMatch && AppState.customers) clientMatch = AppState.customers.find(c => String(c.id) === String(customerId));
            if (clientMatch) costCenterId = clientMatch.costCenterId;
        }
    }

    if (costCenterId) {
        AnexosState.contexto = 'Ambos';
        AnexosState.cc = costCenterId;
        AnexosState.ccName = typeof getPrimaryCostCenter === 'function' ? getPrimaryCostCenter(costCenterId) : costCenterId;
    }

    renderAnexosModule();

    if (saleId) {
        const port = (window.location.port === "5500" || !window.location.port) ? "3000" : window.location.port;
        const host = (window.location.hostname === "" || window.location.hostname === "127.0.0.1") ? "localhost" : window.location.hostname;
        
        // Buscar o contrato de venda diretamente pelo ID e não pela unidade
        fetch(`http://${host}:${port}/sienge-proxy/sales-contracts/${saleId}`, {
            headers: { 'Authorization': typeof getBasicAuthHeader === 'function' ? getBasicAuthHeader() : '' }
        }).then(res => res.json()).then(async (mainC) => {
            if (!mainC || mainC.status === 'CANCELED' || !mainC.id) return;
            
            const mainCust = mainC.salesContractCustomers?.find(cust => cust.main === true) || mainC.salesContractCustomers?.[0] || {};
            let fmtDate = '';
            if (mainC.contractDate || mainC.saleDate) {
                const rawD = mainC.contractDate || mainC.saleDate;
                const parts = rawD.split('-');
                if (parts.length === 3) fmtDate = `${parts[2]}/${parts[1]}/${parts[0]}`;
                else fmtDate = rawD;
            }

            AnexosState.activeContract = {
                id: mainC.id,
                contractNumber: mainC.contractNumber || mainC.number || mainC.id,
                customerName: mainCust.name || mainCust.customerName || mainC.customerName || 'Cliente',
                contractDate: fmtDate,
                customerId: mainCust.customerId || mainCust.id,
                customers: mainC.salesContractCustomers || []
            };

            // Disparar o handleClientMatch nativo do App se disponível, para popular demais informações
            if (typeof SiengeApiService !== 'undefined' && SiengeApiService.getCustomerDetails) {
                SiengeApiService.getCustomerDetails(customerId).then(res => {
                    const cm = { id: customerId, ...res };
                    if (AnexosApp.handleClientMatch) AnexosApp.handleClientMatch(cm);
                }).catch(() => {});
            }

            // Tentar carregar anexos locais do IndexedDB primeiro
            let localFiles = null;
            try {
                if (typeof AnexosDB !== 'undefined') {
                    localFiles = await AnexosDB.load(customerId);
                }
            } catch (e) {
                console.error("Erro ao ler do IndexedDB", e);
            }

            // Buscar anexos do contrato encontrado
            const attRes = await fetch(`http://${host}:${port}/sienge-proxy/sales-contracts/${mainC.id}/attachments`, {
                headers: { 'Authorization': typeof getBasicAuthHeader === 'function' ? getBasicAuthHeader() : '' }
            }).catch(() => null);
            
            // Buscar anexos do cliente
            const custAttRes = await fetch(`http://${host}:${port}/sienge-proxy/customers/${customerId}/attachments`, {
                headers: { 'Authorization': typeof getBasicAuthHeader === 'function' ? getBasicAuthHeader() : '' }
            }).catch(() => null);
            
            let allAttachments = [];
            
            if (attRes && attRes.ok) {
                const attData = await attRes.json();
                allAttachments = allAttachments.concat(attData.results || []);
            }
            
            if (custAttRes && custAttRes.ok) {
                const custAttData = await custAttRes.json();
                if (custAttData.results && custAttData.results.length > 0) {
                    const custResults = custAttData.results.map(a => ({...a, isCustomerAttachment: true, customerId: customerId}));
                    allAttachments = allAttachments.concat(custResults);
                }
            }
            
            if (allAttachments.length > 0 || (attRes && attRes.ok)) {
                AnexosState.contractAttachments = allAttachments;
                renderAnexosModule();
                
                if (localFiles && localFiles.length > 0) {
                    // Já existem arquivos salvos localmente (tagueados)
                    // Necessário regerar o previewUrl pois a URL de blob morre com a sessão
                    localFiles.forEach(f => {
                        if (f.file && ['jpg', 'jpeg', 'png', 'pdf'].includes(f.ext)) {
                            try { f.previewUrl = URL.createObjectURL(f.file); } catch(e) {}
                        }
                    });
                    
                    AnexosState.files = localFiles;
                    AnexosState.importedContracts.add(mainC.id);
                    if (AnexosApp.renderFilesList) AnexosApp.renderFilesList();
                } else if (AnexosState.contractAttachments.length > 0) {
                    // Automaticamente importar anexos do Sienge (primeira vez)
                    AnexosApp.importarAnexosDoContrato();
                }
            }
        }).catch(err => {
            console.error("Erro ao carregar detalhes do contrato e anexos no modal:", err);
        });
    } else {
        if (typeof SiengeApiService !== 'undefined' && SiengeApiService.getCustomerDetails) {
            SiengeApiService.getCustomerDetails(customerId).then(res => {
                const cm = { id: customerId, ...res };
                if (AnexosApp.handleClientMatch) {
                     AnexosApp.handleClientMatch(cm);
                }
            }).catch(() => {});
        }
    }
  } else {
     alert('Módulo de anexos não está carregado.');
  }
};

