document.addEventListener('DOMContentLoaded', () => {
  const urlParams = new URLSearchParams(window.location.search);
  const action = urlParams.get('action');
  const customerId = urlParams.get('customerId');
  const occDate = urlParams.get('occDate');
  
  if (action && customerId && occDate) {
    window.history.replaceState({}, document.title, window.location.pathname);
    
    setTimeout(() => {
      if (typeof window.viewCustomerDetails === 'function') {
        window.viewCustomerDetails(customerId);
        
        setTimeout(() => {
          if (typeof window.switchCustomerTab === 'function') {
            window.switchCustomerTab('tab-ocorrencias');
          }
          
          const textEl = document.getElementById("note-text");
          if (textEl) {
             const d = new Date(occDate);
             const dateStr = d.toLocaleDateString('pt-BR') + ' ' + d.toLocaleTimeString('pt-BR', {hour: '2-digit', minute:'2-digit'});
             
             if (action === 'approve_occurrence') {
                textEl.value = `Referente à ocorrência de ${dateStr}:\nDE ACORDO / APROVADO. `;
             } else if (action === 'request_info_occurrence') {
                textEl.value = `Referente à ocorrência de ${dateStr}:\nSOLICITO MAIS INFORMAÇÕES: `;
             }
             textEl.focus();
             
             const canalSelect = document.getElementById("note-canal");
             if (canalSelect) canalSelect.value = "Nota interna";
             
             if (typeof window.validateOccurrenceForm === 'function') {
               window.validateOccurrenceForm();
             }
          }
        }, 1500);
      }
    }, 1500);
  }
});

