// -------------------------------------------------------
// Máscara de Moeda pt-BR para campos do Distrato
// -------------------------------------------------------

function applyDistratoCurrencyMask() {
  // Formata enquanto o usuário digita
  function maskCurrencyInput(el) {
    // Pega apenas dígitos
    let digits = el.value.replace(/\D/g, '');
    if (!digits) { el.value = ''; return; }

    // Trata como centavos: últimos 2 dígitos = centavos
    // Mas se o usuário não digitou suficiente, mostra sem centavos
    // Estratégia: acumular dígitos e formatar como X.XXX,XX
    let number = parseInt(digits, 10);
    // Divide por 100 para ter os centavos
    let formatted = (number / 100).toLocaleString('pt-BR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
    el.value = formatted;
  }

  document.querySelectorAll('.currency-mask').forEach(el => {
    // Remover listener anterior se existir
    if (el._currencyMaskHandler) {
      el.removeEventListener('input', el._currencyMaskHandler);
      el.removeEventListener('keydown', el._currencyKeydownHandler);
    }

    el._currencyMaskHandler = function() {
      maskCurrencyInput(this);
      calculateDistrato();
    };

    el._currencyKeydownHandler = function(e) {
      // Permitir: backspace, delete, tab, arrows, home, end
      const allowed = ['Backspace','Delete','Tab','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'];
      if (allowed.includes(e.key)) return;
      // Só deixar dígitos
      if (!/^[0-9]$/.test(e.key)) {
        e.preventDefault();
      }
    };

    // Remover o oninput inline para não chamar calculateDistrato duas vezes
    el.removeAttribute('oninput');
    el.addEventListener('keydown', el._currencyKeydownHandler);
    el.addEventListener('input', el._currencyMaskHandler);

    // Inicializar com 0,00 se ainda for "0"
    if (el.value === '0' || el.value === '') {
      el.value = '0,00';
    } else {
      // Se já tiver valor numérico, formatar
      let num = parseFloat(el.value) || 0;
      el.value = num.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }
  });
}

// Expor para ser chamado ao abrir a tela do distrato
window.applyDistratoCurrencyMask = applyDistratoCurrencyMask;

window.toggleCostCenters = function(className, element) {
    const rows = document.querySelectorAll('.' + className);
    let isHidden = true;
    if (rows.length > 0) {
        isHidden = rows[0].style.display === 'none';
    }
    
    rows.forEach(row => {
        row.style.display = isHidden ? 'table-row' : 'none';
    });

    const icon = element.querySelector('i');
    if (icon) {
        if (isHidden) {
            icon.setAttribute('data-lucide', 'chevron-down');
        } else {
            icon.setAttribute('data-lucide', 'chevron-right');
        }
        if (typeof lucide !== 'undefined' && lucide.createIcons) {
            lucide.createIcons({
                nameAttr: 'data-lucide',
                attrs: {
                    class: "lucide",
                    "stroke-width": 2,
                    stroke: "currentColor",
                    fill: "none",
                    "stroke-linecap": "round",
                    "stroke-linejoin": "round"
                }
            });
        }
    }
};

