window.initAdvFiltersUI = function() {
    // Dropdown toggles
    document.addEventListener('click', (e) => {
        const btn = e.target.closest('.adv-dropdown-btn');
        if (btn) {
            const list = btn.nextElementSibling;
            if (list && list.classList.contains('adv-dropdown-list')) {
                const wasActive = list.classList.contains('active');
                document.querySelectorAll('.adv-dropdown-list').forEach(l => l.classList.remove('active'));
                document.querySelectorAll('.adv-dropdown-btn').forEach(b => b.classList.remove('open'));
                if (!wasActive) {
                    list.classList.add('active');
                    btn.classList.add('open');
                }
            }
        } else if (!e.target.closest('.adv-dropdown-container')) {
            // Click outside
            document.querySelectorAll('.adv-dropdown-list').forEach(l => l.classList.remove('active'));
            document.querySelectorAll('.adv-dropdown-btn').forEach(b => b.classList.remove('open'));
        }
    });

    // Pills logic
    document.querySelectorAll('.adv-pills-group').forEach(group => {
        group.addEventListener('click', (e) => {
            const pill = e.target.closest('.adv-pill');
            if (!pill) return;
            
            const isMulti = ['adv-pills-lotes', 'adv-pills-aging', 'adv-pills-parcelas', 'adv-pills-dueday', 'adv-pills-idade', 'adv-pills-pagamento-recente'].includes(group.id);
            const val = pill.dataset.value;

            if (isMulti) {
                if (val === '') {
                    // Clicked 'Todos' -> clear others
                    group.querySelectorAll('.adv-pill').forEach(p => p.classList.remove('active'));
                    pill.classList.add('active');
                } else {
                    // Clicked specific option
                    pill.classList.toggle('active');
                    group.querySelector('.adv-pill[data-value=""]')?.classList.remove('active');
                    // If none selected, select 'Todos'
                    if (group.querySelectorAll('.adv-pill.active').length === 0) {
                        group.querySelector('.adv-pill[data-value=""]')?.classList.add('active');
                    }
                }
            } else {
                // Single select
                group.querySelectorAll('.adv-pill').forEach(p => p.classList.remove('active'));
                pill.classList.add('active');
            }
        });
    });

    document.addEventListener('input', (e) => {
        if (e.target.matches('.adv-dropdown-search input')) {
            const term = e.target.value.toLowerCase();
            const list = e.target.closest('.adv-dropdown-list');
            list.querySelectorAll('.adv-dropdown-item').forEach(item => {
                if (item.classList.contains('hidden-by-empresa')) return; // Ignora se foi ocultado pelo filtro de empresa
                const text = item.querySelector('span').innerText.toLowerCase();
                item.style.display = text.includes(term) ? 'flex' : 'none';
            });
        }
    });

    // Ações de Marcar/Desmarcar Todos nos Dropdowns
    document.addEventListener('click', (e) => {
        if (e.target.matches('.btn-check-all')) {
            const list = e.target.closest('.adv-dropdown-list');
            if(!list) return;
            const items = list.querySelectorAll('.adv-dropdown-item');
            let changed = false;
            items.forEach(item => {
                if (item.style.display !== 'none' && !item.classList.contains('hidden-by-empresa')) {
                    const cb = item.querySelector('input[type="checkbox"]');
                    if (cb && !cb.checked) {
                        cb.checked = true;
                        changed = true;
                    }
                }
            });
            if (changed) {
                const firstCb = list.querySelector('.adv-dropdown-item input[type="checkbox"]');
                if (firstCb) firstCb.dispatchEvent(new Event('change', { bubbles: true }));
            }
        }
        
        if (e.target.matches('.btn-uncheck-all')) {
            const list = e.target.closest('.adv-dropdown-list');
            if(!list) return;
            const items = list.querySelectorAll('.adv-dropdown-item');
            let changed = false;
            items.forEach(item => {
                if (item.style.display !== 'none' && !item.classList.contains('hidden-by-empresa')) {
                    const cb = item.querySelector('input[type="checkbox"]');
                    if (cb && cb.checked) {
                        cb.checked = false;
                        changed = true;
                    }
                }
            });
            if (changed) {
                const firstCb = list.querySelector('.adv-dropdown-item input[type="checkbox"]');
                if (firstCb) firstCb.dispatchEvent(new Event('change', { bubbles: true }));
            }
        }
    });
    
    document.addEventListener('change', (e) => {
        if (e.target.matches('.adv-dropdown-item input[type="checkbox"]')) {
            const container = e.target.closest('.adv-dropdown-container');
            if (container) {
                const count = container.querySelectorAll('input[type="checkbox"]:checked').length;
                const btnSpan = container.querySelector('.adv-dropdown-btn span');
                if (btnSpan) {
                    btnSpan.innerText = count > 0 ? `${count} selecionado(s)` : 'Todos';
                }
            }

            // Lógica de cruzamento avançado (Empresa <-> CCusto <-> Cidade)
            if (container && ['adv-dropdown-empresa-container', 'adv-dropdown-ccusto-container', 'adv-dropdown-cidade-container'].includes(container.id)) {
                
                const selEmp = Array.from(document.querySelectorAll('#adv-dropdown-empresa-container input[type="checkbox"]:checked')).map(cb => cb.value);
                const selCc = Array.from(document.querySelectorAll('#adv-dropdown-ccusto-container input[type="checkbox"]:checked')).map(cb => cb.value);
                const selCid = Array.from(document.querySelectorAll('#adv-dropdown-cidade-container input[type="checkbox"]:checked')).map(cb => cb.value);

                const validEmp = new Set();
                const validCc = new Set();
                const validCid = new Set();

                if (window.advFiltersMapLinks) {
                    window.advFiltersMapLinks.forEach(link => {
                        const matchEmp = selEmp.length === 0 || selEmp.includes(link.empresa);
                        const matchCc = selCc.length === 0 || selCc.includes(link.ccusto);
                        const matchCid = selCid.length === 0 || selCid.includes(link.cidade);

                        if (matchCc && matchCid) validEmp.add(link.empresa);
                        if (matchEmp && matchCid) validCc.add(link.ccusto);
                        if (matchEmp && matchCc) validCid.add(link.cidade);
                    });
                }

                const updateContainer = (id, validSet) => {
                    const c = document.getElementById(id);
                    if (!c) return;
                    const searchInput = c.querySelector('.adv-dropdown-search input');
                    const term = searchInput ? searchInput.value.toLowerCase() : '';
                    
                    c.querySelectorAll('.adv-dropdown-item').forEach(item => {
                        const val = item.querySelector('input').value;
                        const isGloballyEmpty = selEmp.length === 0 && selCc.length === 0 && selCid.length === 0;
                        
                        if (isGloballyEmpty || validSet.has(val)) {
                            item.classList.remove('hidden-by-empresa');
                            const text = item.querySelector('span').innerText.toLowerCase();
                            item.style.display = (!term || text.includes(term)) ? 'flex' : 'none';
                        } else {
                            item.classList.add('hidden-by-empresa');
                            item.style.display = 'none';
                            const cb = item.querySelector('input');
                            if (cb.checked) {
                                cb.checked = false;
                                const btnSpan = c.querySelector('.adv-dropdown-btn span');
                                const count = c.querySelectorAll('input[type="checkbox"]:checked').length;
                                if (btnSpan) btnSpan.innerText = count > 0 ? `${count} selecionado(s)` : 'Todos';
                            }
                        }
                    });
                };

                updateContainer('adv-dropdown-empresa-container', validEmp);
                updateContainer('adv-dropdown-ccusto-container', validCc);
                updateContainer('adv-dropdown-cidade-container', validCid);
            }
        }
    });
};

