window.applyAdvFilters = async function(keepOpen = false) {
    const getPills = (id) => {
        const active = Array.from(document.querySelectorAll(`#${id} .adv-pill.active`));
        return active.map(p => p.dataset.value).filter(v => v !== '');
    };
    
    window.advFilters.lotes = getPills('adv-pills-lotes');
    window.advFilters.aging = getPills('adv-pills-aging');
    window.advFilters.parcelas = getPills('adv-pills-parcelas');
    window.advFilters.dueday = getPills('adv-pills-dueday');
    window.advFilters.idade = getPills('adv-pills-idade');
    
    const contatoPills = getPills('adv-pills-contato');
    window.advFilters.contato = contatoPills.length > 0 ? contatoPills[0] : '';
    
    const statusJuridicoEl = document.getElementById('adv-select-juridico');
    window.advFilters.statusJuridico = statusJuridicoEl ? statusJuridicoEl.value : 'TODOS';
    
    const retroMesesEl = document.getElementById('adv-input-retroativo-meses');
    window.advFilters.retroMeses = retroMesesEl ? retroMesesEl.value : '90';

    
    const zpPills = getPills('adv-pills-zeropaid');
    window.advFilters.zeropaid = zpPills.length > 0 ? zpPills[0] : 'TODOS';
    
    window.advFilters.pagamentoRecente = getPills('adv-pills-pagamento-recente');

    const getDropdown = (containerId) => {
        const container = document.getElementById(containerId);
        if(!container) return [];
        return Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value);
    };

    window.advFilters.cidade = getDropdown('adv-dropdown-cidade-container');
    window.advFilters.empresa = getDropdown('adv-dropdown-empresa-container');
    window.advFilters.ccusto = getDropdown('adv-dropdown-ccusto-container');
    window.advFilters.operador = getDropdown('adv-dropdown-operador-container');
    
    // Sincronizar visualmente as abas de operador (filtros rápidos)
    if (window.advFilters.operador.length === 1) {
        const selectedOp = window.advFilters.operador[0];
        let found = false;
        document.querySelectorAll(".operator-tab-btn:not(#btn-adv-filters)").forEach(b => {
            if (b.getAttribute("data-operator") === selectedOp) {
                b.classList.add("active");
                found = true;
            } else {
                b.classList.remove("active");
            }
        });
        if (typeof activeOperatorFilter !== 'undefined') {
            activeOperatorFilter = found ? selectedOp : "TODOS";
        } else {
            window.activeOperatorFilter = found ? selectedOp : "TODOS";
        }
    } else {
        document.querySelectorAll(".operator-tab-btn:not(#btn-adv-filters)").forEach(b => b.classList.remove("active"));
        if (window.advFilters.operador.length === 0) {
            const todosBtn = document.querySelector('.operator-tab-btn[data-operator="TODOS"]');
            if (todosBtn) todosBtn.classList.add("active");
        }
        if (typeof activeOperatorFilter !== 'undefined') {
            activeOperatorFilter = "TODOS";
        } else {
            window.activeOperatorFilter = "TODOS";
        }
    }

    let count = window.advFilters.lotes.length + window.advFilters.aging.length + window.advFilters.parcelas.length + 
                window.advFilters.dueday.length + window.advFilters.idade.length + window.advFilters.cidade.length + window.advFilters.empresa.length + window.advFilters.ccusto.length;
    if (window.advFilters.contato) count++;
    if (window.advFilters.subjudice && window.advFilters.subjudice !== 'TODOS') count++;
    if (window.advFilters.pagamentoRecente && window.advFilters.pagamentoRecente.length > 0) count++;

    let badgeId = 'adv-filters-badge';
    if (window.currentAdvFilterContext === 'subjudice') badgeId = 'subjudice-adv-filters-badge';
    else if (window.currentAdvFilterContext === 'zeropaid') badgeId = 'zeropaid-adv-filters-badge';
    
    const badge = document.getElementById(badgeId);
    if (badge) {
        if (count > 0) {
            badge.style.display = 'inline-flex';
            badge.innerText = count;
        } else {
            badge.style.display = 'none';
        }
    }
    
    // --- LÓGICA DE CONSUMO DA API PARA O FILTRO PAGAMENTO RECENTE ---
    const applyBtn = document.querySelector('button[onclick="applyAdvFilters()"]') || document.querySelector('.adv-filters-footer .btn-primary');
    
    // A busca na API agora acontece em SEGUNDO PLANO na função window.prefetchRecentPayments()!
    // Aqui no applyAdvFilters, não faremos mais requisições lentas, será tudo instantâneo.
    
    if (!keepOpen) {
        window.closeAdvFiltersModal();
    }
    
    const activeTabPane = document.querySelector('.tab-pane[style*="display: block"]');
    if (activeTabPane && activeTabPane.id === 'tab-zeropaid') {
        if (typeof loadZeroPaidTab === 'function') loadZeroPaidTab();
    } else {
        if (typeof loadDashboardData === 'function') loadDashboardData();
    }
};

window.hasPrefetchedPayments = false;
window.prefetchRecentPayments = async function(forceRefresh = false) {
    if (window.hasPrefetchedPayments && !forceRefresh) return;
    
    // Se o paidMap já foi populado pelo Firebase Cache e tem dados, NÃO BUSQUE de novo!
    if (!forceRefresh && window.advFilters && window.advFilters.paidMap && window.advFilters.paidMap.size > 0) {
        window.hasPrefetchedPayments = true;
        return;
    }
    
    console.log("Iniciando busca de pagamentos recentes em segundo plano...");
    if (!window.rawClientList) return;
    window.hasPrefetchedPayments = true;
    
    window.advFilters = window.advFilters || {};
    window.advFilters.paymentsLoading = true;
    if (typeof loadDashboardData === 'function') loadDashboardData();
    
    try {
        const uniqueCompanies = new Set();
        window.rawClientList.forEach(c => {
            if (c.companyId) uniqueCompanies.add(String(c.companyId));
        });
        
        const today = new Date();
        const dateChunks = [];
        // Quebra em blocos de 6 dias para garantir que nunca passará do limite de 500 do Sienge
        for (let i = 0; i < 30; i += 6) {
            const chunkEnd = new Date(today);
            chunkEnd.setDate(chunkEnd.getDate() - i);
            
            const chunkStart = new Date(today);
            let daysToSubtract = i + 5;
            if (daysToSubtract > 29) daysToSubtract = 29;
            chunkStart.setDate(chunkStart.getDate() - daysToSubtract);
            
            dateChunks.push({
                start: chunkStart.toISOString().split('T')[0],
                end: chunkEnd.toISOString().split('T')[0]
            });
        }
        
        window.advFilters.paidMap = window.advFilters.paidMap || new Map();
        
        // Faz a busca empresa por empresa, bloco por bloco, de forma sequencial para não travar o navegador
        for (const companyId of uniqueCompanies) {
            for (const chunk of dateChunks) {
                try {
                    const res = await window.SiengeApiService.getBulkIncome(chunk.start, chunk.end, companyId);
                    if (res && res.data) {
                        res.data.forEach(item => {
                            const bId = item.billReceivableId || item.receivableBillId || item.billId || item.documentId || item.invoiceId || item.installmentId || item.id;
                            if (bId) {
                                let validDates = [];
                                
                                // No Sienge Bulk Data, 'receipts' vem na raiz do objeto do título (diferente da API v1 padrão)
                                if (item.receipts && Array.isArray(item.receipts)) {
                                    item.receipts.forEach(receipt => {
                                        if (String(receipt.operationTypeId) === "2" && receipt.paymentDate) {
                                            validDates.push(receipt.paymentDate);
                                        }
                                    });
                                }
                                
                                // Fallback caso ainda venha aninhado (só por garantia)
                                if (item.receiptsCategories && Array.isArray(item.receiptsCategories)) {
                                    item.receiptsCategories.forEach(cat => {
                                        if (cat.receipts && Array.isArray(cat.receipts)) {
                                            cat.receipts.forEach(receipt => {
                                                if (String(receipt.operationTypeId) === "2" && receipt.paymentDate) {
                                                    validDates.push(receipt.paymentDate);
                                                }
                                            });
                                        }
                                    });
                                }
                                

                                
                                validDates.forEach(dateStr => {
                                    if (dateStr) {
                                        const cleanDate = typeof dateStr === 'string' ? dateStr.substring(0, 10) : dateStr;
                                        const rDate = new Date(cleanDate + 'T12:00:00');
                                        const todayDate = new Date();
                                        todayDate.setHours(0,0,0,0);
                                        const rAtMidnight = new Date(rDate);
                                        rAtMidnight.setHours(0,0,0,0);
                                        const diffTime = todayDate - rAtMidnight;
                                        const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
                                        
                                        const currentVal = window.advFilters.paidMap.get(String(bId));
                                        if (currentVal === undefined || diffDays < currentVal) {
                                            window.advFilters.paidMap.set(String(bId), diffDays);
                                        }
                                    }
                                });
                            }
                        });
                    }
                } catch (err) {
                    console.error("Erro na busca de pagamentos em segundo plano", err);
                }
            }
        }
        console.log("Busca de pagamentos recentes em segundo plano finalizada com sucesso!");
        if (window.SiengeApiService && typeof window.SiengeApiService.updateCachePaidMap === 'function' && window.advFilters && window.advFilters.paidMap) {
            let paidMapStr = null;
            try { paidMapStr = JSON.stringify(Array.from(window.advFilters.paidMap.entries())); } catch(e){}
            if (paidMapStr) {
                window.SiengeApiService.updateCachePaidMap(paidMapStr);
            }
        }
    } catch (e) {
        console.error("Erro geral na busca de pagamentos em segundo plano:", e);
    } finally {
        if (window.advFilters) window.advFilters.paymentsLoading = false;
        if (typeof loadDashboardData === 'function') loadDashboardData();
    }
};

window.clearAdvFilters = function() {
    const defaultState = {
        lotes: [], aging: [], parcelas: [], dueday: [], idade: [],
        cidade: [], empresa: [], ccusto: [], operador: [],
        contato: '', statusJuridico: 'TODOS', retroMeses: '90', zeropaid: 'TODOS', pagamentoRecente: []
    };
    if (window.currentAdvFilterContext === 'fila') window.advFiltersFila = defaultState;
    else if (window.currentAdvFilterContext === 'subjudice') window.advFiltersSubjudice = defaultState;
    else if (window.currentAdvFilterContext === 'zeropaid') window.advFiltersZeroPaid = defaultState;
    window.advFilters = defaultState;
    
    document.querySelectorAll('.adv-pills-group').forEach(group => {
        group.querySelectorAll('.adv-pill').forEach(p => p.classList.remove('active'));
        const defaultPill = group.querySelector('.adv-pill[data-value=""]') || group.querySelector('.adv-pill[data-value="TODOS"]');
        if (defaultPill) defaultPill.classList.add('active');
    });
    
    const statusJuridicoEl = document.getElementById('adv-select-juridico');
    if (statusJuridicoEl) {
        statusJuridicoEl.value = 'TODOS';
        const event = new Event('change');
        statusJuridicoEl.dispatchEvent(event);
    }
    const retroMesesEl = document.getElementById('adv-input-retroativo-meses');
    if (retroMesesEl) retroMesesEl.value = '90';
    
    document.querySelectorAll('.adv-dropdown-container input[type="checkbox"]').forEach(cb => cb.checked = false);
    document.querySelectorAll('.adv-dropdown-btn span').forEach(s => s.innerText = 'Todos');

    window.applyAdvFilters(true);
};

