window.exportFilteredToExcel = function() {
    try {
        if (!window.clientList || window.clientList.length === 0) {
            alert('Não há dados filtrados para exportar.');
            return;
        }

        if (typeof XLSX === 'undefined') {
            alert('A biblioteca XLSX não foi carregada corretamente. Atualize a página e tente novamente.');
            return;
        }

        const formatCpfCnpj = (val) => {
            if (!val) return "";
            let str = String(val).replace(/\D/g, "");
            if (str.length === 11) return str.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, "$1.$2.$3-$4");
            if (str.length === 14) return str.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, "$1.$2.$3/$4-$5");
            return val;
        };

        const getEmpreendimento = (id) => {
            if (!window.AppState || !window.AppState.cachedCostCenters) return String(id);
            const cc = window.AppState.cachedCostCenters.find(ccObj => String(ccObj.id) === String(id));
            return cc ? `${id} - ${cc.name}` : String(id);
        };

        const rowsData = window.clientList.map(c => {
            let phonesStr = "";
            let emailsStr = "";
            
            // Buscar contatos no GlobalCustomerCache
            let customerData = null;
            if (window.GlobalCustomerCache && window.GlobalCustomerCache.data) {
                customerData = window.GlobalCustomerCache.data.find(cust => String(cust.customerId) === String(c.customerId) || String(cust.id) === String(c.customerId));
            }
            if (!customerData && window.AppState && window.AppState.customers) {
                customerData = window.AppState.customers[c.customerId];
            }
            
            let documentStr = formatCpfCnpj(c.cpfCnpj || "");
            if (customerData && !c.cpfCnpj) {
                documentStr = formatCpfCnpj(customerData.cpfCnpj || customerData.document || customerData.cpf || customerData.cnpj || "");
            }
            
            if (customerData) {
                // E-mails
                if (customerData.email && customerData.email !== 'N/D') {
                    emailsStr = customerData.email;
                }
                if (customerData.emails && Array.isArray(customerData.emails)) {
                    const uniqueEmails = Array.from(new Set(customerData.emails.map(e => e.email).filter(Boolean)));
                    if (uniqueEmails.length > 0) emailsStr = uniqueEmails.join("\n");
                }
                
                // Telefones
                if (customerData.phones && Array.isArray(customerData.phones) && customerData.phones.length > 0) {
                    const uniquePhones = Array.from(new Set(customerData.phones.map(p => {
                        let num = p.areaCode ? `(${String(p.areaCode).replace(/^0+/, '')}) ${p.number || p.phoneNumber}` : (p.number || p.phoneNumber);
                        if (!num) return null;
                        const isMain = p.principal === true || p.isPrincipal === true || p.main === true || p.isMain === true || (p.type && String(p.type).toLowerCase().includes('principal'));
                        if (isMain) num = '* ' + num;
                        return num;
                    }).filter(Boolean)));
                    
                    if (uniquePhones.length > 0) {
                        if (!uniquePhones.some(p => p.startsWith('*'))) {
                            uniquePhones[0] = '* ' + uniquePhones[0];
                        }
                        phonesStr = uniquePhones.join("\n");
                    }
                } else if (customerData.phone && customerData.phone !== 'N/D') {
                    phonesStr = '* ' + customerData.phone;
                }
            }

            return {
                "Empresa ID": c.companyId,
                "Cliente ID": c.customerId,
                "Nome do Cliente": c.customerName,
                "CPF/CNPJ": documentStr, // Enviando como texto limpo pra evitar perda de zero
                "Títulos": Array.isArray(c.billIds) ? c.billIds.join(" ; ") : c.billIds,
                "Empreendimento ID": getPrimaryCostCenter(c.costCenterId),
                "Unidade": c.unitName || '',
                "Operador": c.assignedOperator,
                "Dias em Atraso (Máx)": c.maxDaysDelay,
                "Parcelas Vencidas": c.billCount || (Array.isArray(c.billIds) ? c.billIds.length : 1),
                "Valor Atrasado (R$)": (typeof c.overdueValue === 'number' ? c.overdueValue : 0) + (typeof c.overdueCharges === 'number' ? c.overdueCharges : 0),
                "Sub judice": (c.subjudice === "S" || c.subjudice === true) ? "S" : "N",
                "Telefones": phonesStr,
                "E-mails": emailsStr
            };
        });

        // Converte o array de objetos para uma aba do SheetJS
        const ws = XLSX.utils.json_to_sheet(rowsData);

        const range = XLSX.utils.decode_range(ws['!ref']);
        
        // Ajuste automático de largura das colunas
        ws['!cols'] = [
            { wch: 10 }, // Empresa ID
            { wch: 10 }, // Cliente ID
            { wch: 40 }, // Nome do Cliente
            { wch: 18 }, // CPF/CNPJ
            { wch: 20 }, // Títulos
            { wch: 18 }, // Empreendimento ID
            { wch: 10 }, // Unidade
            { wch: 15 }, // Operador
            { wch: 12 }, // Dias em Atraso (Máx)
            { wch: 12 }, // Parcelas Vencidas
            { wch: 16 }, // Valor Atrasado (R$)
            { wch: 10 }, // Sub judice
            { wch: 25 }, // Telefones
            { wch: 30 }  // E-mails
        ];

        // Aplica formato monetário, bordas em toda a grade, e cabeçalho cinza/negrito
        for (let R = range.s.r; R <= range.e.r; ++R) {
            for (let C = range.s.c; C <= range.e.c; ++C) {
                const cellAddress = XLSX.utils.encode_cell({ r: R, c: C });
                let cell = ws[cellAddress];
                
                // Cria a célula caso esteja vazia no range para garantir a grade
                if (!cell) {
                    cell = { t: 's', v: '' };
                    ws[cellAddress] = cell;
                }
                
                // Configuração base de bordas e alinhamento
                cell.s = {
                    border: {
                        top: { style: "thin", color: { rgb: "000000" } },
                        bottom: { style: "thin", color: { rgb: "000000" } },
                        left: { style: "thin", color: { rgb: "000000" } },
                        right: { style: "thin", color: { rgb: "000000" } }
                    },
                    alignment: { vertical: "center", wrapText: true },
                    font: { name: "Calibri", sz: 11 }
                };

                // Configuração do Cabeçalho
                if (R === 0) {
                    cell.s.fill = { fgColor: { rgb: "E2E8F0" } }; // Cinza suave
                    cell.s.font.bold = true;
                    cell.s.font.color = { rgb: "1E293B" };
                    cell.s.alignment.horizontal = "center";
                }
                
                // Configuração da coluna de Valor (index 10) nas linhas de dados
                if (R > 0 && C === 10 && cell.t === 'n') {
                    cell.z = '#,##0.00'; // Formato numérico nativo
                }
            }
        }

        // Criar o arquivo virtual e inserir a aba
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Fila de Cobrança");

        // Fazer o download mágico como .xlsx real!
        const dateStr = new Date().toISOString().split('T')[0];
        XLSX.writeFile(wb, `relatorio_cobranca_${dateStr}.xlsx`);
        
    } catch (error) {
        console.error("Erro na exportação XLSX:", error);
        alert("Ocorreu um erro ao gerar o Excel: " + error.message);
    }
};

