// Função dinâmica para buscar operadores do localStorage "crm_users"
window.getDynamicOperators = function(type = 'all') {
    let users = [];
    try {
        const saved = localStorage.getItem('crm_users');
        if (saved) {
            users = JSON.parse(saved);
        } else {
            // Fallback
            users = [
                { sienge_user: "LETICIA.OLIVEIRA", profile_name: "OPERADOR COBRANÇA", operator_type: "interno" },
                { sienge_user: "MICHELLE.VIEIRA", profile_name: "OPERADOR COBRANÇA", operator_type: "interno" },
                { sienge_user: "MICHELLE.PEREIRA", profile_name: "OPERADOR COBRANÇA", operator_type: "interno" },
                { sienge_user: "THAIANE.CORDEIRO", profile_name: "OPERADOR COBRANÇA", operator_type: "externo" }
            ];
        }
    } catch(e) {
        console.error("Erro ao buscar operadores", e);
    }
    
    // Filtrar por perfil Operador, excluindo Pagadoria e inativos
    let ops = users.filter(u => {
        if (!u.profile_name) return false;
        const prof = u.profile_name.toUpperCase();
        const nome = (u.name || "").toUpperCase();
        // É operador
        if (!prof.includes("OPERADOR")) return false;
        // Não é inativo
        if (u.status === "INATIVO") return false;
        // Não é pagadoria
        if (prof.includes("PAGADORIA")) return false;
        // Fallback: se o nome for Danielle, bloquear também, conforme solicitado
        if (nome.includes("DANIELLE MARTINS") || nome === "DANIELLE") return false;
        
        return true;
    });
    
    // Filtrar tipo se especificado
    if (type === 'interno') {
        ops = ops.filter(u => u.operator_type === 'interno');
    }
    
    // Retornar os nomes formatados
    return ops.map(u => {
        if (u.sienge_user) return String(u.sienge_user).replace(/\./g, ' ').toUpperCase();
        return String(u.name).toUpperCase();
    });
};


