// Função que baixa configurações na inicialização
window.syncGlobalConfigFromFirebase = async function() {
    if (sessionStorage.getItem('crm_synced_global')) return; // já sincronizou nesta sessão
    
    try {
        if (!window.firebaseDb || !window.firebaseCollections) return;
        const snap = await window.firebaseCollections.getDocs(window.firebaseCollections.collection(window.firebaseDb, "config"));
        let globalData = null;
        snap.forEach(d => { if (d.id === "global") globalData = d.data(); });
        
        if (globalData) {
            let changed = false;
            // Sincroniza chaves fixas
            window.SYNC_KEYS.forEach(k => {
                if (globalData[k] && globalData[k] !== localStorage.getItem(k)) {
                    _originalSetItem.call(localStorage, k, globalData[k]);
                    changed = true;
                }
            });
            // Sincroniza permissões dinâmicas
            Object.keys(globalData).forEach(k => {
                if (k.startsWith("crm_perms_") && globalData[k] !== localStorage.getItem(k)) {
                    _originalSetItem.call(localStorage, k, globalData[k]);
                    changed = true;
                }
            });
            
            sessionStorage.setItem('crm_synced_global', 'true');
            if (changed) {
                console.log("[Firebase] Configurações alteradas recebidas da nuvem. Recarregando a página para aplicar...");
                location.reload();
            } else {
                console.log("[Firebase] Configurações globais já estão atualizadas com a nuvem.");
            }
        }
    } catch(e) {
        console.error("Erro na sincronização:", e);
    }
};

window.forceUploadLocalConfig = async function() {
    try {
        let payload = {};
        window.SYNC_KEYS.forEach(key => {
            const val = localStorage.getItem(key);
            if (val) payload[key] = val;
        });
        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (k.startsWith("crm_perms_")) {
                payload[k] = localStorage.getItem(k);
            }
        }
        
        if (!window.firebaseDb || !window.firebaseCollections) throw new Error("Firebase não inicializado.");
        const docRef = window.firebaseCollections.doc(window.firebaseDb, "config", "global");
        await window.firebaseCollections.setDoc(docRef, payload);
        alert("✔️ SUCESSO!\n\nSuas configurações globais, regras de atribuição, personalização de empresas e acessos foram enviadas para a Nuvem!\n\nAgora o resto da equipe já vai puxar essas configurações.");
    } catch(e) {
        alert("Erro ao enviar: " + e.message);
    }
};

// Sincronização em lote de todas as notas (ocorrências, agenda, jud) para o Firebase
window.syncAllNotesToFirebase = async function() {
    const statusEl = document.getElementById('firebase-sync-status');
    const setStatus = (msg, color) => {
        if (statusEl) { statusEl.textContent = msg; statusEl.style.color = color || '#64748b'; }
        console.log('[SyncNotes]', msg);
    };
    
    if (!window.firebaseDb || !window.firebaseCollections) {
        setStatus('❌ Firebase não está inicializado. Tente novamente em alguns instantes.', '#ef4444');
        return;
    }
    
    try {
        setStatus('🔄 Sincronizando notas de clientes...', '#1d4ed8');
        
        // 1. customer_notes (ocorrências e promessas)
        const notes = window.AppState && window.AppState.notes ? window.AppState.notes : 
                      (JSON.parse(localStorage.getItem('crm_moura_notes') || '{}'));
        const noteKeys = Object.keys(notes);
        let uploadedNotes = 0;
        
        for (const custId of noteKeys) {
            if (notes[custId] && notes[custId].length > 0) {
                const docRef = window.firebaseCollections.doc(window.firebaseDb, 'customer_notes', String(custId));
                await window.firebaseCollections.setDoc(docRef, { notes: notes[custId] }, { merge: false });
                uploadedNotes++;
                if (uploadedNotes % 10 === 0) {
                    setStatus(`🔄 Sincronizando notas... ${uploadedNotes}/${noteKeys.length} clientes`, '#1d4ed8');
                }
                // Small delay to avoid rate limiting
                if (uploadedNotes % 5 === 0) await new Promise(r => setTimeout(r, 200));
            }
        }
        
        // 2. jud_notes
        setStatus('🔄 Sincronizando notas judiciais...', '#1d4ed8');
        const judNotes = window.AppState && window.AppState.judNotes ? window.AppState.judNotes :
                         (JSON.parse(localStorage.getItem('crm_moura_jud_notes') || '{}'));
        let uploadedJud = 0;
        for (const custId of Object.keys(judNotes)) {
            if (judNotes[custId] && judNotes[custId].length > 0) {
                const docRef = window.firebaseCollections.doc(window.firebaseDb, 'jud_notes', String(custId));
                await window.firebaseCollections.setDoc(docRef, { notes: judNotes[custId] }, { merge: false });
                uploadedJud++;
                if (uploadedJud % 5 === 0) await new Promise(r => setTimeout(r, 200));
            }
        }
        
        // 3. agenda_personal_notes
        setStatus('🔄 Sincronizando notas pessoais de agenda...', '#1d4ed8');
        const personalNotes = JSON.parse(localStorage.getItem('crm_agenda_personal_notes') || '{}');
        for (const key of Object.keys(personalNotes)) {
            if (personalNotes[key] && personalNotes[key].length > 0) {
                const docRef = window.firebaseCollections.doc(window.firebaseDb, 'agenda_personal_notes', key);
                await window.firebaseCollections.setDoc(docRef, { notes: personalNotes[key] }, { merge: false });
                await new Promise(r => setTimeout(r, 100));
            }
        }
        
        // 4. agenda_recurring_notes
        const recurringNotes = JSON.parse(localStorage.getItem('crm_agenda_recurring_notes') || '{}');
        for (const key of Object.keys(recurringNotes)) {
            if (recurringNotes[key] && recurringNotes[key].length > 0) {
                const docRef = window.firebaseCollections.doc(window.firebaseDb, 'agenda_recurring_notes', key);
                await window.firebaseCollections.setDoc(docRef, { notes: recurringNotes[key] }, { merge: false });
                await new Promise(r => setTimeout(r, 100));
            }
        }
        
        const msg = `✅ Sincronização concluída! ${uploadedNotes} clientes com ocorrências, ${uploadedJud} com notas judiciais enviados para o Firebase.`;
        setStatus(msg, '#16a34a');
        setTimeout(() => alert(msg + '\n\nAtualize a página na Vercel para ver os dados.'), 100);
        
    } catch(e) {
        const errMsg = '❌ Erro na sincronização: ' + e.message;
        setStatus(errMsg, '#ef4444');
        console.error('[SyncNotes] Erro:', e);
    }
};

// --- INTERCEPTADOR PARA FIREBASE ---
// Captura as chamadas de localStorage.setItem e envia pro Firebase
const _originalSetItem = localStorage.setItem;
localStorage.setItem = function(key, value) {
    _originalSetItem.call(this, key, value);
    
    // Tratamento exclusivo de anotações (mantém a lógica anterior)
    if (key === "crm_moura_notes" && window.saveNotesToFirebase) {
        if (window._fbSyncTimeout) clearTimeout(window._fbSyncTimeout);
        window._fbSyncTimeout = setTimeout(() => {
            if (window.AppState && window.AppState.selectedCustomerId) {
                window.saveNotesToFirebase(window.AppState.selectedCustomerId);
            } else {
                window.saveNotesToFirebase(null); // salvar tudo
            }
        }, 300);
    }

    if (key === "crm_moura_jud_notes" && window.saveJudNotesToFirebase) {
        if (window._fbJudSyncTimeout) clearTimeout(window._fbJudSyncTimeout);
        window._fbJudSyncTimeout = setTimeout(() => {
            if (window.AppState && window.AppState.selectedCustomerId) {
                window.saveJudNotesToFirebase(window.AppState.selectedCustomerId);
            } else {
                window.saveJudNotesToFirebase(null);
            }
        }, 300);
    }

    if ((key === "crm_agenda_personal_notes" || key === "crm_agenda_recurring_notes") && window.saveAgendaNotesToFirebase) {
        if (window._fbAgendaSyncTimeout) clearTimeout(window._fbAgendaSyncTimeout);
        window._fbAgendaSyncTimeout = setTimeout(() => {
            window.saveAgendaNotesToFirebase();
        }, 300);
    }
    
    // Tratamento de Configurações Globais
    if ((window.SYNC_KEYS && window.SYNC_KEYS.includes(key)) || key.startsWith("crm_perms_")) {
        if (window._fbConfigTimeout) clearTimeout(window._fbConfigTimeout);
        window._fbConfigTimeout = setTimeout(async () => {
            if (window.firebaseDb && window.firebaseCollections) {
                try {
                    let payload = {};
                    window.SYNC_KEYS.forEach(k => {
                        const v = localStorage.getItem(k);
                        if (v) payload[k] = v;
                    });
                    for (let i = 0; i < localStorage.length; i++) {
                        const k = localStorage.key(i);
                        if (k.startsWith("crm_perms_")) {
                            payload[k] = localStorage.getItem(k);
                        }
                    }
                    const docRef = window.firebaseCollections.doc(window.firebaseDb, "config", "global");
                    await window.firebaseCollections.setDoc(docRef, payload, { merge: true });
                    console.log("[Firebase] Upload automático: Configurações globais atualizadas na nuvem.");
                } catch(e) {
                    console.error("Erro ao salvar configs na nuvem:", e);
                }
            }
        }, 1500); // 1.5s debounce para não sobrecarregar em edições em lote
    }
};
// ---------------- SHARE AGENDA MODAL ----------------
window.openShareAgendaNoteModal = function(srcKey, originalIndex, isRecurring) {
    window._currentShareNoteKey = srcKey;
    window._currentShareNoteIdx = originalIndex;
    window._currentShareNoteRecurring = isRecurring;
    
    let allNotes = {};
    try {
        const storeKey = isRecurring ? 'crm_agenda_recurring_notes' : 'crm_agenda_personal_notes';
        allNotes = JSON.parse(localStorage.getItem(storeKey) || '{}');
    } catch(e) {}
    
    const note = allNotes[srcKey] ? allNotes[srcKey][originalIndex] : null;
    if(!note) return;
    
    const sharedWith = note.sharedWith || [];
    const modalBody = document.getElementById("share-agenda-users-list");
    
    if(modalBody) {
        let html = '';
        const crmUsers = JSON.parse(localStorage.getItem('crm_users') || '[]');
        const currentUserEmail = (window.AppState && window.AppState.currentUser && window.AppState.currentUser.email) ? window.AppState.currentUser.email.toLowerCase() : "";
        
        crmUsers.forEach(u => {
            if(u.status === 'ATIVO' && u.email && u.email.toLowerCase() !== currentUserEmail) {
                const checked = sharedWith.includes(u.email.toLowerCase()) ? 'checked' : '';
                html += `
                  <label style="display:flex; align-items:center; gap:10px; padding:8px; border:1px solid #e2e8f0; border-radius:4px; margin-bottom:5px; cursor:pointer;" onmouseenter="this.style.background='#f1f5f9'" onmouseleave="this.style.background='none'">
                     <input type="checkbox" class="share-user-chk" value="${u.email.toLowerCase()}" ${checked} style="width:16px;height:16px;accent-color:var(--color-primary);">
                     <span style="font-size:0.9rem; color:#1e293b; font-weight:500;">${u.name} (${u.email})</span>
                  </label>
                `;
            }
        });
        
        if(html === '') html = '<p style="font-size:0.85rem; color:#64748b; text-align:center;">Não há outros operadores para compartilhar.</p>';
        modalBody.innerHTML = html;
    }
    document.getElementById("share-agenda-modal").style.display = "flex";
};

window.closeShareAgendaModal = function() {
    document.getElementById("share-agenda-modal").style.display = "none";
};

window.saveShareAgendaNote = function() {
    const isRecurring = window._currentShareNoteRecurring;
    const storeKey = isRecurring ? 'crm_agenda_recurring_notes' : 'crm_agenda_personal_notes';
    const allNotes = JSON.parse(localStorage.getItem(storeKey) || '{}');
    if(!window._currentShareNoteKey || window._currentShareNoteIdx === undefined) return;
    if(!allNotes[window._currentShareNoteKey]) return;
    const note = allNotes[window._currentShareNoteKey][window._currentShareNoteIdx];
    if(!note) return;
    
    const chks = document.querySelectorAll(".share-user-chk:checked");
    const sharedWith = Array.from(chks).map(c => c.value);
    
    note.sharedWith = sharedWith;
    localStorage.setItem(storeKey, JSON.stringify(allNotes));
    
    if (typeof window.saveAgendaNotesToFirebase === 'function') {
        window.saveAgendaNotesToFirebase();
    }
    
    window.closeShareAgendaModal();
    if(window.renderAgendaPersonalNotes) window.renderAgendaPersonalNotes();
};

window.exportAgendaToExcel = function() {
    const tableBody = document.getElementById("agenda-selected-day-body");
    if (!tableBody || tableBody.querySelectorAll('tr').length === 0 || tableBody.innerHTML.includes('Nenhum compromisso')) {
        alert("Não há dados na agenda para exportar.");
        return;
    }

    const rows = Array.from(tableBody.querySelectorAll("tr"));
    
    // Header
    let csvContent = "\\uFEFF"; // BOM para acentuação no Excel
    csvContent += "Status;Cliente/Unidade;Lembrete/Resumo;R$ Atualizado;Ultimo Contato;Registro\\n";

    rows.forEach(row => {
        const cols = Array.from(row.querySelectorAll("td"));
        if (cols.length < 6) return;
        
        let status = cols[0].textContent.trim();
        if (cols[0].querySelector('.lucide-clock')) status = 'Pendente';
        else if (cols[0].querySelector('.lucide-check-circle')) status = 'Resolvido';
        else if (cols[0].querySelector('.lucide-x-circle')) status = 'Cancelado';

        const clienteUnidade = cols[1].textContent.replace(/\s+/g, ' ').trim().replace(/;/g, ',');
        const lembreteResumo = cols[2].textContent.replace(/\s+/g, ' ').trim().replace(/;/g, ',');
        const valorRaw = cols[3].textContent.replace(/\s+/g, ' ').trim();
        const valor = valorRaw.replace('R$', '').trim().replace(/;/g, '');
        const ultimoContato = cols[4].textContent.replace(/\s+/g, ' ').trim().replace(/;/g, ',');
        const registro = cols[5].textContent.replace(/\s+/g, ' ').trim().replace(/;/g, ',');

        csvContent += `"${status}";"${clienteUnidade}";"${lembreteResumo}";"${valor}";"${ultimoContato}";"${registro}"\n`;
    });

    const dateStr = document.getElementById("selected-agenda-date-str")?.textContent || "agenda";
    const opSelect = document.getElementById("agenda-operator-select");
    let opStr = opSelect ? opSelect.value : "Todos";
    opStr = opStr === "Todos" ? "Todos_Operadores" : opStr.replace(/\s+/g, '_');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Agenda_${opStr}_${dateStr.replace(/\//g, '-')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};
